const parseCsvEnvTokens = (value = "") =>
  String(value || "")
    .split(",")
    .map((entry) => String(entry || "").trim())
    .filter(Boolean);

const normalizeEmailToken = (value = "") => String(value || "").trim().toLowerCase();
const normalizeUidToken = (value = "") =>
  String(value || "")
    .trim()
    .replace(/[^a-zA-Z0-9_-]/g, "")
    .slice(0, 180);

const SUPER_ADMIN_EMAILS = new Set(
  parseCsvEnvTokens(process.env.SUPER_ADMIN_EMAILS || SUPER_ADMIN_EMAIL_DEFAULT)
    .map(normalizeEmailToken)
    .filter(Boolean)
);
const SUPER_ADMIN_UIDS = new Set(
  parseCsvEnvTokens(process.env.SUPER_ADMIN_UIDS || "")
    .map(normalizeUidToken)
    .filter(Boolean)
);
const SUPER_ADMIN_UID_CACHE = new Map();
const SUPER_ADMIN_UID_CACHE_TTL_MS = 10 * 60 * 1000;

const nowMs = () => Date.now();

const normalizeYouTubeSearchQuery = (value = "") =>
  String(value || "").trim().toLowerCase().replace(/\s+/g, " ");

const buildYouTubeSearchIntentKey = (value = "") => {
  const uniqueTokens = [...new Set(
    String(value || "")
      .toLowerCase()
      .replace(/&/g, " and ")
      .replace(/[^a-z0-9]+/g, " ")
      .split(" ")
      .map((token) => token.trim())
      .filter((token) => token && !YOUTUBE_SEARCH_INTENT_STOPWORDS.has(token))
  )];
  if (!uniqueTokens.length) return "";
  return uniqueTokens.sort().join(" ");
};

const isSuperAdminUid = async (uid = "") => {
  const safeUid = normalizeUidToken(uid);
  if (!safeUid) return false;
  if (SUPER_ADMIN_UIDS.has(safeUid)) return true;
  const now = nowMs();
  const cached = SUPER_ADMIN_UID_CACHE.get(safeUid);
  if (cached && Number(cached.expiresAt || 0) > now) {
    return !!cached.value;
  }
  try {
    const userRecord = await admin.auth().getUser(safeUid);
    const email = normalizeEmailToken(userRecord?.email || "");
    const emailVerified = userRecord?.emailVerified === true;
    const allowed = !!email && emailVerified && SUPER_ADMIN_EMAILS.has(email);
    SUPER_ADMIN_UID_CACHE.set(safeUid, {
      value: allowed,
      expiresAt: now + SUPER_ADMIN_UID_CACHE_TTL_MS,
    });
    return allowed;
  } catch (_error) {
    SUPER_ADMIN_UID_CACHE.set(safeUid, {
      value: false,
      expiresAt: now + (60 * 1000),
    });
    return false;
  }
};

const readYoutubeSearchCache = (cacheKey = "") => {
  if (!cacheKey) return null;
  const entry = youtubeSearchCache.get(cacheKey);
  if (!entry) return null;
  if (Number(entry.expiresAtMs || 0) <= nowMs()) {
    youtubeSearchCache.delete(cacheKey);
    return null;
  }
  return Array.isArray(entry.items) ? entry.items : null;
};

const writeYoutubeSearchCache = (cacheKey = "", items = []) => {
  if (!cacheKey) return;
  youtubeSearchCache.set(cacheKey, {
    items: Array.isArray(items) ? items : [],
    expiresAtMs: nowMs() + YOUTUBE_SEARCH_CACHE_TTL_MS,
  });
  if (youtubeSearchCache.size <= YOUTUBE_SEARCH_CACHE_MAX_KEYS) return;
  const oldest = youtubeSearchCache.keys().next().value;
  if (oldest) youtubeSearchCache.delete(oldest);
};

const getYouTubeSearchPersistentCacheRef = (cacheKey = "") => {
  const safeCacheKey = String(cacheKey || "").trim();
  if (!safeCacheKey) return null;
  const docId = crypto.createHash("sha256").update(safeCacheKey).digest("hex");
  return admin
    .firestore()
    .collection("system_caches")
    .doc("youtube_search")
    .collection("queries")
    .doc(docId);
};

const readPersistedYoutubeSearchCache = async (cacheKey = "") => {
  const ref = getYouTubeSearchPersistentCacheRef(cacheKey);
  if (!ref) return null;
  try {
    const snap = await ref.get();
    if (!snap.exists) return null;
    const data = snap.data() || {};
    const expiresAtMs = Number(data.expiresAtMs || 0);
    if (!expiresAtMs || expiresAtMs <= nowMs()) return null;
    const items = Array.isArray(data.items) ? data.items : [];
    writeYoutubeSearchCache(cacheKey, items);
    return items;
  } catch (error) {
    console.warn("readPersistedYoutubeSearchCache failed", error?.message || error);
    return null;
  }
};

const primeYoutubeSearchCaches = async ({
  exactCacheKey = "",
  intentCacheKey = "",
  items = [],
  persistEmpty = false,
} = {}) => {
  const safeItems = Array.isArray(items) ? items : [];
  const writeTargets = [exactCacheKey].filter(Boolean);
  if (safeItems.length > 0 && intentCacheKey && intentCacheKey !== exactCacheKey) {
    writeTargets.push(intentCacheKey);
  }
  writeTargets.forEach((targetKey) => writeYoutubeSearchCache(targetKey, safeItems));
  const persistedTargets = persistEmpty
    ? [exactCacheKey].filter(Boolean)
    : writeTargets;
  await Promise.all(
    persistedTargets.map((targetKey) => writePersistedYoutubeSearchCache(targetKey, safeItems))
  );
};

const writePersistedYoutubeSearchCache = async (cacheKey = "", items = []) => {
  const ref = getYouTubeSearchPersistentCacheRef(cacheKey);
  if (!ref) return false;
  const safeItems = Array.isArray(items) ? items : [];
  const ttlMs = safeItems.length > 0
    ? YOUTUBE_SEARCH_PERSISTED_CACHE_TTL_MS
    : YOUTUBE_SEARCH_PERSISTED_EMPTY_CACHE_TTL_MS;
  try {
    await ref.set({
      cacheKey,
      items: safeItems,
      resultCount: safeItems.length,
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      updatedAtMs: nowMs(),
      expiresAtMs: nowMs() + ttlMs,
    }, { merge: true });
    return true;
  } catch (error) {
    console.warn("writePersistedYoutubeSearchCache failed", error?.message || error);
    return false;
  }
};

