const HOST_BACKGROUND_AUDIO_PLAYBACK_FIELDS = new Set(["type", "id", "title", "url", "status", "reason", "lastReportedAt"]);
const HOST_PERFORMANCE_SESSION_STRING_FIELDS = new Set(["playbackState", "completionReason"]);
const HOST_PERFORMANCE_SESSION_NUMBER_FIELDS = new Set([
  "playerReportedDurationSec",
  "playerPositionSec",
  "lastHeartbeatAtMs",
  "lastReportedAtMs",
  "playbackStartedAtMs",
  "pausedAtMs",
  "endedAtMs",
]);

const HOST_ROOM_DOTTED_KEY_RULES = [
  {
    pattern: /^announcement\.active$/,
    label: "announcement.active",
    validate: (value) => typeof value === "boolean",
  },
  {
    pattern: /^readyCheck\.active$/,
    label: "readyCheck.active",
    validate: (value) => typeof value === "boolean",
  },
  {
    pattern: /^bingoRevealed\.[A-Za-z0-9_-]+$/,
    label: "bingoRevealed.<slot>",
    validate: (value) => typeof value === "boolean",
  },
  {
    pattern: /^bingoSuggestions\.[A-Za-z0-9_-]+\.approvedAt$/,
    label: "bingoSuggestions.<slot>.approvedAt",
    validate: (value) =>
      value === null || isHostServerTimestampMarker(value) || isFiniteNumber(value),
  },
  {
    pattern: /^bingoSuggestions\.[A-Za-z0-9_-]+\.count$/,
    label: "bingoSuggestions.<slot>.count",
    validate: (value) => isFiniteNumber(value),
  },
  {
    pattern: /^bingoSuggestions\.[A-Za-z0-9_-]+\.lastAt$/,
    label: "bingoSuggestions.<slot>.lastAt",
    validate: (value) => value === null || isFiniteNumber(value) || isHostServerTimestampMarker(value),
  },
  {
    pattern: /^bingoSuggestions\.[A-Za-z0-9_-]+\.lastNote$/,
    label: "bingoSuggestions.<slot>.lastNote",
    validate: (value) => typeof value === "string" && value.length <= HOST_UPDATE_MAX_STRING_LENGTH,
  },
  {
    pattern: /^appleMusicPlayback\.status$/,
    label: "appleMusicPlayback.status",
    validate: (value) => typeof value === "string" && HOST_APPLE_PLAYBACK_STATUS_VALUES.has(value),
  },
  {
    pattern: /^appleMusicPlayback\.([A-Za-z0-9_-]+)$/,
    label: "appleMusicPlayback.<field>",
    validate: (value, match) => {
      const field = match?.[1] || "";
      if (HOST_APPLE_PLAYBACK_STRING_FIELDS.has(field)) return value === null || typeof value === "string";
      if (HOST_APPLE_PLAYBACK_NUMBER_FIELDS.has(field)) return value === null || isFiniteNumber(value);
      return false;
    },
  },
  {
    pattern: /^currentPerformanceSession\.([A-Za-z0-9_-]+)$/,
    label: "currentPerformanceSession.<field>",
    validate: (value, match) => {
      const field = match?.[1] || "";
      if (HOST_PERFORMANCE_SESSION_STRING_FIELDS.has(field)) return value === null || typeof value === "string";
      if (HOST_PERFORMANCE_SESSION_NUMBER_FIELDS.has(field)) return value === null || isFiniteNumber(value);
      return false;
    },
  },
  {
    pattern: /^gameData\.hostAssist$/,
    label: "gameData.hostAssist",
    validate: (value) => value === null || isPlainObject(value),
  },
  {
    pattern: /^gameData\.voiceTelemetry$/,
    label: "gameData.voiceTelemetry",
    validate: (value) => value === null || isPlainObject(value),
  },
];

const isPlainObject = (value) =>
  !!value && Object.prototype.toString.call(value) === "[object Object]";
const isFiniteNumber = (value) => typeof value === "number" && Number.isFinite(value);
const isBlockedKeyToken = (value = "") =>
  UPDATE_BLOCKED_PATH_TOKENS.has(value) || value.startsWith("__");
const isHostServerTimestampMarker = (value) =>
  isPlainObject(value)
    && Object.keys(value).length === 1
    && value[HOST_UPDATE_OP_FIELD] === HOST_UPDATE_SERVER_TIMESTAMP;
const isValidUpdatePathToken = (value = "") =>
  /^[A-Za-z0-9_-]{1,80}$/.test(value) && !isBlockedKeyToken(value);

const normalizeHostRoomSearchSources = (value = {}) => ({
  local: value?.local !== false,
  youtube: value?.youtube !== false,
  itunes: value?.itunes !== false,
});

const validateHostRoomUpdateValue = (value, depth = 0) => {
  if (depth > HOST_UPDATE_MAX_DEPTH) {
    throw new HttpsError("invalid-argument", "updates payload is nested too deeply.");
  }
  if (value === undefined) return;
  if (value === null) return;

  const valueType = typeof value;
  if (valueType === "string") {
    if (value.length > HOST_UPDATE_MAX_STRING_LENGTH) {
      throw new HttpsError("invalid-argument", "String update value is too large.");
    }
    return;
  }
  if (valueType === "boolean") return;
  if (valueType === "number") {
    if (!Number.isFinite(value)) {
      throw new HttpsError("invalid-argument", "Numeric update values must be finite.");
    }
    return;
  }

  if (Array.isArray(value)) {
    if (value.length > HOST_UPDATE_MAX_ARRAY_ITEMS) {
      throw new HttpsError("invalid-argument", "Array update value has too many items.");
    }
    value.forEach((entry) => validateHostRoomUpdateValue(entry, depth + 1));
    return;
  }

  if (!isPlainObject(value)) {
    throw new HttpsError("invalid-argument", "updates payload contains unsupported values.");
  }

  if (Object.prototype.hasOwnProperty.call(value, HOST_UPDATE_OP_FIELD)) {
    if (!isHostServerTimestampMarker(value)) {
      throw new HttpsError("invalid-argument", `Unsupported host update operation "${HOST_UPDATE_OP_FIELD}".`);
    }
    return;
  }

  const keys = Object.keys(value);
  if (keys.length > HOST_UPDATE_MAX_OBJECT_KEYS) {
    throw new HttpsError("invalid-argument", "Object update value has too many keys.");
  }
  keys.forEach((key) => {
    if (!isValidUpdatePathToken(key)) {
      throw new HttpsError("invalid-argument", `Invalid nested update key token: ${key}`);
    }
    validateHostRoomUpdateValue(value[key], depth + 1);
  });
};

const validateHostRoomUpdateType = (key, value) => {
  if (HOST_ROOM_TIMESTAMP_ROOT_KEYS.has(key)
    && !(value === null || isFiniteNumber(value) || isHostServerTimestampMarker(value))) {
    throw new HttpsError(
      "invalid-argument",
      `Room field "${key}" must be a finite number, server timestamp marker, or null.`,
    );
  }
  if (HOST_ROOM_BOOLEAN_ROOT_KEYS.has(key) && typeof value !== "boolean") {
    throw new HttpsError("invalid-argument", `Room field "${key}" must be a boolean.`);
  }
  if (HOST_ROOM_NUMBER_ROOT_KEYS.has(key) && !(value === null || isFiniteNumber(value))) {
    throw new HttpsError("invalid-argument", `Room field "${key}" must be a finite number or null.`);
  }
  if (HOST_ROOM_STRING_ROOT_KEYS.has(key) && !(value === null || typeof value === "string")) {
    throw new HttpsError("invalid-argument", `Room field "${key}" must be a string or null.`);
  }
  if (HOST_ROOM_ARRAY_ROOT_KEYS.has(key) && !(value === null || Array.isArray(value))) {
    throw new HttpsError("invalid-argument", `Room field "${key}" must be an array or null.`);
  }
  if (HOST_ROOM_OBJECT_OR_NULL_ROOT_KEYS.has(key) && !(value === null || isPlainObject(value))) {
    throw new HttpsError("invalid-argument", `Room field "${key}" must be an object or null.`);
  }

  if (key === "liveStageCameraMode" && !LIVE_STAGE_CAMERA_MODE_VALUES.has(value)) {
    throw new HttpsError(
      "invalid-argument",
      "Room field \"liveStageCameraMode\" must be off, full, or corner.",
    );
  }
  if (key === "liveStageCameraCorner" && !LIVE_STAGE_CAMERA_CORNER_VALUES.has(value)) {
    throw new HttpsError(
      "invalid-argument",
      "Room field \"liveStageCameraCorner\" has an unsupported corner.",
    );
  }

  if (key === "backgroundAudioPlayback" && value !== null) {
    const fields = Object.keys(value);
    if (!fields.length || fields.some((field) => !HOST_BACKGROUND_AUDIO_PLAYBACK_FIELDS.has(field))) {
      throw new HttpsError("invalid-argument", "Room field \"backgroundAudioPlayback\" contains unsupported fields.");
    }
    if (value.type !== "local_upload") {
      throw new HttpsError("invalid-argument", "Room field \"backgroundAudioPlayback.type\" must be local_upload.");
    }
    if (!HOST_BACKGROUND_AUDIO_PLAYBACK_STATUS_VALUES.has(value.status)) {
      throw new HttpsError("invalid-argument", "Room field \"backgroundAudioPlayback.status\" is invalid.");
    }
    ["id", "title", "url", "reason"].forEach((field) => {
      if (value[field] !== undefined && typeof value[field] !== "string") {
        throw new HttpsError("invalid-argument", `Room field "backgroundAudioPlayback.${field}" must be a string.`);
      }
    });
    if (value.lastReportedAt !== undefined && !isFiniteNumber(value.lastReportedAt)) {
      throw new HttpsError("invalid-argument", "Room field \"backgroundAudioPlayback.lastReportedAt\" must be a finite number.");
    }
  }

  if (key === "searchSources") {
    if (!isPlainObject(value)) {
      throw new HttpsError("invalid-argument", "Room field \"searchSources\" must be an object.");
    }
    Object.entries(value).forEach(([sourceKey, sourceValue]) => {
      if (!HOST_ROOM_SEARCH_SOURCE_KEYS.has(sourceKey)) {
        throw new HttpsError("invalid-argument", `Room field "searchSources.${sourceKey}" is not supported.`);
      }
      if (typeof sourceValue !== "boolean") {
        throw new HttpsError("invalid-argument", `Room field "searchSources.${sourceKey}" must be a boolean.`);
      }
    });
  }

  if (key === "bingoData") {
    const valid = value === null || isPlainObject(value) || Array.isArray(value);
    if (!valid) {
      throw new HttpsError("invalid-argument", "Room field \"bingoData\" must be an object, array, or null.");
    }
  }

  if (key === "featuredPhotoId") {
    const valid = value === null || typeof value === "string" || isFiniteNumber(value);
    if (!valid) {
      throw new HttpsError("invalid-argument", "Room field \"featuredPhotoId\" must be string, number, or null.");
    }
  }

  if (key === "highlightedTile") {
    const valid = value === null
      || typeof value === "string"
      || isFiniteNumber(value)
      || isPlainObject(value);
    if (!valid) {
      throw new HttpsError("invalid-argument", "Room field \"highlightedTile\" has an invalid value type.");
    }
  }
};

const matchDottedHostRoomRule = (key = "") =>
  HOST_ROOM_DOTTED_KEY_RULES.find((rule) => rule.pattern.test(key)) || null;

const decodeHostRoomUpdateValue = (value) => {
  if (Array.isArray(value)) {
    return value.map((entry) => decodeHostRoomUpdateValue(entry));
  }
  if (!isPlainObject(value)) return value;
  if (Object.prototype.hasOwnProperty.call(value, HOST_UPDATE_OP_FIELD)) {
    if (!isHostServerTimestampMarker(value)) {
      throw new HttpsError("invalid-argument", "Unsupported host update operation payload.");
    }
    return admin.firestore.FieldValue.serverTimestamp();
  }
  const next = {};
  Object.entries(value).forEach(([key, child]) => {
    next[key] = decodeHostRoomUpdateValue(child);
  });
  return next;
};

const normalizeHostRoomRequestMode = (value = "", allowSingerTrackSelect = false) => {
  const normalized = String(value || "").trim().toLowerCase();
  if (VALID_ROOM_REQUEST_MODES.has(normalized)) return normalized;
  return allowSingerTrackSelect
    ? ROOM_REQUEST_MODES.guestBackingOptional
    : ROOM_REQUEST_MODES.canonicalOpen;
};

const deriveHostAudienceBackingMode = ({
  audienceBackingMode = "",
  requestMode = "",
  allowSingerTrackSelect = false,
} = {}) => {
  const normalizedAudienceBackingMode = String(audienceBackingMode || "").trim().toLowerCase();
  if (VALID_ROOM_AUDIENCE_BACKING_MODES.has(normalizedAudienceBackingMode)) return normalizedAudienceBackingMode;
  const normalizedRequestMode = normalizeHostRoomRequestMode(requestMode, allowSingerTrackSelect);
  if (normalizedRequestMode === ROOM_REQUEST_MODES.playableOnly) {
    return ROOM_AUDIENCE_BACKING_MODES.canonicalPlusApprovedBackings;
  }
  if (normalizedRequestMode === ROOM_REQUEST_MODES.guestBackingOptional) {
    return ROOM_AUDIENCE_BACKING_MODES.canonicalPlusAudienceYoutube;
  }
  return ROOM_AUDIENCE_BACKING_MODES.canonicalOnly;
};

const deriveHostUnknownBackingPolicy = ({
  audienceBackingMode = "",
  unknownBackingPolicy = "",
  requestMode = "",
  allowSingerTrackSelect = false,
} = {}) => {
  const normalizedAudienceBackingMode = deriveHostAudienceBackingMode({
    audienceBackingMode,
    requestMode,
    allowSingerTrackSelect,
  });
  if (normalizedAudienceBackingMode === ROOM_AUDIENCE_BACKING_MODES.canonicalPlusApprovedBackings) {
    return ROOM_UNKNOWN_BACKING_POLICIES.blockUnknown;
  }
  if (normalizedAudienceBackingMode === ROOM_AUDIENCE_BACKING_MODES.canonicalOnly) {
    return ROOM_UNKNOWN_BACKING_POLICIES.requireReview;
  }
  const normalizedUnknownBackingPolicy = String(unknownBackingPolicy || "").trim().toLowerCase();
  if (VALID_ROOM_UNKNOWN_BACKING_POLICIES.has(normalizedUnknownBackingPolicy)) return normalizedUnknownBackingPolicy;
  return ROOM_UNKNOWN_BACKING_POLICIES.requireReview;
};

const deriveLegacyRequestModeFromAudienceBackingMode = (audienceBackingMode = "") => {
  const normalizedAudienceBackingMode = deriveHostAudienceBackingMode({ audienceBackingMode });
  if (normalizedAudienceBackingMode === ROOM_AUDIENCE_BACKING_MODES.canonicalPlusApprovedBackings) {
    return ROOM_REQUEST_MODES.playableOnly;
  }
  if (normalizedAudienceBackingMode === ROOM_AUDIENCE_BACKING_MODES.canonicalPlusAudienceYoutube) {
    return ROOM_REQUEST_MODES.guestBackingOptional;
  }
  return ROOM_REQUEST_MODES.canonicalOpen;
};

const deriveLegacyAllowSingerTrackSelect = (audienceBackingMode = "") => (
  deriveHostAudienceBackingMode({ audienceBackingMode }) === ROOM_AUDIENCE_BACKING_MODES.canonicalPlusAudienceYoutube
);

const deriveRoomWelcomeGrantMode = (accessMode = "") => (
  String(accessMode || "").trim().toLowerCase() === ROOM_AUDIENCE_JOIN_ACCESS_MODES.accountRequired
    ? ROOM_WELCOME_GRANT_MODES.oncePerRoomPerAccount
    : ROOM_WELCOME_GRANT_MODES.oncePerRoomPerDevice
);

const normalizeRoomAudienceJoinPolicy = (input = {}, fallback = {}) => {
  const fallbackAccessMode = VALID_ROOM_AUDIENCE_JOIN_ACCESS_MODES.has(String(fallback?.accessMode || "").trim().toLowerCase())
    ? String(fallback.accessMode).trim().toLowerCase()
    : ROOM_AUDIENCE_JOIN_ACCESS_MODES.anonymousAllowed;
  const accessMode = VALID_ROOM_AUDIENCE_JOIN_ACCESS_MODES.has(String(input?.accessMode || "").trim().toLowerCase())
    ? String(input.accessMode).trim().toLowerCase()
    : fallbackAccessMode;
  const explicitWelcomeGrantMode = String(input?.welcomeGrantMode || "").trim().toLowerCase();
  const fallbackWelcomeGrantMode = String(fallback?.welcomeGrantMode || "").trim().toLowerCase();
  const welcomeGrantMode = VALID_ROOM_WELCOME_GRANT_MODES.has(explicitWelcomeGrantMode)
    ? explicitWelcomeGrantMode
    : VALID_ROOM_WELCOME_GRANT_MODES.has(fallbackWelcomeGrantMode)
      ? fallbackWelcomeGrantMode
      : deriveRoomWelcomeGrantMode(accessMode);
  return {
    accessMode,
    welcomeGrantMode,
  };
};

const sanitizeAudienceJoinInstallId = (value = "") =>
  String(value || "")
    .trim()
    .replace(/[^a-zA-Z0-9_-]/g, "")
    .slice(0, 120);

const hashAudienceJoinInstallId = (installId = "") => {
  const safeInstallId = sanitizeAudienceJoinInstallId(installId);
  if (!safeInstallId) return "";
  return crypto.createHash("sha256").update(safeInstallId).digest("hex").slice(0, 24);
};

const resolveJoinParticipantIdentity = ({
  joinPolicy = {},
  uid = "",
  installId = "",
} = {}) => {
  const policy = normalizeRoomAudienceJoinPolicy(joinPolicy);
  const safeUid = normalizeUidToken(uid || "");
  const installIdHash = hashAudienceJoinInstallId(installId);
  if (policy.accessMode === ROOM_AUDIENCE_JOIN_ACCESS_MODES.anonymousAllowed && installIdHash) {
    return {
      participantKey: `anon_device:${installIdHash}`,
      participantIdentityType: "anon_device",
      participantInstallIdHash: installIdHash,
      welcomeGrantParticipantKey: policy.welcomeGrantMode === ROOM_WELCOME_GRANT_MODES.oncePerRoomPerAccount && safeUid
        ? `account:${safeUid}`
        : `anon_device:${installIdHash}`,
    };
  }
  return {
    participantKey: `account:${safeUid || installIdHash || "guest"}`,
    participantIdentityType: "account",
    participantInstallIdHash: installIdHash || null,
    welcomeGrantParticipantKey: policy.welcomeGrantMode === ROOM_WELCOME_GRANT_MODES.none
      ? ""
      : `account:${safeUid || installIdHash || "guest"}`,
  };
};

const VALID_PROVISION_AUDIENCE_ACCESS_LEVELS = new Set([
  "open",
  "account_required",
  "support_or_account",
  "disabled",
]);

const normalizeProvisionAudienceFeatureAccess = (input = {}) => {
  const features = isPlainObject(input?.features) ? input.features : {};
  const customEmoji = String(features.customEmoji || "open").trim().toLowerCase();
  return {
    features: {
      customEmoji: VALID_PROVISION_AUDIENCE_ACCESS_LEVELS.has(customEmoji) ? customEmoji : "open",
    },
  };
};

const normalizeProvisionAudienceBrandTheme = (input = {}) => {
  if (!isPlainObject(input)) return null;
  const appTitle = typeof input.appTitle === "string" ? input.appTitle.trim().slice(0, 64) : "";
  const primaryColor = typeof input.primaryColor === "string" ? input.primaryColor.trim().slice(0, 24) : "";
  const secondaryColor = typeof input.secondaryColor === "string" ? input.secondaryColor.trim().slice(0, 24) : "";
  const accentColor = typeof input.accentColor === "string" ? input.accentColor.trim().slice(0, 24) : "";
  if (!appTitle && !primaryColor && !secondaryColor && !accentColor) return null;
  return {
    appTitle: appTitle || "Audience app",
    primaryColor: primaryColor || "#00C4D9",
    secondaryColor: secondaryColor || "#EC4899",
    accentColor: accentColor || "#FACC15",
  };
};

const normalizeProvisionNightPresetPayload = (input = {}) => {
  if (!isPlainObject(input)) return null;
  const settings = isPlainObject(input.settings) ? input.settings : {};
  const queueSettings = isPlainObject(settings.queueSettings) ? settings.queueSettings : {};
  const gameDefaults = isPlainObject(settings.gameDefaults) ? settings.gameDefaults : {};
  const theme = normalizeProvisionAudienceBrandTheme(input.audienceBrandTheme || settings.audienceBrandTheme || {});
  return {
    id: normalizeProvisionPresetId(input.id || input.presetId || "custom") || "custom",
    label: typeof input.label === "string" ? input.label.trim().slice(0, 64) : "",
    description: typeof input.description === "string" ? input.description.trim().slice(0, 240) : "",
    basePresetId: normalizeProvisionPresetId(input.basePresetId || input.id || "casual") || "casual",
    isBuiltIn: input.isBuiltIn === true,
    brandingLogoUrl: typeof input.brandingLogoUrl === "string" ? input.brandingLogoUrl.trim().slice(0, 2048) : "",
    brandingOrbSkinUrl: typeof input.brandingOrbSkinUrl === "string" ? input.brandingOrbSkinUrl.trim().slice(0, 2048) : "",
    searchSources: {
      local: input?.searchSources?.local !== false,
      youtube: input?.searchSources?.youtube !== false,
      itunes: input?.searchSources?.itunes !== false,
    },
    audienceBrandTheme: theme,
    settings: {
      autoDj: settings.autoDj === true,
      autoBgMusic: settings.autoBgMusic === true,
      autoPlayMedia: settings.autoPlayMedia !== false,
      autoEndOnTrackFinish: settings.autoEndOnTrackFinish !== false,
      autoBonusEnabled: settings.autoBonusEnabled !== false,
      autoBonusPoints: clampNumber(settings.autoBonusPoints, 0, 1000, 25),
      autoDjDelaySec: clampNumber(settings.autoDjDelaySec, 2, 45, 10),
      oneMinuteMicEnabled: settings.oneMinuteMicEnabled === true,
      performanceProgressionMode: String(settings.performanceProgressionMode || "full_song").trim().toLowerCase() === "one_minute_mic" ? "one_minute_mic" : "full_song",
      oneMinuteMicOpeningWindowSec: clampNumber(settings.oneMinuteMicOpeningWindowSec, 15, 180, 60),
      oneMinuteMicVoteWindowSec: clampNumber(settings.oneMinuteMicVoteWindowSec, 5, 45, 12),
      showVisualizerTv: settings.showVisualizerTv === true,
      showLyricsTv: settings.showLyricsTv === true,
      showScoring: settings.showScoring === true,
      hypeMeterDisplayMode: normalizeHostSettingsDefaultsHypeMeterDisplayMode(settings.hypeMeterDisplayMode || ""),
      showFameLevel: settings.showFameLevel === true,
      hideNonEmbeddableYouTube: settings.hideNonEmbeddableYouTube !== false,
      requestMode: normalizeHostRoomRequestMode(settings.requestMode, settings.allowSingerTrackSelect === true),
      allowSingerTrackSelect: settings.allowSingerTrackSelect === true,
      audienceBackingMode: typeof settings.audienceBackingMode === "string" ? settings.audienceBackingMode.trim().toLowerCase() : "",
      unknownBackingPolicy: typeof settings.unknownBackingPolicy === "string" ? settings.unknownBackingPolicy.trim().toLowerCase() : "",
      audienceJoinPolicy: normalizeRoomAudienceJoinPolicy(settings.audienceJoinPolicy || {}),
      marqueeEnabled: settings.marqueeEnabled === true,
      marqueeShowMode: typeof settings.marqueeShowMode === "string" ? settings.marqueeShowMode.trim().toLowerCase() : "idle",
      chatShowOnTv: settings.chatShowOnTv === true,
      chatTvMode: typeof settings.chatTvMode === "string" ? settings.chatTvMode.trim().toLowerCase() : "auto",
      bouncerMode: settings.bouncerMode === true,
      bingoShowTv: settings.bingoShowTv !== false,
      bingoVotingMode: typeof settings.bingoVotingMode === "string" ? settings.bingoVotingMode.trim().toLowerCase() : "host+votes",
      bingoAutoApprovePct: clampNumber(settings.bingoAutoApprovePct, 10, 100, 50),
      bingoAudienceReopenEnabled: settings.bingoAudienceReopenEnabled !== false,
      autoLyricsOnQueue: settings.autoLyricsOnQueue === true,
      popTriviaEnabled: settings.popTriviaEnabled === true,
      gamePreviewId: typeof settings.gamePreviewId === "string" ? settings.gamePreviewId.trim().toLowerCase() : "",
      audienceShellVariant: String(settings.audienceShellVariant || "").trim().toLowerCase() === "classic" ? "classic" : "streamlined",
      audienceFeatureAccess: normalizeProvisionAudienceFeatureAccess(settings.audienceFeatureAccess || {}),
      queueSettings: {
        limitMode: typeof queueSettings.limitMode === "string" ? queueSettings.limitMode.trim().toLowerCase() : "none",
        limitCount: Math.max(0, Math.floor(Number(queueSettings.limitCount || 0) || 0)),
        rotation: typeof queueSettings.rotation === "string" ? queueSettings.rotation.trim().toLowerCase() : "round_robin",
        firstTimeBoost: queueSettings.firstTimeBoost !== false,
      },
      gameDefaults: {
        triviaRoundSec: clampNumber(gameDefaults.triviaRoundSec, 5, 90, 20),
        triviaAutoReveal: gameDefaults.triviaAutoReveal !== false,
        bingoVotingMode: typeof gameDefaults.bingoVotingMode === "string" ? gameDefaults.bingoVotingMode.trim().toLowerCase() : "host+votes",
        bingoAutoApprovePct: clampNumber(gameDefaults.bingoAutoApprovePct, 10, 100, 50),
      },
    },
  };
};

const buildProvisionPresetOverridesFromConfig = (presetConfig = null) => {
  if (!presetConfig) return {};
  const settings = presetConfig.settings || {};
  const requestMode = normalizeHostRoomRequestMode(settings.requestMode, settings.allowSingerTrackSelect === true);
  const audienceBackingMode = deriveHostAudienceBackingMode({
    audienceBackingMode: settings.audienceBackingMode,
    requestMode,
    allowSingerTrackSelect: settings.allowSingerTrackSelect === true,
  });
  const unknownBackingPolicy = deriveHostUnknownBackingPolicy({
    unknownBackingPolicy: settings.unknownBackingPolicy,
    audienceBackingMode,
    requestMode,
    allowSingerTrackSelect: settings.allowSingerTrackSelect === true,
  });
  const overrides = {
    hostNightPreset: presetConfig.id || "custom",
    hostNightPresetConfig: presetConfig,
    autoDj: settings.autoDj === true,
    autoBgMusic: settings.autoBgMusic === true,
    autoPlayMedia: settings.autoPlayMedia !== false,
    autoEndOnTrackFinish: settings.autoEndOnTrackFinish !== false,
    autoBonusEnabled: settings.autoBonusEnabled !== false,
    autoBonusPoints: clampNumber(settings.autoBonusPoints, 0, 1000, 25),
    autoDjDelaySec: clampNumber(settings.autoDjDelaySec, 2, 45, 10),
    oneMinuteMicEnabled: settings.oneMinuteMicEnabled === true,
    performanceProgressionMode: String(settings.performanceProgressionMode || "full_song").trim().toLowerCase() === "one_minute_mic" ? "one_minute_mic" : "full_song",
    oneMinuteMicOpeningWindowSec: clampNumber(settings.oneMinuteMicOpeningWindowSec, 15, 180, 60),
    oneMinuteMicVoteWindowSec: clampNumber(settings.oneMinuteMicVoteWindowSec, 5, 45, 12),
    showVisualizerTv: settings.showVisualizerTv === true,
    showLyricsTv: settings.showLyricsTv === true,
    showScoring: settings.showScoring === true,
    hypeMeterDisplayMode: normalizeHostSettingsDefaultsHypeMeterDisplayMode(settings.hypeMeterDisplayMode || ""),
    showFameLevel: settings.showFameLevel === true,
    requestMode,
    allowSingerTrackSelect: requestMode === ROOM_REQUEST_MODES.guestBackingOptional,
    audienceBackingMode,
    unknownBackingPolicy,
    hideNonEmbeddableYouTube: settings.hideNonEmbeddableYouTube !== false,
    audienceJoinPolicy: normalizeRoomAudienceJoinPolicy(settings.audienceJoinPolicy || {}),
    marqueeEnabled: settings.marqueeEnabled === true,
    marqueeShowMode: settings.marqueeShowMode || "idle",
    chatShowOnTv: settings.chatShowOnTv === true,
    chatTvMode: settings.chatTvMode || "auto",
    bouncerMode: settings.bouncerMode === true,
    bingoShowTv: settings.bingoShowTv !== false,
    bingoVotingMode: settings.bingoVotingMode || "host+votes",
    bingoAutoApprovePct: clampNumber(settings.bingoAutoApprovePct, 10, 100, 50),
    bingoAudienceReopenEnabled: settings.bingoAudienceReopenEnabled !== false,
    autoLyricsOnQueue: settings.autoLyricsOnQueue === true,
    popTriviaEnabled: settings.popTriviaEnabled === true,
    gamePreviewId: settings.gamePreviewId || null,
    audienceShellVariant: settings.audienceShellVariant === "classic" ? "classic" : "streamlined",
    audienceFeatureAccess: normalizeProvisionAudienceFeatureAccess(settings.audienceFeatureAccess || {}),
    queueSettings: {
      limitMode: settings?.queueSettings?.limitMode || "none",
      limitCount: Math.max(0, Number(settings?.queueSettings?.limitCount || 0)),
      rotation: settings?.queueSettings?.rotation || "round_robin",
      firstTimeBoost: settings?.queueSettings?.firstTimeBoost !== false,
    },
    gameDefaults: {
      triviaRoundSec: clampNumber(settings?.gameDefaults?.triviaRoundSec, 5, 90, 20),
      triviaAutoReveal: settings?.gameDefaults?.triviaAutoReveal !== false,
      bingoVotingMode: settings?.gameDefaults?.bingoVotingMode || "host+votes",
      bingoAutoApprovePct: clampNumber(settings?.gameDefaults?.bingoAutoApprovePct, 10, 100, 50),
    },
  };
  if (presetConfig.audienceBrandTheme) {
    overrides.audienceBrandTheme = presetConfig.audienceBrandTheme;
  }
  if (typeof presetConfig.brandingLogoUrl === "string" && presetConfig.brandingLogoUrl.trim()) {
    overrides.logoUrl = presetConfig.brandingLogoUrl.trim().slice(0, 2048);
  }
  if (typeof presetConfig.brandingOrbSkinUrl === "string" && presetConfig.brandingOrbSkinUrl.trim()) {
    overrides.lobbyOrbSkinUrl = presetConfig.brandingOrbSkinUrl.trim().slice(0, 2048);
  }
  return overrides;
};

const syncHostRoomRequestPolicyUpdates = ({ roomData = {}, updates = {} } = {}) => {
  const touchedPolicyKey = Object.keys(updates).some((key) => ROOM_REQUEST_POLICY_KEYS.has(key));
  if (!touchedPolicyKey) return updates;
  const touchedRequestModeKey = Object.prototype.hasOwnProperty.call(updates, "requestMode")
    || Object.prototype.hasOwnProperty.call(updates, "allowSingerTrackSelect");
  const touchedAudienceBackingModeKey = Object.prototype.hasOwnProperty.call(updates, "audienceBackingMode");

  const mergedPolicyState = {
    requestMode: Object.prototype.hasOwnProperty.call(updates, "requestMode")
      ? updates.requestMode
      : roomData?.requestMode,
    allowSingerTrackSelect: Object.prototype.hasOwnProperty.call(updates, "allowSingerTrackSelect")
      ? updates.allowSingerTrackSelect
      : roomData?.allowSingerTrackSelect,
    audienceBackingMode: touchedRequestModeKey
      ? ""
      : touchedAudienceBackingModeKey
      ? updates.audienceBackingMode
      : roomData?.audienceBackingMode,
    unknownBackingPolicy: Object.prototype.hasOwnProperty.call(updates, "unknownBackingPolicy")
      ? updates.unknownBackingPolicy
      : roomData?.unknownBackingPolicy,
  };

  const audienceBackingMode = deriveHostAudienceBackingMode(mergedPolicyState);
  const unknownBackingPolicy = deriveHostUnknownBackingPolicy({
    ...mergedPolicyState,
    audienceBackingMode,
  });

  return {
    ...updates,
    requestMode: deriveLegacyRequestModeFromAudienceBackingMode(audienceBackingMode),
    allowSingerTrackSelect: deriveLegacyAllowSingerTrackSelect(audienceBackingMode),
    audienceBackingMode,
    unknownBackingPolicy,
  };
};

const normalizeHostRoomUpdates = (rawUpdates = {}) => {
  if (!isPlainObject(rawUpdates)) {
    throw new HttpsError("invalid-argument", "updates must be an object.");
  }
  const entries = Object.entries(rawUpdates);
  if (!entries.length) {
    throw new HttpsError("invalid-argument", "updates must include at least one field.");
  }
  if (entries.length > 200) {
    throw new HttpsError("invalid-argument", "Too many updates in one request.");
  }

  const normalized = {};
  let estimatedChars = 0;

  entries.forEach(([rawKey, rawValue]) => {
    const key = String(rawKey || "").trim();
    if (!key) {
      throw new HttpsError("invalid-argument", "Update keys must be non-empty strings.");
    }
    if (key.length > 160 || key.startsWith(".") || key.endsWith(".") || key.includes("..")) {
      throw new HttpsError("invalid-argument", `Invalid update key: ${key}`);
    }

    const pathTokens = key.split(".");
    if (!pathTokens.every((token) => isValidUpdatePathToken(token))) {
      throw new HttpsError("invalid-argument", `Invalid update key: ${key}`);
    }
    const rootKey = pathTokens[0];
    if (ROOM_UPDATE_BLOCKED_ROOT_KEYS.has(rootKey)) {
      throw new HttpsError("permission-denied", `Room field "${rootKey}" cannot be updated from client payloads.`);
    }
    if (!HOST_ROOM_ALLOWED_ROOT_KEYS.has(rootKey)) {
      throw new HttpsError("invalid-argument", `Room field "${rootKey}" is not writable through host updates.`);
    }

    validateHostRoomUpdateValue(rawValue);
    if (pathTokens.length > 1) {
      const dottedRule = matchDottedHostRoomRule(key);
      if (!dottedRule) {
        throw new HttpsError("invalid-argument", `Nested room update path "${key}" is not allowed.`);
      }
      const dottedMatch = key.match(dottedRule.pattern);
      if (!dottedRule.validate(rawValue, dottedMatch)) {
        throw new HttpsError("invalid-argument", `Nested room update path "${dottedRule.label}" has an invalid value.`);
      }
    } else {
      validateHostRoomUpdateType(rootKey, rawValue);
    }

    const value = decodeHostRoomUpdateValue(rawValue);
    if (value === undefined) return;
    normalized[key] = key === "eventCredits"
      ? buildRoomEventCreditPublicSummary(value)
      : key === "audienceJoinPolicy"
        ? normalizeRoomAudienceJoinPolicy(value || {})
      : key === "searchSources"
        ? normalizeHostRoomSearchSources(value || {})
      : value;
    estimatedChars += key.length;
    try {
      estimatedChars += JSON.stringify(rawValue).length;
    } catch {
      estimatedChars += 0;
    }
  });

  if (!Object.keys(normalized).length) {
    throw new HttpsError("invalid-argument", "No valid update fields provided.");
  }
  if (estimatedChars > 120000) {
    throw new HttpsError("invalid-argument", "updates payload too large.");
  }

  return normalized;
};

const sanitizeOrgToken = (value = "") =>
  String(value || "")
    .trim()
    .replace(/[^a-zA-Z0-9_-]/g, "")
    .slice(0, 80);

const buildOrgIdForUid = (uid = "") => {
  const token = sanitizeOrgToken(uid) || "owner";
  return `org_${token}`;
};

const normalizeOrganizationMemberRole = (value = "", fallback = "member") => {
  const token = String(value || "").trim().toLowerCase();
  if (token === "owner" || token === "admin" || token === "member") return token;
  return fallback;
};

const normalizeOrgName = (value = "", uid = "") => {
  const trimmed = typeof value === "string" ? value.trim().slice(0, 120) : "";
  if (trimmed) return trimmed;
  const token = sanitizeOrgToken(uid).slice(0, 6) || "ORG";
  return `Workspace ${token.toUpperCase()}`;
};

const normalizeCapabilities = (input = {}) => {
  const caps = { ...BASE_CAPABILITIES };
  Object.entries(input || {}).forEach(([key, value]) => {
    caps[key] = !!value;
  });
  return caps;
};

const isPublicPaidHostPlan = (planId = "") => {
  const plan = getPlanDefinition(planId);
  return !!(
    plan
    && isPublicHostPlan(planId)
    && plan.interval
    && plan.amountCents > 0
  );
};

const planToUserTier = (planId = "") => {
  const plan = getPlanDefinition(planId);
  return plan?.tier || "free";
};

const planToUserPlan = (planId = "") => {
  const plan = getPlanDefinition(planId);
  if (plan?.interval === "year") return "yearly";
  if (plan?.interval === "month") return "monthly";
  return "monthly";
};

const valueToMillis = (value) => {
  if (!value) return 0;
  if (value instanceof Date) return value.getTime();
  if (typeof value?.toMillis === "function") return value.toMillis();
  if (typeof value?.seconds === "number") return value.seconds * 1000;
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : 0;
};

const orgsCollection = () => admin.firestore().collection(ORGS_COLLECTION);

const HOST_SETTINGS_DEFAULTS_SAVE_TARGETS = new Set([
  "host_default",
  "workspace_template",
]);
const HOST_SETTINGS_SHARED_TEMPLATES_CAPABILITY = "workspace.shared_templates";
const HOST_SETTINGS_AUDIT_COLLECTION = "settings_audit";

const HOST_SETTINGS_DEFAULTS_BUNDLE_KEYS = new Set([
  "crowd_mode",
  "operating_style",
]);

const HOST_SETTINGS_DEFAULTS_SOURCE_TYPES = new Set([
  "preset",
  "workspace_template",
  "host_default",
  "room_override",
  "runtime_override",
  "migration_adapter",
]);

const normalizeHostSettingsDefaultsSaveTarget = (value = "") => {
  const token = String(value || "").trim().toLowerCase();
  return HOST_SETTINGS_DEFAULTS_SAVE_TARGETS.has(token) ? token : "";
};

const normalizeHostSettingsDefaultsBundleKey = (value = "") => {
  const token = String(value || "").trim().toLowerCase();
  return HOST_SETTINGS_DEFAULTS_BUNDLE_KEYS.has(token) ? token : "";
};

const normalizeHostSettingsDefaultsSourceType = (value = "") => {
  const token = String(value || "").trim().toLowerCase();
  return HOST_SETTINGS_DEFAULTS_SOURCE_TYPES.has(token) ? token : "room_override";
};

const getHostSettingsCapabilityLabel = (capability = "") => {
  const safeCapability = String(capability || "").trim().toLowerCase();
  if (safeCapability === HOST_SETTINGS_SHARED_TEMPLATES_CAPABILITY) return "Shared Workspace Templates";
  return safeCapability || "Feature";
};

const hasHostSettingsCapability = (entitlements = null, capability = "") => {
  const safeCapability = String(capability || "").trim().toLowerCase();
  if (!safeCapability) return true;
  const capabilities = normalizeCapabilities(entitlements?.capabilities || {});
  return capabilities[safeCapability] === true;
};

const buildHostSettingsDefaultsAccessState = ({
  target = "",
  entitlements = null,
} = {}) => {
  const safeTarget = normalizeHostSettingsDefaultsSaveTarget(target);
  if (safeTarget === "workspace_template") {
    const canSave = hasHostSettingsCapability(entitlements, HOST_SETTINGS_SHARED_TEMPLATES_CAPABILITY);
    const capabilityLabel = getHostSettingsCapabilityLabel(HOST_SETTINGS_SHARED_TEMPLATES_CAPABILITY);
    return {
      target: safeTarget,
      requiredCapability: HOST_SETTINGS_SHARED_TEMPLATES_CAPABILITY,
      requiredCapabilityLabel: capabilityLabel,
      canRead: true,
      canSave,
      downgradeState: canSave ? "active" : "read_only_after_downgrade",
      message: canSave
        ? ""
        : `Workspace template is read-only on this plan. ${capabilityLabel} is required to save changes.`,
    };
  }
  return {
    target: safeTarget,
    requiredCapability: "",
    requiredCapabilityLabel: "",
    canRead: true,
    canSave: true,
    downgradeState: "active",
    message: "",
  };
};

const normalizeHostSettingsDefaultsChatTvMode = (value = "") => {
  const token = String(value || "").trim().toLowerCase();
  return token === "fullscreen" ? "fullscreen" : "auto";
};

const normalizeHostSettingsDefaultsQueueLimitMode = (value = "") => {
  const token = String(value || "").trim().toLowerCase();
  if (token === "per_night" || token === "per_hour" || token === "soft") return token;
  return "none";
};

const normalizeHostSettingsDefaultsQueueRotation = (value = "") => {
  const token = String(value || "").trim().toLowerCase();
  return token === "first_come" ? "first_come" : "round_robin";
};

const normalizeHostSettingsDefaultsHypeMeterDisplayMode = (value = "") => {
  const token = String(value || "").trim().toLowerCase();
  if (token === "score" || token === "integrated" || token === "score_integrated") return "score_integrated";
  if (token === "bar" || token === "top" || token === "top_bar") return "top_bar";
  if (token === "both") return "both";
  if (token === "off" || token === "none" || token === "hidden") return "hidden";
  return "score_integrated";
};

const normalizeHostSettingsDefaultsCrowdModeSettings = (input = {}) => ({
  chatShowOnTv: input?.chatShowOnTv === true,
  chatTvMode: normalizeHostSettingsDefaultsChatTvMode(input?.chatTvMode || ""),
  showScoring: input?.showScoring !== false,
  hypeMeterDisplayMode: normalizeHostSettingsDefaultsHypeMeterDisplayMode(input?.hypeMeterDisplayMode || ""),
  marqueeEnabled: input?.marqueeEnabled === true,
  popTriviaEnabled: input?.popTriviaEnabled === true,
});

const normalizeHostSettingsDefaultsOperatingStyleSettings = (input = {}) => ({
  autoPlayMedia: input?.autoPlayMedia === true,
  readyCheckDurationSec: clampNumber(input?.readyCheckDurationSec, 3, 30, 10),
  queueSettings: {
    limitMode: normalizeHostSettingsDefaultsQueueLimitMode(input?.queueSettings?.limitMode || ""),
    limitCount: clampNumber(input?.queueSettings?.limitCount, 0, 12, 0),
    rotation: normalizeHostSettingsDefaultsQueueRotation(input?.queueSettings?.rotation || ""),
    firstTimeBoost: input?.queueSettings?.firstTimeBoost !== false,
  },
});

const normalizeHostSettingsDefaultsBundleSettings = (bundleKey = "", input = {}) => {
  const safeBundleKey = normalizeHostSettingsDefaultsBundleKey(bundleKey);
  if (safeBundleKey === "crowd_mode") return normalizeHostSettingsDefaultsCrowdModeSettings(input);
  if (safeBundleKey === "operating_style") return normalizeHostSettingsDefaultsOperatingStyleSettings(input);
  return {};
};

const normalizeHostSettingsDefaultsProvenance = (input = {}) => ({
  sourceType: normalizeHostSettingsDefaultsSourceType(input?.sourceType || ""),
  sourceId: normalizeRunOfShowText(input?.sourceId || "", 180),
  savedTo: normalizeHostSettingsDefaultsSaveTarget(input?.savedTo || ""),
  actorUid: normalizeUidToken(input?.actorUid || ""),
  actorRole: normalizeRunOfShowText(input?.actorRole || "", 80).toLowerCase(),
  lastChangedAtMs: Math.max(0, Number(input?.lastChangedAtMs || 0) || 0),
});

const getHostSettingsDefaultsDocRef = ({ db, target = "", uid = "", orgId = "" }) => {
  const safeTarget = normalizeHostSettingsDefaultsSaveTarget(target);
  if (safeTarget === "host_default") {
    return db.collection("users").doc(normalizeUidToken(uid));
  }
  if (safeTarget === "workspace_template") {
    return orgsCollection().doc(orgId).collection("settings").doc("defaults");
  }
  return null;
};

const collectHostSettingsAuditChangedKeys = (value = {}, prefix = "") => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return prefix ? [prefix] : [];
  }
  return Object.entries(value).flatMap(([key, nested]) => {
    const nextPrefix = prefix ? `${prefix}.${key}` : key;
    if (nested && typeof nested === "object" && !Array.isArray(nested)) {
      return collectHostSettingsAuditChangedKeys(nested, nextPrefix);
    }
    return [nextPrefix];
  });
};

const buildHostSettingsAuditEntryId = ({
  target = "",
  bundleKey = "",
  uid = "",
  nowMs: entryNowMs = Date.now(),
} = {}) => [
  normalizeHostSettingsDefaultsSaveTarget(target),
  normalizeHostSettingsDefaultsBundleKey(bundleKey),
  normalizeUidToken(uid || ""),
  Math.max(0, Number(entryNowMs || 0) || 0),
].filter(Boolean).join("_").slice(0, 220);

const getHostSettingsAuditDocRef = ({ orgId = "", entryId = "" }) => {
  const safeOrgId = String(orgId || "").trim();
  const safeEntryId = String(entryId || "").trim();
  if (!safeOrgId || !safeEntryId) return null;
  return orgsCollection().doc(safeOrgId).collection(HOST_SETTINGS_AUDIT_COLLECTION).doc(safeEntryId);
};

const buildHostSettingsAuditEntry = ({
  target = "",
  bundleKey = "",
  actorUid = "",
  actorRole = "",
  workspaceRole = "",
  roomCode = "",
  orgId = "",
  sourceType = "",
  sourceId = "",
  settings = {},
  nowMs: entryNowMs = Date.now(),
} = {}) => {
  const safeTarget = normalizeHostSettingsDefaultsSaveTarget(target);
  const changedKeys = collectHostSettingsAuditChangedKeys(settings);
  return {
    id: buildHostSettingsAuditEntryId({
      target: safeTarget,
      bundleKey,
      uid: actorUid,
      nowMs: entryNowMs,
    }),
    action: "bundle_saved",
    target: safeTarget,
    bundleKey: normalizeHostSettingsDefaultsBundleKey(bundleKey),
    actorUid: normalizeUidToken(actorUid || ""),
    actorRole: normalizeRunOfShowText(actorRole || "", 80).toLowerCase(),
    workspaceRole: normalizeRunOfShowText(workspaceRole || "", 80).toLowerCase(),
    roomCode: normalizeRoomCode(roomCode || ""),
    orgId: String(orgId || "").trim(),
    sourceType: normalizeHostSettingsDefaultsSourceType(sourceType || ""),
    sourceId: normalizeRunOfShowText(sourceId || "", 180),
    changedKeys,
    changedKeyCount: changedKeys.length,
    visibility: safeTarget === "workspace_template" ? "workspace_visible" : "host_private",
    changedAtMs: Math.max(0, Number(entryNowMs || 0) || 0),
  };
};

const canViewHostSettingsAuditEntry = ({
  entry = {},
  actorUid = "",
  workspaceRole = "",
} = {}) => {
  const safeActorUid = normalizeUidToken(actorUid || "");
  const safeWorkspaceRole = normalizeRunOfShowText(workspaceRole || "", 80).toLowerCase();
  const visibility = normalizeRunOfShowText(entry?.visibility || "", 40).toLowerCase();
  if (visibility === "workspace_visible") return true;
  if (safeWorkspaceRole === "owner" || safeWorkspaceRole === "admin") return true;
  return normalizeUidToken(entry?.actorUid || "") === safeActorUid;
};

const readHostSettingsDefaultsResponse = ({ target = "", data = {}, accessState = null } = {}) => {
  const safeTarget = normalizeHostSettingsDefaultsSaveTarget(target);
  const bundleSource = data?.hostSettingsDefaults?.bundles && typeof data.hostSettingsDefaults.bundles === "object"
    ? data.hostSettingsDefaults.bundles
    : data?.bundles && typeof data.bundles === "object"
      ? data.bundles
      : {};
  const bundles = {};
  Object.keys(bundleSource).forEach((key) => {
    const safeKey = normalizeHostSettingsDefaultsBundleKey(key);
    if (!safeKey) return;
    const entry = bundleSource[key] || {};
    bundles[safeKey] = {
      bundleKey: safeKey,
      settings: normalizeHostSettingsDefaultsBundleSettings(safeKey, entry?.settings || {}),
      provenance: normalizeHostSettingsDefaultsProvenance(entry?.provenance || {}),
      updatedBy: normalizeUidToken(entry?.updatedBy || ""),
      updatedAtMs: Math.max(0, Number(entry?.updatedAtMs || 0) || 0),
    };
  });
  return {
    ok: true,
    target: safeTarget,
    bundles,
    accessState: accessState && typeof accessState === "object" ? { ...accessState } : null,
  };
};

const getUsagePeriodKey = (date = new Date()) => {
  const year = date.getUTCFullYear();
  const month = String(date.getUTCMonth() + 1).padStart(2, "0");
  return `${year}${month}`;
};

const normalizeUsagePeriodKey = (value = "") => {
  const trimmed = String(value || "").trim();
  if (!trimmed) return getUsagePeriodKey();
  if (!/^\d{6}$/.test(trimmed)) return "";
  const month = Number(trimmed.slice(4, 6));
  if (month < 1 || month > 12) return "";
  return trimmed;
};

const getPeriodRangeForKey = (periodKey = "") => {
  const safe = String(periodKey || "");
  if (!/^\d{6}$/.test(safe)) {
    return { startMs: 0, endMs: 0 };
  }
  const year = Number(safe.slice(0, 4));
  const monthIndex = Number(safe.slice(4, 6)) - 1;
  const start = Date.UTC(year, monthIndex, 1, 0, 0, 0, 0);
  const end = Date.UTC(year, monthIndex + 1, 1, 0, 0, 0, 0) - 1;
  return { startMs: start, endMs: end };
};

const toWholeNumber = (value, fallback = 0) => {
  const n = Number(value);
  if (!Number.isFinite(n)) return fallback;
  return Math.max(0, Math.floor(n));
};


const assignNestedUsageValue = (target = {}, dottedKey = "", value = undefined) => {
  const parts = String(dottedKey || "").split(".").map((part) => part.trim()).filter(Boolean);
  if (parts.length < 2) return;
  let cursor = target;
  for (let index = 0; index < parts.length; index += 1) {
    const part = parts[index];
    const last = index === parts.length - 1;
    if (last) {
      if (cursor[part] === undefined) cursor[part] = value;
      return;
    }
    if (!isPlainObject(cursor[part])) cursor[part] = {};
    cursor = cursor[part];
  }
};

const normalizeUsageDocumentData = (data = {}) => {
  const normalized = isPlainObject(data) ? { ...data } : {};
  Object.entries(isPlainObject(data) ? data : {}).forEach(([key, value]) => {
    if (!key.includes(".")) return;
    if (!key.startsWith("meters.") && !key.startsWith("analytics.")) return;
    assignNestedUsageValue(normalized, key, value);
  });
  return normalized;
};

const readOrganizationUsageSummary = async ({
  orgId = "",
  entitlements = null,
  periodKey = getUsagePeriodKey(),
}) => {
  if (!orgId) {
    return {
      orgId: "",
      period: periodKey,
      planId: entitlements?.planId || "free",
      status: entitlements?.status || "inactive",
      meters: {},
      totals: {
        estimatedOverageCents: 0,
      },
      generatedAtMs: nowMs(),
      periodRange: getPeriodRangeForKey(periodKey),
    };
  }
  const orgRef = orgsCollection().doc(orgId);
  const usageRef = orgRef.collection("usage").doc(periodKey);
  const workspaceControlRef = orgRef.collection("usage_controls").doc(USAGE_WORKSPACE_CONTROL_DOC);
  const capacityRef = orgRef.collection(ORG_USAGE_CAPACITY_COLLECTION).doc(periodKey);
  const [usageSnap, workspaceControlSnap, capacitySnap] = await Promise.all([
    usageRef.get(),
    workspaceControlRef.get(),
    capacityRef.get(),
  ]);
  const usageData = normalizeUsageDocumentData(usageSnap.data() || {});
  const workspaceControlData = workspaceControlSnap.data() || {};
  const capacityData = capacitySnap.data() || {};
  const meterData = usageData.meters || {};
  const meters = {};
  const workspaceMeterControls = {};
  const additionalCapacityEligible = canUseAdditionalUsageCapacity({
    planId: entitlements?.planId,
    status: entitlements?.status,
  });
  let estimatedOverageCents = 0;

  Object.keys(USAGE_METER_DEFINITIONS).forEach((meterId) => {
    const planQuota = resolveUsageMeterQuota({
      meterId,
      planId: entitlements?.usagePlanId || entitlements?.planId || "free",
      status: entitlements?.usageStatus || entitlements?.status || "inactive",
    });
    const additionalCapacity = additionalCapacityEligible
      ? resolveAdditionalCapacityUnits({ capacityDocument: capacityData, meterId })
      : 0;
    const maximumHardLimit = resolveMaximumUsageHardLimit({
      planHardLimit: planQuota.hardLimit,
      additionalUnits: additionalCapacity,
    });
    const effectiveHardLimit = resolveConfiguredHardLimit({
      control: workspaceControlData?.meters?.[meterId],
      maximumHardLimit,
      fallbackHardLimit: maximumHardLimit,
    });
    const capacityQuota = { ...planQuota, hardLimit: effectiveHardLimit };
    workspaceMeterControls[meterId] = {
      hardLimit: effectiveHardLimit,
      planHardLimit: planQuota.hardLimit,
      additionalCapacity,
      maximumHardLimit,
      customized: effectiveHardLimit !== maximumHardLimit,
    };
    const billingPlan = getPlanDefinition(entitlements?.planId || "free");
    const billingEligible = billingPlan?.tier === "host" && isEntitledStatus(entitlements?.status || "inactive");
    const quota = billingEligible ? capacityQuota : {
      ...capacityQuota,
      overageRateCents: 0,
      passThroughUnitCostCents: 0,
      markupMultiplier: 1,
      billableUnitRateCents: 0,
    };
    const meterBucket = meterData?.[meterId] || {};
    const used = toWholeNumber(meterBucket?.used, 0);
    const summary = buildUsageMeterSummary({
      meterId,
      used,
      reserved: meterBucket?.reserved,
      settled: meterBucket?.settled,
      released: meterBucket?.released,
      billable: meterBucket?.billable,
      invoiced: meterBucket?.invoiced,
      quota,
      periodKey,
      sources: meterBucket?.sources || {},
      actors: meterBucket?.actors || {},
      rooms: meterBucket?.rooms || {},
      surfaces: meterBucket?.surfaces || {},
    });
    summary.billingEligible = billingEligible;
    summary.planHardLimit = planQuota.hardLimit;
    summary.additionalCapacity = additionalCapacity;
    summary.maximumHardLimit = maximumHardLimit;
    meters[meterId] = summary;
    estimatedOverageCents += summary.estimatedOverageCents;
  });

  return {
    orgId,
    period: periodKey,
    planId: entitlements?.planId || "free",
    status: entitlements?.status || "inactive",
    meters,
    totals: {
      estimatedOverageCents,
    },
    controls: {
      workspace: {
        meters: workspaceMeterControls,
      },
    },
    additionalUsage: buildAdditionalUsageSummary({
      policy: ADDITIONAL_USAGE_POLICY,
      capacityDocument: capacityData,
      meterDefinitions: USAGE_METER_DEFINITIONS,
      periodKey,
    }),
    generatedAtMs: nowMs(),
    periodRange: getPeriodRangeForKey(periodKey),
  };
};

const centsToDollarString = (cents = 0) => (toWholeNumber(cents, 0) / 100).toFixed(2);

const csvEscape = (value = "") => {
  const s = String(value ?? "");
  if (s.includes(",") || s.includes("\"") || s.includes("\n")) {
    return `"${s.replace(/"/g, "\"\"")}"`;
  }
  return s;
};

const formatPeriodLabel = (periodKey = "") => {
  if (!/^\d{6}$/.test(String(periodKey || ""))) return "Current Period";
  const year = Number(periodKey.slice(0, 4));
  const monthIndex = Number(periodKey.slice(4, 6)) - 1;
  const date = new Date(Date.UTC(year, monthIndex, 1));
  return date.toLocaleString("en-US", { month: "long", year: "numeric", timeZone: "UTC" });
};

const buildUsageInvoiceDraft = ({
  orgId = "",
  orgName = "",
  entitlements = null,
  usageSummary = null,
  periodKey = getUsagePeriodKey(),
  includeBasePlan = false,
  taxRatePercent = 0,
  customerName = "",
}) => {
  const safeEntitlements = entitlements || {};
  const safeUsage = usageSummary || {
    meters: {},
    period: periodKey,
    totals: { estimatedOverageCents: 0 },
    periodRange: getPeriodRangeForKey(periodKey),
  };
  const period = safeUsage.period || periodKey;
  const periodLabel = formatPeriodLabel(period);
  const plan = getPlanDefinition(safeEntitlements.planId) || PLAN_DEFINITIONS.free;
  const issueDateMs = safeUsage?.periodRange?.endMs || nowMs();
  const dueDateMs = issueDateMs + (14 * 24 * 60 * 60 * 1000);
  const invoiceId = `INV-${sanitizeOrgToken(orgId).toUpperCase().slice(-12) || "ORG"}-${period}`;
  const lineItems = [];
  const billingEntity = String(customerName || "").trim() || String(orgName || "").trim() || orgId || "Customer";
  const rateCardSnapshot = {
    generatedAtMs: nowMs(),
    planId: safeEntitlements.planId || "free",
    planStatus: safeEntitlements.status || "inactive",
    meters: {},
  };

  if (includeBasePlan && isEntitledStatus(safeEntitlements.status) && plan.amountCents > 0) {
    lineItems.push({
      id: `base_plan_${plan.id}`,
      type: "base_plan",
      description: `${plan.name} subscription (${plan.interval || "period"})`,
      quantity: 1,
      unit: "plan",
      unitPriceCents: toWholeNumber(plan.amountCents, 0),
      amountCents: toWholeNumber(plan.amountCents, 0),
      period,
    });
  }

  const meters = Object.values(safeUsage.meters || {}).sort((a, b) =>
    String(a?.label || "").localeCompare(String(b?.label || ""))
  );
  meters.forEach((meter) => {
    const overageUnits = toWholeNumber(meter?.overageUnits, 0);
    const passThroughUnitCostCents = toWholeNumber(meter?.passThroughUnitCostCents, 0);
    const markupMultiplier = Number.isFinite(Number(meter?.markupMultiplier))
      ? Math.max(0, Number(meter?.markupMultiplier))
      : 1;
    const billableUnitRateCents = toWholeNumber(
      meter?.billableUnitRateCents,
      toWholeNumber(meter?.overageRateCents, 0)
    );
    rateCardSnapshot.meters[meter.meterId] = {
      meterId: meter.meterId,
      label: meter.label || meter.meterId,
      unit: meter.unit || "unit",
      includedUnits: toWholeNumber(meter?.included, 0),
      hardLimitUnits: toWholeNumber(meter?.hardLimit, 0),
      passThroughUnitCostCents,
      markupMultiplier,
      billableUnitRateCents,
    };
    if (!overageUnits || !billableUnitRateCents) return;
    lineItems.push({
      id: `overage_${meter.meterId}`,
      type: "overage",
      meterId: meter.meterId,
      description: `${meter.label} overage (${periodLabel})`,
      quantity: overageUnits,
      unit: meter.unit || "unit",
      includedUnits: toWholeNumber(meter?.included, 0),
      overageUnits,
      passThroughUnitCostCents,
      markupMultiplier,
      billableUnitRateCents,
      unitPriceCents: billableUnitRateCents,
      amountCents: overageUnits * billableUnitRateCents,
      period,
    });
  });

  const subtotalCents = lineItems.reduce((sum, line) => sum + toWholeNumber(line.amountCents, 0), 0);
  const safeTaxRatePercent = Math.max(0, Math.min(100, Number(taxRatePercent || 0)));
  const taxCents = Math.round(subtotalCents * (safeTaxRatePercent / 100));
  const totalCents = subtotalCents + taxCents;

  const qbseTransactionCsvRows = [
    ["Date", "Description", "Amount"],
    ...lineItems.map((line) => ([
      new Date(issueDateMs).toISOString().slice(0, 10),
      `${billingEntity} - ${line.description}`,
      centsToDollarString(line.amountCents),
    ])),
  ];
  const qbseTransactionCsv = qbseTransactionCsvRows
    .map((row) => row.map((cell) => csvEscape(cell)).join(","))
    .join("\n");

  const lineItemCsvRows = [
    [
      "InvoiceNumber",
      "InvoiceDate",
      "DueDate",
      "Customer",
      "Description",
      "Qty",
      "UnitPrice",
      "Amount",
      "IncludedUnits",
      "OverageUnits",
      "PassThroughUnitCost",
      "MarkupMultiplier",
      "BillableUnitRate",
    ],
    ...lineItems.map((line) => ([
      invoiceId,
      new Date(issueDateMs).toISOString().slice(0, 10),
      new Date(dueDateMs).toISOString().slice(0, 10),
      billingEntity,
      line.description,
      String(line.quantity || 0),
      centsToDollarString(line.unitPriceCents || 0),
      centsToDollarString(line.amountCents || 0),
      String(toWholeNumber(line.includedUnits, 0)),
      String(toWholeNumber(line.overageUnits, 0)),
      centsToDollarString(line.passThroughUnitCostCents || 0),
      Number(line.markupMultiplier || 1).toFixed(2),
      centsToDollarString(line.billableUnitRateCents || line.unitPriceCents || 0),
    ])),
  ];
  const lineItemCsv = lineItemCsvRows
    .map((row) => row.map((cell) => csvEscape(cell)).join(","))
    .join("\n");

  return {
    invoiceId,
    orgId,
    orgName: orgName || orgId,
    customerName: billingEntity,
    period,
    periodLabel,
    issueDateMs,
    dueDateMs,
    planId: safeEntitlements.planId || "free",
    planStatus: safeEntitlements.status || "inactive",
    includeBasePlan: !!includeBasePlan,
    taxRatePercent: safeTaxRatePercent,
    lineItems,
    totals: {
      subtotalCents,
      taxCents,
      totalCents,
    },
    rateCardSnapshot,
    usageSummary: safeUsage,
    quickbooks: {
      selfEmployed: {
        apiSupported: false,
        suggestedFlow: "Use line-item CSV for manual invoice entry and transaction CSV for income import reconciliation.",
        lineItemCsv,
        qbseTransactionCsv,
      },
      online: {
        apiSupported: true,
        suggestedFlow: "Map lineItems to QuickBooks Online Invoice API SalesItemLineDetail entries.",
        invoicePayloadCandidate: {
          customerDisplayName: billingEntity,
          txnDate: new Date(issueDateMs).toISOString().slice(0, 10),
          dueDate: new Date(dueDateMs).toISOString().slice(0, 10),
          lineItems: lineItems.map((line) => ({
            description: line.description,
            qty: line.quantity || 0,
            unitPrice: Number(centsToDollarString(line.unitPriceCents || 0)),
            amount: Number(centsToDollarString(line.amountCents || 0)),
          })),
        },
      },
    },
  };
};

const sanitizeInvoiceStatus = (value = "") => {
  const safe = String(value || "").trim().toLowerCase();
  if (["draft", "sent", "paid", "void"].includes(safe)) return safe;
  return "draft";
};

const MARKETING_WAITLIST_USE_CASES = new Set([
  "Home Party Host",
  "Fundraiser Organizer",
  "Community Event Host",
  "Venue / KJ Operator",
  "host_application",
]);

const sanitizeWaitlistName = (value = "") => {
  const safe = String(value || "").trim().slice(0, 80);
  if (!safe) {
    throw new HttpsError("invalid-argument", "name is required.");
  }
  return safe;
};

const sanitizeWaitlistEmail = (value = "") => {
  const safe = String(value || "").trim().toLowerCase();
  if (!safe || safe.length > 254) {
    throw new HttpsError("invalid-argument", "Valid email is required.");
  }
  const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(safe);
  if (!valid) {
    throw new HttpsError("invalid-argument", "Valid email is required.");
  }
  return safe;
};

const sanitizeOptionalWaitlistEmail = (value = "") => {
  const safe = String(value || "").trim();
  if (!safe) return "";
  return sanitizeWaitlistEmail(safe);
};

const parseBooleanInput = (value, fallback = true) => {
  if (value === undefined || value === null || value === "") return fallback;
  if (typeof value === "boolean") return value;
  const token = String(value || "").trim().toLowerCase();
  if (["1", "true", "yes", "on"].includes(token)) return true;
  if (["0", "false", "no", "off"].includes(token)) return false;
  return fallback;
};

const sanitizeWaitlistUseCase = (value = "") => {
  const safe = String(value || "").trim();
  if (MARKETING_WAITLIST_USE_CASES.has(safe)) return safe;
  return "Home Party Host";
};

const sanitizeWaitlistSource = (value = "") => {
  const safe = String(value || "").trim().slice(0, 120);
  if (!safe) return "marketing_site";
  return safe;
};

const HOST_APPLICATION_HOST_TYPES = new Set(["home_party", "private_events", "venue_kj", "fundraiser_community", "testing_learning"]);

const sanitizeHostApplicationChoice = (value = "", allowed = new Set()) => {
  const token = String(value || "").trim().toLowerCase();
  return allowed.has(token) ? token : "";
};

const sanitizeHostApplicationProfile = (payload = {}) => ({
  hostType: sanitizeHostApplicationChoice(payload.hostType, HOST_APPLICATION_HOST_TYPES),
  hostingGoal: String(payload.hostingGoal || "").trim().slice(0, 500),
});

const buildHostApplicationNextStepsMessage = ({ isNewSignup = false } = {}) => (
  isNewSignup
    ? "You are on the BeauRocks Host waitlist. We release only a few invitations at a time and will email you if a spot becomes available. No account is needed right now."
    : "You are already on the BeauRocks Host waitlist. We will email you if an invitation becomes available. No account is needed right now."
);

const sanitizeHostApplicationStatus = (value = "", fallback = "pending") => {
  const token = String(value || "").trim().toLowerCase();
  if (["pending", "approved", "rejected"].includes(token)) return token;
  return fallback;
};

const buildWaitlistDocId = (email = "") =>
  `wl_${email.replace(/[^a-z0-9]/g, "_").replace(/_+/g, "_").slice(0, 140) || "unknown"}`;

const buildHostApplicationDocId = ({ uid = "", email = "" } = {}) => {
  const safeUid = normalizeUidToken(uid);
  if (safeUid) return `uid_${safeUid}`;
  const safeEmail = normalizeEmailToken(email);
  return `email_${buildWaitlistDocId(safeEmail || "unknown")}`;
};

const normalizeMarketingPrivateInviteCode = (value = "", maxLen = 24) =>
  String(value || "")
    .trim()
    .toUpperCase()
    .replace(/[^A-Z0-9@]/g, "")
    .slice(0, Math.max(4, Number(maxLen || 24)));

const parseMarketingPrivateInviteCodes = (value = "") => {
  const raw = Array.isArray(value)
    ? value
    : String(value || "").split(/[,\n;|]/g);
  const out = [];
  const seen = new Set();
  raw.forEach((entry) => {
    const code = normalizeMarketingPrivateInviteCode(entry, 24);
    if (!code || seen.has(code)) return;
    seen.add(code);
    out.push(code);
  });
  return out;
};

const parseMarketingUidSet = (value = "") => {
  const raw = Array.isArray(value)
    ? value
    : String(value || "").split(/[,\n;|]/g);
  const out = new Set();
  raw.forEach((entry) => {
    const token = String(entry || "").trim().slice(0, 180);
    if (!token) return;
    out.add(token);
  });
  return out;
};

const parseMarketingRoomCodeSet = (value = "") => {
  const raw = Array.isArray(value)
    ? value
    : String(value || "").split(/[,\n;|]/g);
  const out = new Set();
  raw.forEach((entry) => {
    const token = normalizeRoomCode(entry);
    if (!token) return;
    out.add(token);
  });
  return out;
};

