const writeDemoTriviaVotes = async ({
  rootRef = getRootRef(),
  roomCode = "",
  payload = {},
}) => {
  const safeRoomCode = normalizeRoomCode(roomCode);
  if (!safeRoomCode) return 0;
  const mode = resolveDemoSceneMode(payload.sceneId || "");
  if (mode !== "trivia" && mode !== "wyr") return 0;

  const db = admin.firestore();
  const batch = db.batch();
  const questionIdToken = mode === "trivia"
    ? (payload?.trivia?.questionId || "q_demo")
    : (payload?.wyr?.questionId || "wyr_demo");
  const questionId = sanitizeDemoToken(questionIdToken, 64) || (mode === "trivia" ? "q_demo" : "wyr_demo");
  const serverNow = admin.firestore.FieldValue.serverTimestamp();
  const voteType = mode === "trivia" ? "vote_trivia" : "vote_wyr";
  const voteValues = mode === "trivia" ? [0, 1, 2, 3] : ["A", "B"];
  const voteCounts = mode === "trivia"
    ? (Array.isArray(payload?.trivia?.votes) ? payload.trivia.votes : [])
    : (Array.isArray(payload?.wyr?.votes) ? payload.wyr.votes : []);
  if (!voteCounts.length) return 0;

  let cursor = 0;
  let written = 0;
  for (let optionIndex = 0; optionIndex < voteValues.length; optionIndex += 1) {
    const requestedVotes = clampNumber(voteCounts[optionIndex] ?? 0, 0, 200, 0);
    const count = Math.min(DEMO_MAX_VOTES_PER_OPTION, requestedVotes);
    for (let i = 0; i < count; i += 1) {
      const profile = DEMO_USER_LIBRARY[cursor % DEMO_USER_LIBRARY.length];
      const uid = `demo_vote_${optionIndex + 1}_${i + 1}`;
      const voteDocId = `demo_vote_${safeRoomCode}_${questionId}_${uid}`;
      batch.set(rootRef.collection("reactions").doc(voteDocId), {
        roomCode: safeRoomCode,
        type: voteType,
        val: voteValues[optionIndex],
        questionId,
        uid,
        userName: profile.name,
        avatar: profile.avatar,
        isVote: true,
        isDemo: true,
        timestamp: serverNow,
      }, { merge: true });
      cursor += 1;
      written += 1;
    }
  }

  if (!written) return 0;
  await batch.commit();
  return written;
};

const applyRoomAwardsOnce = async ({
  roomCode,
  awardKey,
  awards = [],
  source = "room_signal",
}) => {
  const safeRoomCode = normalizeRoomCode(roomCode);
  const safeAwardKey = normalizeAwardKeyToken(awardKey);
  const normalizedAwards = normalizePointAwards(awards);
  if (!safeRoomCode || !safeAwardKey || !normalizedAwards.length) {
    return { applied: false, awardedCount: 0, awardedPoints: 0 };
  }

  const rootRef = getRootRef();
  const eventRef = rootRef.collection("room_awards").doc(safeAwardKey);

  return admin.firestore().runTransaction(async (tx) => {
    const eventSnap = await tx.get(eventRef);
    if (eventSnap.exists) {
      return { applied: false, duplicate: true, awardedCount: 0, awardedPoints: 0 };
    }

    const targets = normalizedAwards.map((entry) => ({
      ...entry,
      ref: rootRef.collection("room_users").doc(`${safeRoomCode}_${entry.uid}`),
    }));
    const snaps = await Promise.all(targets.map((entry) => tx.get(entry.ref)));

    const appliedAwards = [];
    const skippedUids = [];
    targets.forEach((entry, idx) => {
      if (!snaps[idx].exists) {
        skippedUids.push(entry.uid);
        return;
      }
      appliedAwards.push(entry);
      tx.update(entry.ref, {
        points: admin.firestore.FieldValue.increment(entry.points),
        lastActiveAt: admin.firestore.FieldValue.serverTimestamp(),
      });
    });

    let awardedPoints = 0;
    appliedAwards.forEach((entry) => {
      awardedPoints += entry.points;
    });

    tx.set(eventRef, {
      roomCode: safeRoomCode,
      source,
      awards: appliedAwards.map(({ uid, points }) => ({ uid, points })),
      skippedUids,
      awardedCount: appliedAwards.length,
      awardedPoints,
      createdAt: admin.firestore.FieldValue.serverTimestamp(),
    });

    return {
      applied: appliedAwards.length > 0,
      duplicate: false,
      awardedCount: appliedAwards.length,
      awardedPoints,
      skippedUids,
    };
  });
};

const decodeEntities = (input = "") =>
  input
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");

const parseTimeMs = (val = "") => {
  const parts = val.split(":").map((p) => p.trim());
  const toSeconds = (p) => {
    const [s, ms = "0"] = p.split(".");
    return Number(s || 0) + Number(ms.padEnd(3, "0")) / 1000;
  };
  if (parts.length === 3) {
    return (
      Number(parts[0] || 0) * 3600 * 1000 +
      Number(parts[1] || 0) * 60 * 1000 +
      toSeconds(parts[2]) * 1000
    );
  }
  if (parts.length === 2) {
    return Number(parts[0] || 0) * 60 * 1000 + toSeconds(parts[1]) * 1000;
  }
  return toSeconds(parts[0] || "0") * 1000;
};

const parseTtml = (ttml = "") => {
  if (!ttml) return [];
  const results = [];
  const regex = /<p\b[^>]*begin="([^"]+)"[^>]*end="([^"]+)"[^>]*>([\s\S]*?)<\/p>/gi;
  let match;
  while ((match = regex.exec(ttml))) {
    const startMs = parseTimeMs(match[1]);
    const endMs = parseTimeMs(match[2]);
    const rawText = match[3]
      .replace(/<br\s*\/?>/gi, "\n")
      .replace(/<[^>]+>/g, "")
      .trim();
    const text = decodeEntities(rawText);
    if (!text) continue;
    results.push({ text, startMs, endMs });
  }
  return results;
};

let appleTokenCache = { token: null, exp: 0 };
const normalizeAppleMusicSecret = (value = "", { preserveNewlines = false } = {}) => {
  const stringValue = String(value || "");
  if (!stringValue) return "";
  if (preserveNewlines) {
    return stringValue
      .replace(/\r/g, "")
      .replace(/^\s+|\s+$/g, "");
  }
  return stringValue.replace(/[\r\n]/g, "").trim();
};
const getAppleMusicToken = () => {
  const teamId = normalizeAppleMusicSecret(APPLE_MUSIC_TEAM_ID.value());
  const keyId = normalizeAppleMusicSecret(APPLE_MUSIC_KEY_ID.value());
  let privateKey = normalizeAppleMusicSecret(APPLE_MUSIC_PRIVATE_KEY.value(), { preserveNewlines: true });
  if (!teamId || !keyId || !privateKey) {
    throw new HttpsError("failed-precondition", "Apple Music secrets not configured.");
  }
  privateKey = privateKey.replace(/\\n/g, "\n");
  const now = Math.floor(Date.now() / 1000);
  if (appleTokenCache.token && appleTokenCache.exp > now + 60) {
    return appleTokenCache.token;
  }
  const exp = now + 60 * 60;
  const token = jwt.sign(
    { iss: teamId, iat: now, exp },
    privateKey,
    { algorithm: "ES256", header: { kid: keyId } }
  );
  appleTokenCache = { token, exp };
  return token;
};

const SONG_IDENTITY_ALIASES_COLLECTION = "song_identity_aliases";

const ensureSongAdmin = async ({
  title,
  artist,
  artworkUrl,
  itunesId,
  appleMusicId,
  aliases = [],
  verifyMeta = false,
  verifiedBy = "host",
}) => {
  const safeTitle = (title || "").trim();
  if (!safeTitle) return null;
  const safeArtist = (artist || "Unknown").trim() || "Unknown";
  const songId = buildSongKey(safeTitle, safeArtist);
  const ref = admin.firestore().collection("songs").doc(songId);
  const snap = await ref.get();

  const updates = {
    title: safeTitle,
    artist: safeArtist,
    normalizedKey: songId,
    updatedAt: admin.firestore.FieldValue.serverTimestamp(),
  };

  if (!snap.exists) {
    updates.createdAt = admin.firestore.FieldValue.serverTimestamp();
  }
  if (artworkUrl) {
    updates.artworkUrl = artworkUrl;
  }
  if (itunesId) {
    updates.itunesId = String(itunesId);
  }
  if (appleMusicId) {
    updates.appleMusicIds = admin.firestore.FieldValue.arrayUnion(String(appleMusicId));
  }
  if (aliases.length) {
    const cleanAliases = aliases.filter(Boolean).map((item) => String(item));
    if (cleanAliases.length) {
      updates.aliases = admin.firestore.FieldValue.arrayUnion(...cleanAliases);
    }
  }

  if (verifyMeta && typeof verifyMeta === "object") {
    updates.verifiedMeta = {
      title: safeTitle,
      artist: safeArtist,
      artworkUrl: artworkUrl || null,
      lyricsSource: verifyMeta.lyricsSource || null,
      lyricsTimed: !!verifyMeta.lyricsTimed,
      lastVerifiedAt: admin.firestore.FieldValue.serverTimestamp(),
      verifiedBy,
    };
  }

  await ref.set(updates, { merge: true });
  const aliasKeys = new Set([songId]);
  aliases.filter(Boolean).forEach((alias) => {
    const aliasText = String(alias || "").trim();
    if (aliasText) aliasKeys.add(buildSongKey(aliasText, safeArtist));
  });
  const aliasRefs = [...aliasKeys].map((aliasKey) => ({
    aliasKey,
    ref: admin.firestore().collection(SONG_IDENTITY_ALIASES_COLLECTION).doc(aliasKey),
  }));
  await admin.firestore().runTransaction(async (tx) => {
    const aliasSnaps = await Promise.all(aliasRefs.map(({ ref: aliasRef }) => tx.get(aliasRef)));
    const conflicts = [];
    aliasRefs.forEach(({ aliasKey, ref: aliasRef }, index) => {
      const existingCanonicalSongId = aliasSnaps[index].exists
        ? String(aliasSnaps[index].get("canonicalSongId") || "").trim()
        : "";
      if (existingCanonicalSongId && existingCanonicalSongId !== songId) {
        conflicts.push(`${aliasKey}:${existingCanonicalSongId}`);
        return;
      }
      tx.set(aliasRef, {
        aliasKey,
        canonicalSongId: songId,
        title: safeTitle,
        artist: safeArtist,
        source: aliasKey === songId ? "normalized_identity" : "declared_alias",
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      }, { merge: true });
    });
    if (conflicts.length) tx.set(ref, { aliasConflicts: admin.firestore.FieldValue.arrayUnion(...conflicts) }, { merge: true });
  });
  return { songId, songData: snap.exists ? snap.data() : null };
};

const ensureTrackAdmin = async ({
  songId,
  source,
  mediaUrl,
  appleMusicId,
  label,
  duration,
  audioOnly,
  backingOnly,
  addedBy,
  approvalState,
  qualityScore,
  backingCandidateId,
  canonicalSongId,
  rankingScore,
  backingTelemetry,
}) => {
  if (!songId) return null;
  const cleanSource = source || "custom";
  const youtubeId = cleanSource === "youtube" ? extractYouTubeId(mediaUrl) : "";
  const sourceLookupKey = buildTrackSourceLookupKey({
    source: cleanSource,
    mediaUrl,
    appleMusicId,
    youtubeId,
  });
  let trackId = "";

  if (cleanSource === "youtube" && youtubeId) {
    trackId = `${songId}__yt__${youtubeId}`;
  } else if (cleanSource === "apple" && appleMusicId) {
    trackId = `${songId}__apple__${appleMusicId}`;
  }

  const payload = {
    songId,
    source: cleanSource,
    mediaUrl: mediaUrl || null,
    appleMusicId: appleMusicId || null,
    youtubeId: youtubeId || null,
    label: label || null,
    duration: duration || null,
    audioOnly: !!audioOnly,
    backingOnly: !!backingOnly,
    updatedAt: admin.firestore.FieldValue.serverTimestamp(),
  };
  if (addedBy) payload.addedBy = addedBy;
  if (approvalState) payload.approvalState = normalizeTrackApprovalState(approvalState);
  if (Number.isFinite(Number(qualityScore))) payload.qualityScore = Number(qualityScore);
  if (backingCandidateId) payload.backingCandidateId = String(backingCandidateId).trim().slice(0, 260);
  if (canonicalSongId || songId) payload.canonicalSongId = String(canonicalSongId || songId).trim().slice(0, 220);
  if (Number.isFinite(Number(rankingScore))) payload.rankingScore = Math.max(0, Number(rankingScore));
  if (backingTelemetry && typeof backingTelemetry === 'object' && !Array.isArray(backingTelemetry)) {
    payload.backingTelemetry = backingTelemetry;
  }

  if (trackId) {
    const ref = admin.firestore().collection("tracks").doc(trackId);
    const snap = await ref.get();
    if (!snap.exists) {
      payload.createdAt = admin.firestore.FieldValue.serverTimestamp();
    }
    await ref.set(payload, { merge: true });
    if (sourceLookupKey) {
      await admin.firestore().collection(TRACK_SOURCE_LOOKUP_COLLECTION).doc(sourceLookupKey).set(
        {
          source: cleanSource,
          songId,
          trackId,
          youtubeId: youtubeId || null,
          appleMusicId: appleMusicId || null,
          updatedAt: admin.firestore.FieldValue.serverTimestamp(),
          ...(snap.exists ? {} : { createdAt: admin.firestore.FieldValue.serverTimestamp() }),
        },
        { merge: true }
      );
    }
    return { trackId };
  }

  payload.createdAt = admin.firestore.FieldValue.serverTimestamp();
  const docRef = await admin.firestore().collection("tracks").add(payload);
  if (sourceLookupKey) {
    await admin.firestore().collection(TRACK_SOURCE_LOOKUP_COLLECTION).doc(sourceLookupKey).set(
      {
        source: cleanSource,
        songId,
        trackId: docRef.id,
        youtubeId: youtubeId || null,
        appleMusicId: appleMusicId || null,
        createdAt: admin.firestore.FieldValue.serverTimestamp(),
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      },
      { merge: true }
    );
  }
  return { trackId: docRef.id };
};

const resolveCanonicalTrackIdentityInternal = async ({
  songId = "",
  title = "",
  artist = "",
  source = "",
  mediaUrl = "",
  appleMusicId = "",
} = {}) => {
  const db = admin.firestore();
  const safeSongId = String(songId || "").trim();
  const safeTitle = String(title || "").trim();
  const safeArtist = String(artist || "").trim() || "Unknown";
  const cleanSource = String(source || "").trim().toLowerCase()
    || (appleMusicId ? "apple" : extractYouTubeId(mediaUrl || "") ? "youtube" : "");
  const youtubeId = extractYouTubeId(mediaUrl || "");

  const loadSong = async (candidateSongId = "", matchedBy = "", matchedTrackId = "") => {
    const requestedSongId = String(candidateSongId || "").trim();
    const resolvedIdentity = await followCanonicalSongRedirect({
      initialSongId: requestedSongId,
      loadSongData: async (nextSongId) => {
        const nextSnap = await db.collection("songs").doc(nextSongId).get();
        return nextSnap.exists ? (nextSnap.data() || {}) : null;
      },
    });
    const normalizedSongId = String(resolvedIdentity?.songId || "").trim();
    if (!normalizedSongId) return null;
    const songData = resolvedIdentity.songData || {};
    return {
      found: true,
      songId: normalizedSongId,
      trackId: matchedTrackId || null,
      title: String(songData.title || safeTitle || "").trim() || safeTitle,
      artist: String(songData.artist || safeArtist || "Unknown").trim() || "Unknown",
      artworkUrl: String(songData.artworkUrl || songData.albumArtUrl || "").trim(),
      matchedBy: resolvedIdentity.redirected ? `${matchedBy}_redirect` : matchedBy,
    };
  };
  const loadSongAlias = async (aliasKey = "", matchedBy = "identity_alias") => {
    const safeAliasKey = String(aliasKey || "").trim();
    if (!safeAliasKey) return null;
    const aliasSnap = await db.collection(SONG_IDENTITY_ALIASES_COLLECTION).doc(safeAliasKey).get();
    if (!aliasSnap.exists) return null;
    return loadSong(aliasSnap.get("canonicalSongId") || "", matchedBy);
  };

  if (safeSongId) {
    const explicitSong = await loadSong(safeSongId, "explicit_song_id");
    if (explicitSong) return explicitSong;
  }

  const sourceLookupKey = buildTrackSourceLookupKey({
    source: cleanSource,
    mediaUrl,
    appleMusicId,
    youtubeId,
  });
  if (sourceLookupKey) {
    const sourceSnap = await db.collection(TRACK_SOURCE_LOOKUP_COLLECTION).doc(sourceLookupKey).get();
    if (sourceSnap.exists) {
      const sourceData = sourceSnap.data() || {};
      const mappedSong = await loadSong(sourceData.songId || "", "source_lookup", sourceData.trackId || "");
      if (mappedSong) return mappedSong;
    }
  }

  const safeAppleMusicId = String(appleMusicId || "").trim();
  if (safeAppleMusicId) {
    const songsSnap = await db.collection("songs")
      .where("appleMusicIds", "array-contains", safeAppleMusicId)
      .limit(1)
      .get();
    const songDoc = songsSnap.docs[0];
    if (songDoc?.exists) {
      const appleSong = await loadSong(songDoc.id, "apple_music_id");
      if (appleSong) return appleSong;
    }
  }

  const candidates = deriveCanonicalSongCandidates({
    title: safeTitle,
    artist: safeArtist,
  });
  for (const candidate of candidates) {
    const matchedSong = await loadSong(candidate.songId, candidate.matchedBy);
    if (matchedSong) {
      return matchedSong;
    }
    const aliasSong = await loadSongAlias(candidate.songId, `${candidate.matchedBy}_alias`);
    if (aliasSong) return aliasSong;
  }

  const fallbackCandidate = candidates[0] || {
    songId: buildSongKey(safeTitle || "Unknown", safeArtist),
    title: safeTitle || "Unknown",
    artist: safeArtist,
    matchedBy: "fallback",
  };
  return {
    found: false,
    songId: fallbackCandidate.songId,
    trackId: null,
    title: fallbackCandidate.title,
    artist: fallbackCandidate.artist,
    matchedBy: fallbackCandidate.matchedBy,
    sourceLookupKey: sourceLookupKey || "",
  };
};

const normalizeLyricsText = (value = "") =>
  typeof value === "string"
    ? value.replace(/\r\n/g, "\n").replace(/\r/g, "\n").trim()
    : "";

const normalizeTimedLyrics = (timedLyrics = []) => {
  if (!Array.isArray(timedLyrics)) return [];
  const normalized = [];
  for (const raw of timedLyrics) {
    const text = normalizeLyricsText(raw?.text || "");
    if (!text) continue;
    const startMs = Math.max(0, Math.round(Number(raw?.startMs || 0)));
    const endCandidate = Math.round(Number(raw?.endMs || startMs + 2500));
    const endMs = Math.max(startMs + 300, endCandidate);
    normalized.push({ text, startMs, endMs });
  }
  return normalized;
};

const isRoomAiDemoBypassEnabled = (roomData = {}) => {
  const missionControl = isPlainObject(roomData?.missionControl)
    ? roomData.missionControl
    : {};
  if (missionControl?.aiDemoBypass !== true) return false;
  const untilRaw = Number(missionControl?.aiDemoBypassUntil || 0);
  const untilMs = Number.isFinite(untilRaw) && untilRaw > 0 ? untilRaw : 0;
  return !untilMs || untilMs > Date.now();
};

const isLyricsPipelineV2EnabledForRoom = () => LYRICS_PIPELINE_V2_ENABLED_DEFAULT;

const buildLyricsAiMeterEntitlements = async ({
  roomData = {},
  entitlements = null,
} = {}) => {
  if (entitlements?.capabilities?.["ai.generate_content"]) return entitlements;
  const hostUids = Array.isArray(roomData?.hostUids) ? roomData.hostUids : [];
  const primaryHostUid = normalizeUidToken(roomData?.hostUid || hostUids[0] || "");
  if (!primaryHostUid) return entitlements;
  const [hostApprovalEnabled, superAdmin] = await Promise.all([
    hasHostApprovalAccess(primaryHostUid),
    isSuperAdminUid(primaryHostUid),
  ]);
  if (!hostApprovalEnabled && !superAdmin) return entitlements;
  const currentPlanId = String(entitlements?.planId || "").trim();
  const effectivePlan = getPlanDefinition(currentPlanId);
  const effectivePlanId = effectivePlan?.tier === "host" ? effectivePlan.id : "host_monthly";
  return {
    ...(entitlements || {}),
    planId: effectivePlanId,
    status: "active",
    source: superAdmin ? "lyrics_super_admin_metered" : "lyrics_host_approval_metered",
    capabilities: normalizeCapabilities({
      ...(entitlements?.capabilities || {}),
      "ai.generate_content": true,
    }),
  };
};

const readPopTriviaRoomContext = async (roomCode = "") => {
  const safeRoomCode = normalizeRoomCode(roomCode || "");
  if (!safeRoomCode) {
    return { roomCode: "", roomData: {}, popTriviaSongCache: {} };
  }
  const rootRef = getRootRef();
  const [roomSnap, librarySnap] = await Promise.all([
    rootRef.collection("rooms").doc(safeRoomCode).get(),
    rootRef.collection("host_libraries").doc(safeRoomCode).get().catch(() => null),
  ]);
  return {
    roomCode: safeRoomCode,
    roomData: roomSnap?.data() || {},
    popTriviaSongCache: normalizePopTriviaSongCache(
      librarySnap?.exists ? librarySnap.get(POP_TRIVIA_CACHE_FIELD) : {}
    ),
  };
};

const writeResolvedPopTrivia = async ({
  songRef,
  cacheKey = "",
  source = "ai",
  questions = [],
  model = "",
} = {}) => {
  if (!songRef) return;
  await songRef.set({
    popTrivia: Array.isArray(questions) ? questions : [],
    popTriviaStatus: "ready",
    popTriviaSource: String(source || "ai").trim() || "ai",
    popTriviaCacheKey: String(cacheKey || "").trim() || null,
    popTriviaGeneratedAt: admin.firestore.FieldValue.serverTimestamp(),
    popTriviaUpdatedAt: admin.firestore.FieldValue.serverTimestamp(),
    popTriviaModel: String(model || "").trim() || null,
    popTriviaError: null,
    popTriviaLeaseAtMs: admin.firestore.FieldValue.delete(),
    popTriviaLeaseId: admin.firestore.FieldValue.delete(),
  }, { merge: true });
};

const writePopTriviaCacheEntry = async ({
  roomCode = "",
  cacheKey = "",
  seedRows = [],
  songData = {},
  source = "ai",
} = {}) => {
  const safeRoomCode = normalizeRoomCode(roomCode || "");
  const safeCacheKey = String(cacheKey || "").trim();
  if (!safeRoomCode || !safeCacheKey || !Array.isArray(seedRows) || !seedRows.length) return;
  const cacheEntry = {
    seedRows,
    songTitle: String(songData?.songTitle || songData?.title || "").trim(),
    artist: String(songData?.artist || "").trim(),
    source: String(source || "ai").trim() || "ai",
    updatedAtMs: nowMs(),
  };
  await getRootRef().collection("host_libraries").doc(safeRoomCode).set({
    [POP_TRIVIA_CACHE_FIELD]: {
      [safeCacheKey]: cacheEntry,
    },
  }, { merge: true });
};

const writeFallbackPopTrivia = async ({
  songRef,
  roomCode = "",
  cacheKey = "",
  songData = {},
  reason = "",
} = {}) => {
  const safeRoomCode = normalizeRoomCode(roomCode || songData?.roomCode || "");
  const seedRows = selectPopTriviaSeedRows({
    song: songData,
    aiRows: [],
    fallbackRows: buildFallbackPopTriviaSeedRows(songData),
    limit: DEFAULT_POP_TRIVIA_MAX_QUESTIONS,
  });
  const fallbackPopTriviaSource = seedRows.some((row) => String(row?.source || "").trim() === "curated_fact")
    ? "curated_fallback"
    : "fallback";
  const questions = normalizePopTriviaQuestions(seedRows, {
    limit: DEFAULT_POP_TRIVIA_MAX_QUESTIONS,
    idPrefix: `${safeRoomCode || "ROOM"}_${songRef?.id || "song"}`,
  });
  if (!songRef || !seedRows.length || !questions.length) {
    return { ok: false, status: "failed", reason: "fallback_generation_failed" };
  }
  await writeResolvedPopTrivia({
    songRef,
    cacheKey,
    source: fallbackPopTriviaSource,
    questions,
    model: fallbackPopTriviaSource,
  });
  if (safeRoomCode && cacheKey) {
    await writePopTriviaCacheEntry({
      roomCode: safeRoomCode,
      cacheKey,
      seedRows,
      songData,
      source: fallbackPopTriviaSource,
    });
  }
  return {
    ok: true,
    status: "ready",
    source: fallbackPopTriviaSource,
    questionCount: questions.length,
    reason: String(reason || "").trim() || "fallback",
  };
};

const claimPopTriviaGeneration = async ({
  songRef,
  now = nowMs(),
  leaseId = "",
} = {}) => admin.firestore().runTransaction(async (tx) => {
  const snap = await tx.get(songRef);
  if (!snap.exists) return { claimed: false, reason: "missing_song", songData: {} };
  const songData = snap.data() || {};
  const attempt = shouldAttemptPopTriviaGeneration(songData, { now });
  if (!attempt.ok) {
    return { claimed: false, reason: attempt.reason, songData };
  }
  const activeLeaseAtMs = Math.max(0, Number(songData?.popTriviaLeaseAtMs || 0));
  if (activeLeaseAtMs > 0 && (now - activeLeaseAtMs) < (2 * 60 * 1000)) {
    return { claimed: false, reason: "lease_active", songData };
  }
  tx.set(songRef, {
    popTriviaStatus: "pending",
    popTriviaError: null,
    popTriviaRequestedAtMs: now,
    popTriviaUpdatedAt: admin.firestore.FieldValue.serverTimestamp(),
    popTriviaLeaseAtMs: now,
    popTriviaLeaseId: String(leaseId || `poptrivia_${songRef.id}_${now}`).slice(0, 180),
  }, { merge: true });
  return { claimed: true, reason: attempt.reason, songData };
});

const resolvePopTriviaAiAccess = async (roomData = {}) => {
  const orgId = String(roomData?.orgId || "").trim();
  let entitlements = null;
  if (orgId) {
    try {
      entitlements = await readOrganizationEntitlements(orgId);
    } catch (error) {
      console.warn("popTrivia entitlements lookup failed", error?.message || error);
    }
  }
  let aiMeterEntitlements = entitlements;
  try {
    aiMeterEntitlements = await buildLyricsAiMeterEntitlements({
      roomData,
      entitlements,
    });
  } catch (error) {
    console.warn("popTrivia AI access entitlement lookup failed", error?.message || error);
  }
  const demoBypassEnabled = isRoomAiDemoBypassEnabled(roomData);
  const aiCapabilityEnabled = !!aiMeterEntitlements?.capabilities?.["ai.generate_content"];
  return {
    orgId,
    entitlements,
    aiMeterEntitlements,
    demoBypassEnabled,
    aiCapabilityEnabled,
    canCallAiProvider: demoBypassEnabled || aiCapabilityEnabled,
    shouldMeterUsage: !!orgId && (aiCapabilityEnabled || demoBypassEnabled),
  };
};

const enrichPopTriviaSongMetadata = async (song = {}) => {
  const context = buildPopTriviaSongContext(song);
  if (context.metadataConfidence === "grounded") return song;
  const title = String(context.songTitle || "").trim();
  const artist = String(context.artist || "").trim();
  if (!title || !artist || artist.toLowerCase() === "unknown") return song;
  try {
    const term = `${title} ${artist}`;
    const url = `https://itunes.apple.com/search?term=${encodeURIComponent(term)}&media=music&entity=song&limit=5`;
    const response = await fetch(url, { signal: AbortSignal.timeout(4500) });
    if (!response.ok) return song;
    const payload = await response.json();
    const metadataPatch = selectItunesPopTriviaMetadata(song, payload?.results || []);
    if (!Object.keys(metadataPatch).length) return song;
    return {
      ...song,
      album: song?.album || song?.albumName || metadataPatch.album || "",
      releaseYear: song?.releaseYear || song?.year || metadataPatch.releaseYear || "",
      genre: song?.genre || song?.primaryGenre || song?.primaryGenreName || metadataPatch.genre || "",
      durationSec: song?.durationSec || song?.duration || metadataPatch.durationSec || "",
      appleMusicId: song?.appleMusicId || metadataPatch.appleMusicId || "",
      albumArtUrl: song?.albumArtUrl || song?.artworkUrl || metadataPatch.albumArtUrl || "",
      popTriviaMetadataProvider: metadataPatch.metadataProvider || "itunes_search",
    };
  } catch (error) {
    console.warn("popTrivia metadata enrichment skipped", error?.message || error);
    return song;
  }
};

const processPopTriviaForSong = async ({
  songRef,
  songData = {},
  leaseId = "",
  reason = "",
} = {}) => {
  if (!songRef) {
    return { ok: false, status: "skipped", reason: "missing_song_ref" };
  }

  const safeRoomCode = normalizeRoomCode(songData?.roomCode || "");
  if (!safeRoomCode) {
    return { ok: false, status: "skipped", reason: "missing_room_code" };
  }

  const { roomData, popTriviaSongCache } = await readPopTriviaRoomContext(safeRoomCode);
  if (roomData?.popTriviaEnabled === false) {
    return { ok: false, status: "skipped", reason: "pop_trivia_disabled" };
  }

  const claim = await claimPopTriviaGeneration({
    songRef,
    now: nowMs(),
    leaseId: String(leaseId || reason || "auto_pop_trivia").slice(0, 180),
  });
  if (!claim.claimed) {
    return { ok: false, status: "skipped", reason: claim.reason };
  }

  const latestSongSnap = await songRef.get();
  const latestSong = latestSongSnap.data() || songData || {};
  const cacheKey = buildPopTriviaCacheKey({
    song: latestSong,
    buildSongKey,
  });
  const cacheEntry = cacheKey ? popTriviaSongCache?.[cacheKey] : null;
  const cachedSeedRows = normalizePopTriviaSeedRows(cacheEntry?.seedRows || [], {
    limit: DEFAULT_POP_TRIVIA_MAX_QUESTIONS,
  });
  if (cachedSeedRows.length) {
    const cachedQuestions = normalizePopTriviaQuestions(cachedSeedRows, {
      limit: DEFAULT_POP_TRIVIA_MAX_QUESTIONS,
      idPrefix: `${safeRoomCode}_${songRef.id}`,
    });
    if (cachedQuestions.length) {
      await writeResolvedPopTrivia({
        songRef,
        cacheKey,
        source: cacheEntry?.source || "cache",
        questions: cachedQuestions,
        model: "cache",
      });
      return { ok: true, status: "ready", source: "cache", questionCount: cachedQuestions.length };
    }
  }

  const triviaSong = await enrichPopTriviaSongMetadata(latestSong);
  const apiKey = GEMINI_API_KEY.value();
  if (!String(apiKey || "").trim()) {
    return writeFallbackPopTrivia({
      songRef,
      roomCode: safeRoomCode,
      cacheKey,
      songData: triviaSong,
      reason: "missing_api_key",
    });
  }

  const aiAccess = await resolvePopTriviaAiAccess(roomData);
  if (!aiAccess.canCallAiProvider) {
    return writeFallbackPopTrivia({
      songRef,
      roomCode: safeRoomCode,
      cacheKey,
      songData: triviaSong,
      reason: "ai_access_blocked",
    });
  }

  let aiUsageReservation = null;
  const aiUsageOperationId = appendUsageOperationIdSuffix(
    `pop-trivia:${songRef.id}:${leaseId || reason || crypto.randomUUID()}`,
    "ai"
  );
  if (aiAccess.shouldMeterUsage) {
    try {
      aiUsageReservation = await reserveOrganizationUsageOperation({
        orgId: aiAccess.orgId,
        entitlements: aiAccess.aiMeterEntitlements || aiAccess.entitlements,
        operationId: aiUsageOperationId,
        meterId: "ai_generate_content",
        capabilityId: "ai_generation",
        units: 1,
        source: "auto_pop_trivia_song",
        roomCode: safeRoomCode,
        surface: "backend",
      });
      if (!aiUsageReservation.created) throw new HttpsError("aborted", `AI usage operation is already ${aiUsageReservation.state || "reserved"}.`);
    } catch (error) {
      return writeFallbackPopTrivia({
        songRef,
        roomCode: safeRoomCode,
        cacheKey,
        songData: triviaSong,
        reason: error?.details?.reasonCode || "ai_provider_paused",
      });
    }
  }

  try {
    const prompt = buildGeminiPrompt("pop_trivia_song", buildPopTriviaSongContext(triviaSong));
    let geminiPayload;
    try {
      geminiPayload = await requestGeminiJson({ apiKey, prompt, responseMimeType: "application/json" });
    } finally {
      if (aiUsageReservation) {
        await settleOrganizationUsageOperation({
          orgId: aiAccess.orgId,
          operationId: aiUsageOperationId,
          periodKey: aiUsageReservation.periodKey,
        });
      }
    }
    const rawText = geminiPayload?.data?.candidates?.[0]?.content?.parts?.[0]?.text || "";
    const cleanText = rawText.replace(/```json|```/g, "").trim();
    const parsed = JSON.parse(cleanText);
    const seedRows = selectPopTriviaSeedRows({
      song: triviaSong,
      aiRows: parsed?.result || parsed || [],
      fallbackRows: buildFallbackPopTriviaSeedRows(triviaSong),
      limit: DEFAULT_POP_TRIVIA_MAX_QUESTIONS,
    });
    const triviaQuestions = normalizePopTriviaQuestions(seedRows, {
      limit: DEFAULT_POP_TRIVIA_MAX_QUESTIONS,
      idPrefix: `${safeRoomCode}_${songRef.id}`,
    });
    if (!seedRows.length || !triviaQuestions.length) {
      return writeFallbackPopTrivia({
        songRef,
        roomCode: safeRoomCode,
        cacheKey,
        songData: triviaSong,
        reason: "empty_ai_result",
      });
    }

    const selectedSourceSet = new Set(seedRows.map((row) => String(row?.source || "").trim() || "ai"));
    const resolvedPopTriviaSource = selectedSourceSet.has("ai")
      ? "ai"
      : (selectedSourceSet.has("curated_fact") ? "curated_fallback" : "fallback");
    const resolvedPopTriviaModel = resolvedPopTriviaSource === "ai"
      ? (geminiPayload?.model || GEMINI_DEFAULT_MODEL)
      : resolvedPopTriviaSource;
    await writeResolvedPopTrivia({
      songRef,
      cacheKey,
      source: resolvedPopTriviaSource,
      questions: triviaQuestions,
      model: resolvedPopTriviaModel,
    });
    if (cacheKey) {
      await writePopTriviaCacheEntry({
        roomCode: safeRoomCode,
        cacheKey,
        seedRows,
        songData: triviaSong,
        source: resolvedPopTriviaSource,
      });
    }
    return {
      ok: true,
      status: "ready",
      source: resolvedPopTriviaSource,
      questionCount: triviaQuestions.length,
      model: resolvedPopTriviaModel,
    };
  } catch (error) {
    return writeFallbackPopTrivia({
      songRef,
      roomCode: safeRoomCode,
      cacheKey,
      songData: triviaSong,
      reason: String(error?.message || error || "generation_failed"),
    });
  }
};

const isTimedAdapterEnabledForRoom = (roomCode = "") => {
  if (!LYRICS_TIMED_ADAPTER_ENABLED_DEFAULT) return false;
  if (!LYRICS_TIMED_ADAPTER_ROOM_CODES.size) return true;
  return LYRICS_TIMED_ADAPTER_ROOM_CODES.has(normalizeRoomCode(roomCode));
};

const compactLyricsProviderTrace = (trace = []) =>
  (Array.isArray(trace) ? trace : [])
    .slice(0, 8)
    .map((entry) => ({
      provider: String(entry?.provider || "").trim().slice(0, 40) || "unknown",
      status: String(entry?.status || "").trim().slice(0, 32) || "miss",
      latencyMs: Math.max(0, Math.round(Number(entry?.latencyMs || 0))),
      detail: String(entry?.detail || "").trim().slice(0, 140),
    }));

const normalizeLyricsGenerationStatus = ({
  hasLyrics = false,
  hasTimedLyrics = false,
  needsUserToken = false,
  resolution = "",
} = {}) => {
  if (hasLyrics || hasTimedLyrics) return "resolved";
  if (needsUserToken) return "needs_user_token";
  const token = String(resolution || "").trim().toLowerCase();
  if (token === "disabled") return "disabled";
  if (token === "capability_blocked") return "capability_blocked";
  if (token === "apple_permission_denied" || token === "permission_denied") return "permission_denied";
  if (token.includes("error")) return "error";
  return "no_match";
};

const buildLyricsResolverDeps = ({
  timedAdapterEnabled = false,
} = {}) => ({
  db: admin.firestore(),
  buildSongKey,
  normalizeLyricsText,
  normalizeTimedLyrics,
  fetchImpl: fetch,
  getAppleMusicToken,
  parseTtml,
  fetchAiLyricsFallbackText,
  timedAdapterEnabled: !!timedAdapterEnabled,
  resolveTimedLyrics: null,
});

const toMillisSafe = (value) => {
  if (!value) return 0;
  if (typeof value === "number") return value;
  if (typeof value?.toMillis === "function") return value.toMillis();
  if (typeof value?.seconds === "number") return value.seconds * 1000;
  return 0;
};

const normalizeTrackApprovalState = (value = "") => String(value || "").trim().toLowerCase();
const normalizeTrackFeedbackState = (value = "") => {
  const safeValue = String(value || "").trim().toLowerCase();
  if (["suppressed", "observing", "healthy"].includes(safeValue)) return safeValue;
  return "";
};

const normalizeTrustedCatalogMap = (value = {}) => (
  value && typeof value === "object" && !Array.isArray(value) ? value : {}
);

const normalizeRoomYouTubeIndexEntry = (value = {}) => {
  const entry = value && typeof value === "object" && !Array.isArray(value) ? value : null;
  if (!entry) return null;
  const videoId = String(entry.videoId || entry.id || "").trim();
  if (!videoId) return null;
  const curatedAtMs = Math.max(0, Number(entry.curatedAtMs || 0) || 0);
  const lastValidatedAtMs = Math.max(0, Number(entry.lastValidatedAtMs || curatedAtMs || 0) || 0);
  const expiresAtMs = Math.max(
    0,
    Number(entry.expiresAtMs || 0) || (lastValidatedAtMs > 0 ? lastValidatedAtMs + YOUTUBE_INDEX_RETENTION_MS : 0),
  );
  if (expiresAtMs > 0 && expiresAtMs <= nowMs()) return null;
  return {
    ...entry,
    videoId,
    curatedAtMs,
    lastValidatedAtMs,
    expiresAtMs,
    rankingScore: Math.max(0, Number(entry.rankingScore || 0) || 0),
    canonicalSongId: String(entry.canonicalSongId || '').trim().slice(0, 220),
    appleMusicId: String(entry.appleMusicId || '').trim().slice(0, 220),
    backingCandidateId: String(entry.backingCandidateId || '').trim().slice(0, 260),
    backingProvider: String(entry.backingProvider || 'youtube').trim().toLowerCase().slice(0, 40) || 'youtube',
    providerTrackId: String(entry.providerTrackId || videoId).trim().slice(0, 220),
    titleIntentMatch: Math.max(0, Number(entry.titleIntentMatch || 0) || 0),
    durationFit: Math.max(0, Number(entry.durationFit || 0) || 0),
    sourceTrust: Math.max(0, Number(entry.sourceTrust || 0) || 0),
    backingTelemetry: entry.backingTelemetry && typeof entry.backingTelemetry === 'object' && !Array.isArray(entry.backingTelemetry)
      ? entry.backingTelemetry
      : null,
    sourceDiscovery: String(entry.sourceDiscovery || '').trim().slice(0, 80),
  };
};

const normalizeRoomYouTubeIndex = (value = []) => (
  Array.isArray(value)
    ? value.map((entry) => normalizeRoomYouTubeIndexEntry(entry)).filter(Boolean)
    : []
);

const HOST_ACCOUNT_YOUTUBE_INDEXES_COLLECTION = "youtube_indexes";
const HOST_ACCOUNT_YOUTUBE_INDEX_DOC_ID = "karaoke";
const GLOBAL_YOUTUBE_INDEXES_COLLECTION = "global_youtube_indexes";
const GLOBAL_YOUTUBE_INDEX_DOC_ID = "karaoke";
const ACCOUNT_YOUTUBE_INDEX_MAX_ENTRIES = 500;
const GLOBAL_YOUTUBE_INDEX_MAX_ENTRIES = 750;
const GLOBAL_YOUTUBE_PROMOTION_MIN_SUCCESS_COUNT = 2;
const NIGHTLY_YOUTUBE_INDEX_REFRESH_MAX_LIBRARIES = 10;
const NIGHTLY_YOUTUBE_INDEX_REFRESH_IDS_PER_LIBRARY = 12;
const NIGHTLY_YOUTUBE_INDEX_BACKFILL_MAX_LIBRARIES = 10;
const NIGHTLY_YOUTUBE_INDEX_BACKFILL_CANDIDATES_PER_LIBRARY = 20;

const clampIndexCounter = (value = 0) => Math.max(0, Math.min(999999, Math.round(Number(value || 0) || 0)));

const normalizeCuratedYouTubeIndexContribution = (value = {}) => {
  const entry = normalizeRoomYouTubeIndexEntry(value);
  if (!entry) return null;
  return {
    ...entry,
    source: "youtube",
    trackName: String(entry.trackName || value.title || "YouTube Track").trim().slice(0, 220) || "YouTube Track",
    artistName: String(entry.artistName || value.channelTitle || value.channel || "YouTube").trim().slice(0, 220) || "YouTube",
    artworkUrl100: String(entry.artworkUrl100 || value.thumbnail || "").trim().slice(0, 700),
    url: String(entry.url || `https://www.youtube.com/watch?v=${entry.videoId}`).trim().slice(0, 700),
    sourceDetail: String(entry.sourceDetail || value.sourceDetail || "Host-learned karaoke backing.").trim().slice(0, 240),
    sourceDiscovery: String(entry.sourceDiscovery || value.sourceDiscovery || "trusted_catalog").trim().slice(0, 80) || "trusted_catalog",
    qualityScore: Math.max(0, Number(entry.qualityScore || value.qualityScore || 0) || 0),
    rankingScore: Math.max(0, Number(entry.rankingScore || value.rankingScore || 0) || 0),
    canonicalSongId: String(entry.canonicalSongId || value.canonicalSongId || "").trim().slice(0, 220),
    appleMusicId: String(entry.appleMusicId || value.appleMusicId || "").trim().slice(0, 220),
    backingCandidateId: String(entry.backingCandidateId || value.backingCandidateId || "").trim().slice(0, 260),
    backingProvider: String(entry.backingProvider || value.backingProvider || "youtube").trim().toLowerCase().slice(0, 40) || "youtube",
    providerTrackId: String(entry.providerTrackId || value.providerTrackId || entry.videoId || "").trim().slice(0, 220),
    backingTelemetry: entry.backingTelemetry && typeof entry.backingTelemetry === "object" ? entry.backingTelemetry : null,
    usageCount: clampIndexCounter(entry.usageCount || value.usageCount),
    successCount: clampIndexCounter(entry.successCount || value.successCount),
    failureCount: clampIndexCounter(entry.failureCount || value.failureCount),
    usageCountDelta: clampIndexCounter(value.usageCountDelta),
    successCountDelta: clampIndexCounter(value.successCountDelta),
    failureCountDelta: clampIndexCounter(value.failureCountDelta),
  };
};

const mergeCuratedYouTubeIndexEntries = ({ existing = [], contributions = [], layer = "account" } = {}) => {
  const merged = new Map();
  normalizeRoomYouTubeIndex(existing).forEach((entry) => {
    merged.set(entry.videoId, {
      ...entry,
      usageCount: clampIndexCounter(entry.usageCount),
      successCount: clampIndexCounter(entry.successCount),
      failureCount: clampIndexCounter(entry.failureCount),
    });
  });
  contributions.forEach((rawContribution) => {
    const contribution = normalizeCuratedYouTubeIndexContribution(rawContribution);
    if (!contribution) return;
    const previous = merged.get(contribution.videoId) || {};
    const curatedAtMs = Math.max(0, Number(previous.curatedAtMs || contribution.curatedAtMs || nowMs()) || nowMs());
    const lastValidatedAtMs = Math.max(
      Number(previous.lastValidatedAtMs || 0),
      Number(contribution.lastValidatedAtMs || 0),
      contribution.playable === true ? nowMs() : 0,
    );
    const usageCount = clampIndexCounter(previous.usageCount) + clampIndexCounter(contribution.usageCount) + clampIndexCounter(contribution.usageCountDelta);
    const successCount = clampIndexCounter(previous.successCount) + clampIndexCounter(contribution.successCount) + clampIndexCounter(contribution.successCountDelta);
    const failureCount = clampIndexCounter(previous.failureCount) + clampIndexCounter(contribution.failureCount) + clampIndexCounter(contribution.failureCountDelta);
    merged.set(contribution.videoId, {
      ...previous,
      ...contribution,
      sourceReason: layer === "global" ? "global_learned" : "account_learned",
      resolutionLayer: layer === "global" ? "global_learned_index" : "account_index",
      sourceDetail: layer === "global"
        ? "Globally learned karaoke backing from successful host performances."
        : "Account-learned karaoke backing from this host workspace.",
      curatedAtMs,
      lastValidatedAtMs,
      expiresAtMs: lastValidatedAtMs > 0 ? lastValidatedAtMs + YOUTUBE_INDEX_RETENTION_MS : contribution.expiresAtMs,
      usageCount,
      successCount,
      failureCount,
    });
  });
  return [...merged.values()]
    .filter((entry) => entry && !isKnownNonEmbeddableYouTubePayload(entry))
    .filter((entry) => !normalizeRoomYouTubeIndexEntry(entry) ? false : true)
    .sort((left, right) => {
      const leftScore = (Number(left.successCount || 0) * 8) + (Number(left.usageCount || 0) * 3) + Number(left.qualityScore || 0) + Math.max(0, Number(left.rankingScore || 0) - 50) - (Number(left.failureCount || 0) * 12);
      const rightScore = (Number(right.successCount || 0) * 8) + (Number(right.usageCount || 0) * 3) + Number(right.qualityScore || 0) + Math.max(0, Number(right.rankingScore || 0) - 50) - (Number(right.failureCount || 0) * 12);
      if (rightScore !== leftScore) return rightScore - leftScore;
      return Number(right.lastValidatedAtMs || right.curatedAtMs || 0) - Number(left.lastValidatedAtMs || left.curatedAtMs || 0);
    });
};

const filterGlobalYouTubePromotionCandidates = (entries = []) => (
  (Array.isArray(entries) ? entries : [])
    .map((entry) => normalizeCuratedYouTubeIndexContribution(entry))
    .filter((entry) => {
      if (!entry || entry.playable !== true || entry.embeddable !== true) return false;
      if (clampIndexCounter(entry.failureCount) + clampIndexCounter(entry.failureCountDelta) > 0) return false;
      const successes = clampIndexCounter(entry.successCount) + clampIndexCounter(entry.successCountDelta);
      const usage = clampIndexCounter(entry.usageCount) + clampIndexCounter(entry.usageCountDelta);
      return successes >= GLOBAL_YOUTUBE_PROMOTION_MIN_SUCCESS_COUNT || usage >= GLOBAL_YOUTUBE_PROMOTION_MIN_SUCCESS_COUNT;
    })
);

const readRoomHostLibrary = async (roomCode = "") => {
  const safeRoomCode = normalizeRoomCode(roomCode || "");
  if (!safeRoomCode) return { trustedCatalog: {}, ytIndex: [] };
  try {
    const snap = await getRootRef().collection("host_libraries").doc(safeRoomCode).get();
    const data = snap.data() || {};
    return {
      trustedCatalog: normalizeTrustedCatalogMap(data.trustedCatalog || {}),
      ytIndex: normalizeRoomYouTubeIndex(data.ytIndex || []),
    };
  } catch (_error) {
    return { trustedCatalog: {}, ytIndex: [] };
  }
};

const _readRoomTrustedCatalog = async (roomCode = "") => {
  const library = await readRoomHostLibrary(roomCode);
  return library.trustedCatalog || {};
};

const getTrustedSongEntry = (trustedCatalog = {}, songId = "") => {
  const safeSongId = String(songId || "").trim();
  if (!safeSongId) return null;
  const value = trustedCatalog?.[safeSongId];
  return value && typeof value === "object" && !Array.isArray(value) ? value : null;
};

const getTrackLayer = (track = {}, trustedSongEntry = null) => {
  const safeTrackId = String(track?.id || track?.trackId || "").trim();
  if (!safeTrackId || !trustedSongEntry) return "global_catalog";
  if (String(trustedSongEntry.hostFavoriteTrackId || "").trim() === safeTrackId) return "host_favorite";
  if (String(trustedSongEntry.roomRecentTrackId || "").trim() === safeTrackId) return "room_recent";
  return normalizeTrackApprovalState(track?.approvalState) === "approved"
    ? "global_approved"
    : "global_catalog";
};

const getTrackLayerScore = (track = {}, trustedSongEntry = null) => {
  const layer = getTrackLayer(track, trustedSongEntry);
  if (layer === "host_favorite") return 120;
  if (layer === "room_recent") return 90;
  if (layer === "global_approved") return 70;
  return 35;
};

const buildTrackUsageScore = (track = {}) => {
  const qualityScore = Math.max(0, Number(track?.qualityScore || 0));
  const rankingSignal = Math.min(80, Math.max(0, Number(track?.rankingScore || 0) - 50));
  const successScore = Math.min(40, Math.max(0, Number(track?.successCount || 0)) * 4);
  const usageScore = Math.min(24, Math.max(0, Number(track?.usageCount || 0)) * 2);
  const failurePenalty = Math.min(24, Math.max(0, Number(track?.failureCount || 0)) * 6);
  const approvalState = normalizeTrackApprovalState(track?.approvalState);
  const approvalScore = approvalState === "approved"
    ? 20
    : approvalState === "submitted"
      ? 10
      : 0;
  return qualityScore + rankingSignal + successScore + usageScore + approvalScore - failurePenalty;
};

const scoreTrack = (track = {}, trustedSongEntry = null) => {
  const source = String(track.source || "").toLowerCase();
  const sourceScore = source === "apple" ? 30 : source === "youtube" ? 20 : source ? 10 : 0;
  const backingScore = track.backingOnly ? 5 : 0;
  const layerScore = getTrackLayerScore(track, trustedSongEntry);
  const usageScore = buildTrackUsageScore(track);
  return sourceScore + backingScore + layerScore + usageScore;
};

const _pickBestTrack = (tracks = [], trustedSongEntry = null) => {
  if (!Array.isArray(tracks) || !tracks.length) return null;
  return tracks
    .slice()
    .sort((a, b) => {
      const scoreDiff = scoreTrack(b, trustedSongEntry) - scoreTrack(a, trustedSongEntry);
      if (scoreDiff !== 0) return scoreDiff;
      return toMillisSafe(b.updatedAt) - toMillisSafe(a.updatedAt);
    })
    .map((track) => ({
      ...track,
      resolutionLayer: getTrackLayer(track, trustedSongEntry),
      resolutionScore: scoreTrack(track, trustedSongEntry),
    }))[0];
};

const buildTrackCandidateSummary = (track = {}, trustedSongEntry = null) => ({
  id: track.id || "",
  source: track.source || "",
  mediaUrl: track.mediaUrl || "",
  appleMusicId: track.appleMusicId || "",
  duration: track.duration || null,
  backingOnly: !!track.backingOnly,
  audioOnly: !!track.audioOnly,
  updatedAt: track.updatedAt || null,
  approvalState: normalizeTrackApprovalState(track.approvalState),
  qualityScore: Number(track.qualityScore || 0),
  rankingScore: Number(track.rankingScore || 0),
  backingCandidateId: String(track.backingCandidateId || '').trim(),
  canonicalSongId: String(track.canonicalSongId || track.songId || '').trim(),
  backingTelemetry: track.backingTelemetry && typeof track.backingTelemetry === 'object' ? track.backingTelemetry : null,
  successCount: Number(track.successCount || 0),
  usageCount: Number(track.usageCount || 0),
  failureCount: Number(track.failureCount || 0),
  avoidRoomCount: Math.max(0, Number(track.globalAvoidRoomCount || 0)),
  globalFeedbackState: normalizeTrackFeedbackState(track.globalFeedbackState),
  layer: getTrackLayer(track, trustedSongEntry),
  score: scoreTrack(track, trustedSongEntry),
});

const normalizeCatalogMatchText = (value = "") => cleanCatalogTitle(value)
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, " ")
  .trim()
  .replace(/\s+/g, " ");

const tokenizeCatalogMatchText = (value = "") => normalizeCatalogMatchText(value)
  .split(" ")
  .map((token) => token.trim())
  .filter(Boolean);

const countCatalogTokenOverlap = (left = [], right = []) => {
  if (!left.length || !right.length) return 0;
  const rightSet = new Set(right);
  return left.reduce((count, token) => count + (rightSet.has(token) ? 1 : 0), 0);
};

const scoreCatalogTextMatch = (needle = "", haystack = "") => {
  const safeNeedle = normalizeCatalogMatchText(needle);
  const safeHaystack = normalizeCatalogMatchText(haystack);
  if (!safeNeedle || !safeHaystack) return 0;
  if (safeNeedle === safeHaystack) return 120;
  if (safeHaystack.includes(safeNeedle) || safeNeedle.includes(safeHaystack)) return 80;
  return countCatalogTokenOverlap(
    tokenizeCatalogMatchText(safeNeedle),
    tokenizeCatalogMatchText(safeHaystack),
  ) * 12;
};

const buildYouTubeIndexCandidateSummaries = ({
  ytIndex = [],
  songId = "",
  title = "",
  artist = "",
} = {}) => {
  const requestSongIds = new Set(
    [
      String(songId || "").trim(),
      ...deriveCanonicalSongCandidates({ title, artist }).map((candidate) => String(candidate.songId || "").trim()),
    ].filter(Boolean),
  );
  const requestTitle = String(title || "").trim();
  const requestArtist = String(artist || "").trim();
  return normalizeRoomYouTubeIndex(ytIndex)
    .map((entry, index) => {
      const videoId = String(entry?.videoId || entry?.id || "").trim();
      const mediaUrl = String(entry?.url || (videoId ? `https://www.youtube.com/watch?v=${videoId}` : "")).trim();
      const candidateTitle = String(entry?.trackName || entry?.title || "").trim();
      const candidateArtist = String(entry?.artistName || entry?.channelTitle || entry?.channel || "YouTube").trim() || "YouTube";
      const candidateSongIds = deriveCanonicalSongCandidates({
        title: candidateTitle,
        artist: candidateArtist,
      }).map((candidate) => String(candidate.songId || "").trim()).filter(Boolean);
      const exactSongMatch = candidateSongIds.some((candidateSongId) => requestSongIds.has(candidateSongId));
      const titleScore = scoreCatalogTextMatch(requestTitle, candidateTitle);
      const artistScore = scoreCatalogTextMatch(requestArtist, candidateArtist);
      if (!exactSongMatch && (titleScore + artistScore) < 48) return null;
      const qualityScore = Math.max(0, Number(entry?.qualityScore || 0));
      const rankingScore = Math.max(0, Number(entry?.rankingScore || 0));
      const rankingSignal = Math.min(80, Math.max(0, rankingScore - 50));
      const successCount = Math.max(0, Number(entry?.successCount || 0));
      const usageCount = Math.max(0, Number(entry?.usageCount || 0));
      const failureCount = Math.max(0, Number(entry?.failureCount || 0));
      const popularityScore = Math.min(40, successCount * 4) + Math.min(24, usageCount * 2) - Math.min(24, failureCount * 6);
      const exactMatchScore = exactSongMatch ? 170 : 0;
      return {
        id: videoId ? `yt_index:${videoId}` : `yt_index:${index}`,
        source: "youtube",
        mediaUrl,
        appleMusicId: "",
        duration: null,
        backingOnly: true,
        audioOnly: false,
        updatedAt: null,
        approvalState: entry?.playable === false ? "candidate" : "approved",
        qualityScore,
        rankingScore,
        backingCandidateId: String(entry?.backingCandidateId || '').trim(),
        canonicalSongId: String(entry?.canonicalSongId || '').trim(),
        backingTelemetry: entry?.backingTelemetry && typeof entry.backingTelemetry === 'object' ? entry.backingTelemetry : null,
        successCount,
        usageCount,
        failureCount,
        layer: "room_index",
        score: exactMatchScore + titleScore + artistScore + qualityScore + rankingSignal + popularityScore,
        label: String(entry?.sourceDetail || "Host-curated YouTube").trim() || "Host-curated YouTube",
      };
    })
    .filter((entry) => entry && entry.mediaUrl)
    .sort((left, right) => Number(right.score || 0) - Number(left.score || 0))
    .slice(0, 5);
};

const ensureSongLyricsAdmin = async ({
  songId,
  title,
  artist,
  lyrics,
  lyricsTimed,
  lyricsSource,
  appleMusicId,
  language = "en",
  verifiedBy = "system",
}) => {
  const safeSongId = String(songId || "").trim();
  if (!safeSongId) return { songId: "", hasLyrics: false, hasTimedLyrics: false };

  const normalizedLyrics = normalizeLyricsText(lyrics || "");
  const normalizedTimed = normalizeTimedLyrics(lyricsTimed);
  if (!normalizedLyrics && !normalizedTimed.length) {
    return { songId: safeSongId, hasLyrics: false, hasTimedLyrics: false };
  }

  const ref = admin.firestore().collection("song_lyrics").doc(safeSongId);
  const snap = await ref.get();
  const payload = {
    songId: safeSongId,
    title: (title || "").trim() || null,
    artist: (artist || "").trim() || null,
    lyrics: normalizedLyrics || "",
    lyricsTimed: normalizedTimed.length ? normalizedTimed : null,
    hasTimedLyrics: normalizedTimed.length > 0,
    lineCount: normalizedTimed.length
      || (normalizedLyrics ? normalizedLyrics.split("\n").filter(Boolean).length : 0),
    lyricsSource: (lyricsSource || (normalizedTimed.length ? "timed" : "text")).trim() || null,
    appleMusicId: appleMusicId ? String(appleMusicId) : null,
    language: (language || "en").trim() || "en",
    verifiedBy: (verifiedBy || "system").trim() || "system",
    updatedAt: admin.firestore.FieldValue.serverTimestamp(),
  };

  if (!snap.exists) {
    payload.createdAt = admin.firestore.FieldValue.serverTimestamp();
  }

  await ref.set(payload, { merge: true });
  await admin.firestore().collection("songs").doc(safeSongId).set(
    {
      hasLyrics: true,
      hasTimedLyrics: normalizedTimed.length > 0,
      canonicalLyricsSource: payload.lyricsSource || null,
      canonicalLyricsUpdatedAt: admin.firestore.FieldValue.serverTimestamp(),
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    },
    { merge: true }
  );

  return {
    songId: safeSongId,
    hasLyrics: true,
    hasTimedLyrics: normalizedTimed.length > 0,
  };
};

const isSongVerified = (songDoc) => {
  const meta = songDoc?.verifiedMeta || {};
  return !!(meta.title && meta.artist && meta.artworkUrl);
};

const buildGeminiPrompt = (type, context) => {
  if (type === "bingo_board") {
    const { title, size, mode } = context || {};
    const count = Number(size || 5) ** 2;
    if (mode === "mystery") {
      return `Generate ${count} pairs of (Clue, Song Title, Artist) for a music bingo game with the theme "${title}". Format strictly as JSON array of objects: [{"clue": "...", "title": "...", "artist": "..."}]. Do not include markdown.`;
    }
    return `Generate ${count} short bingo terms (1-3 words) for a bingo game with the theme "${title}". Format strictly as JSON array of strings. Do not include markdown.`;
  }
  if (type === "lyrics") {
    const { title, artist } = context || {};
    return `Generate the full lyrics for the song "${title}" by "${artist}". Format strictly as JSON object with a single key "lyrics" containing the text with \\n for line breaks. Example: {"lyrics": "Line 1\\nLine 2"}. Do not include markdown.`;
  }
  if (type === "selfie_prompt") {
    return 'Generate 5 short, funny selfie prompts for a karaoke crowd. Format strictly as JSON array of strings. Do not include markdown.';
  }
  if (type === "doodle_lyrics") {
    const { topic, count } = context || {};
    const total = clampNumber(count || 12, 5, 30, 12);
    return `Generate ${total} short, recognizable lyric lines for a karaoke drawing game. Keep each line under 8 words. Theme: "${topic || 'karaoke hits'}". Format strictly as JSON array of strings. Do not include markdown.`;
  }
  if (type === "doodle_prompts") {
    const topic = Array.isArray(context)
      ? String(context[0] || "").trim()
      : String(context?.topic || "").trim();
    const total = clampNumber(
      Array.isArray(context) ? 12 : (context?.count || 12),
      5,
      30,
      12
    );
    return `Generate ${total} short, visual drawing prompts for a party doodle game. Theme: "${topic || 'fun drawings'}". Format strictly as JSON array of strings. Do not include markdown.`;
  }
  const songs = Array.isArray(context)
    ? context.slice(0, 5).map((s) => `${s.songTitle} by ${s.artist}`).join(", ")
    : "";
  const singleSong = (!Array.isArray(context) && context && typeof context === "object")
    ? context
    : null;
  if (type === "pop_trivia_song") {
    const songTitle = String(singleSong?.songTitle || "").trim() || "Unknown Song";
    const artist = String(singleSong?.artist || "").trim() || "Unknown Artist";
    const metadataConfidence = String(singleSong?.metadataConfidence || "").trim() || "limited";
    const sourceMode = String(singleSong?.sourceMode || "").trim() || "catalog";
    const metadata = (singleSong?.metadata && typeof singleSong.metadata === "object" && !Array.isArray(singleSong.metadata))
      ? Object.entries(singleSong.metadata)
        .map(([k, v]) => `${k}: ${String(v || "").trim()}`)
        .filter((entry) => !entry.endsWith(": "))
      : [];
    const metadataLine = metadata.length ? metadata.join(", ") : "none";
    return `Create 4 high-quality multiple-choice pop-up trivia questions about the requested song "${songTitle}" by "${artist}".
Tone: funny, clever, and insightful (VH1 Pop-Up Video vibe), never mean.
Audience: fans answering quickly on phones while the song plays.
Known metadata: ${metadataLine}.
Metadata confidence: ${metadataConfidence}.
Source mode: ${sourceMode}.
Rules:
- Each question must be answerable in under 10 seconds.
- Every correct answer must be supported directly by Known metadata above or by a universally established, high-confidence fact about this exact song or artist. Never guess.
- The set must feel like real music trivia, not internal app metadata confirmation. The title and artist are already visible, so do not ask players to identify either one.
- Every question must mention the song title, artist, or an unmistakable title phrase.
- Use four distinct angles when the evidence supports them: song fact, artist fact, album/release context, genre/duration, hook recognition, or a concrete arrangement detail.
- Use one of these categories per question: song_fact, artist_fact, fan_fact, hook_recognition, arrangement, safe_fact.
- Prefer album, release year, genre, and duration questions when those fields appear in Known metadata. Use widely established facts only when confidence is high.
- Do not ask generic filler such as "which song section sets up the story", "what usually helps most in karaoke", or "which production trick is common".
- Keep each answer option concise (under 45 characters).
- Wrong answers should be plausible music alternatives and funny, not random nonsense, placeholders, or generic labels.
- Do not mention or ask about the current singer, performer, host, crowd, room, microphone, karaoke technique, or stage strategy.
- Avoid subjective taste, opinion, vibe, strategy, or "best" questions. Avoid obscure deep-cut facts and avoid speculation.
- If metadata confidence is sparse or source mode is youtube/custom, do not invent release years, chart stats, album facts, music-video facts, or artist biography facts.
- In sparse mode, do not ask "who released", "what year", "which album", award, chart, label, music-video, or biography questions.
- In sparse mode, return fewer than 4 questions rather than padding the set with generic or speculative filler.
- Every row must contain exactly four distinct answer choices: one correct answer and three plausible distractors.
Format strictly as JSON array of objects:
[{"q":"...","correct":"...","w1":"...","w2":"...","w3":"...","category":"hook_recognition"}]
Do not include markdown.`;
  }
  if (type === "trivia") {
    return `Generate 3 trivia questions based on: ${songs}. Format strictly as JSON array of objects: [{q, correct, w1, w2, w3}]`;
  }
  return `Generate 3 "Would You Rather" questions based on: ${songs}. Format strictly as JSON array: [{q, a, b}]`;
};

const fetchAiLyricsFallbackText = async (title, artist) => {
  if (!LYRICS_AI_FALLBACK_ENABLED_DEFAULT) return null;
  const safeTitle = normalizeLyricsText(title);
  if (!safeTitle) return null;
  const safeArtist = normalizeLyricsText(artist || "Unknown") || "Unknown";
  const apiKey = GEMINI_API_KEY.value();
  if (!apiKey) {
    console.warn("autoAppleLyrics AI fallback skipped: GEMINI_API_KEY not configured.");
    return null;
  }
  const prompt = buildGeminiPrompt("lyrics", { title: safeTitle, artist: safeArtist });
  try {
    const { data, model } = await requestGeminiJson({
      apiKey,
      prompt,
      responseMimeType: "application/json",
    });
    const rawText = data?.candidates?.[0]?.content?.parts?.[0]?.text || "";
    const cleanText = rawText.replace(/```json|```/g, "").trim();
    if (!cleanText) return null;
    const parsed = JSON.parse(cleanText);
    const lyrics = normalizeLyricsText(parsed?.lyrics || "");
    if (!lyrics) return null;
    const usage = data?.usageMetadata || {};
    const promptTokens = Math.max(0, Number(usage?.promptTokenCount || 0));
    const outputTokens = Math.max(0, Number(usage?.candidatesTokenCount || 0));
    const totalTokens = Math.max(0, Number(usage?.totalTokenCount || (promptTokens + outputTokens)));
    const pricing = getGeminiModelPricing(model);
    const estimatedCostUsd = ((promptTokens / 1000000) * pricing.inputUsdPer1M)
      + ((outputTokens / 1000000) * pricing.outputUsdPer1M);
    return {
      lyrics,
      usage: {
        model,
        promptTokens,
        outputTokens,
        totalTokens,
        estimatedCostUsd: Number(estimatedCostUsd.toFixed(6)),
        inputUsdPer1M: pricing.inputUsdPer1M,
        outputUsdPer1M: pricing.outputUsdPer1M,
      },
    };
  } catch (err) {
    console.warn("autoAppleLyrics AI fallback failed", err?.message || err);
    return null;
  }
};

exports.itunesSearch = onCall({ cors: true }, async (request) => {
  checkRateLimit(request.rawRequest, "itunes");
  requireAuth(request);
  enforceAppCheckIfEnabled(request, "itunes_search");
  const term = request.data?.term || "";
  ensureString(term, "term");
  const limit = clampNumber(request.data?.limit || 6, 1, 25, 6);
  const usageSource = resolveUsageSource(request.data?.usageContext?.source, "itunes_search");
  const usageRoomCode = normalizeRoomCode(request.data?.roomCode || "");
  if (usageRoomCode) {
    try {
      const orgId = await resolveUsageOrgIdFromRoomCode(usageRoomCode);
      if (orgId) {
        await trackOrganizationUsageAnalytics({
          orgId,
          signalId: "itunes_search",
          source: usageSource,
        });
      }
    } catch (error) {
      console.warn("itunesSearch usage analytics failed", error?.message || error);
    }
  }
  const url = `https://itunes.apple.com/search?term=${encodeURIComponent(term)}&media=music&entity=song&limit=${limit}`;
  const res = await fetch(url);
  if (!res.ok) {
    throw new HttpsError("unavailable", "iTunes search failed.");
  }
  const data = await res.json();
  return { results: data.results || [] };
});

exports.ensureSong = onCall({ cors: true }, async (request) => {
  checkRateLimit(request.rawRequest, "ensure_song", { perMinute: 30, perHour: 180 });
  enforceAppCheckIfEnabled(request, "ensure_song");
  await requireCatalogContributor(request, {
    deniedMessage: "Host or moderator access required to write catalog songs.",
  });
  const data = request.data || {};
  const title = (data.title || "").trim();
  if (!title) {
    throw new HttpsError("invalid-argument", "title is required.");
  }
  const res = await ensureSongAdmin({
    title,
    artist: data.artist || "Unknown",
    artworkUrl: data.artworkUrl || "",
    itunesId: data.itunesId || "",
    appleMusicId: data.appleMusicId || "",
    aliases: Array.isArray(data.aliases) ? data.aliases : [],
    verifyMeta: data.verifyMeta || false,
    verifiedBy: data.verifiedBy || "host",
  });
  return { songId: res?.songId || buildSongKey(title, data.artist || "Unknown") };
});

exports.ensureTrack = onCall({ cors: true }, async (request) => {
  checkRateLimit(request.rawRequest, "ensure_track", { perMinute: 30, perHour: 180 });
  enforceAppCheckIfEnabled(request, "ensure_track");
  await requireCatalogContributor(request, {
    deniedMessage: "Host or moderator access required to write catalog tracks.",
  });
  const data = request.data || {};
  if (!data.songId) {
    throw new HttpsError("invalid-argument", "songId is required.");
  }
  const res = await ensureTrackAdmin({
    songId: data.songId,
    source: data.source || "custom",
    mediaUrl: data.mediaUrl || "",
    appleMusicId: data.appleMusicId || "",
    label: data.label || null,
    duration: data.duration ?? null,
    audioOnly: !!data.audioOnly,
    backingOnly: !!data.backingOnly,
    addedBy: data.addedBy || "",
    approvalState: data.approvalState || "",
    qualityScore: data.qualityScore ?? null,
    backingCandidateId: data.backingCandidateId || "",
    canonicalSongId: data.canonicalSongId || data.songId || "",
    rankingScore: data.rankingScore ?? null,
    backingTelemetry: data.backingTelemetry || null,
  });
  return { trackId: res?.trackId || null };
});

exports.recordTrackFeedback = onCall({ cors: true }, async (request) => {
  checkRateLimit(request.rawRequest, "record_track_feedback", { perMinute: 30, perHour: 240 });
  enforceAppCheckIfEnabled(request, "record_track_feedback");
  const { uid } = await requireCatalogContributor(request, {
    deniedMessage: "Host or moderator access required to record track feedback.",
  });
  const data = request.data || {};
  const rating = String(data.rating || "").trim().toLowerCase();
  if (!["up", "down"].includes(rating)) {
    throw new HttpsError("invalid-argument", "rating must be 'up' or 'down'.");
  }

  const songTitle = String(data.songTitle || data.title || "").trim();
  const artist = String(data.artist || "Unknown").trim() || "Unknown";
  const mediaUrl = String(data.mediaUrl || "").trim();
  const appleMusicId = String(data.appleMusicId || "").trim();
  const sourceGuess = String(data.source || data.trackSource || "").trim().toLowerCase()
    || (appleMusicId ? "apple" : extractYouTubeId(mediaUrl) ? "youtube" : "custom");
  const canonicalMatch = await resolveCanonicalTrackIdentityInternal({
    songId: data.songId || "",
    title: songTitle,
    artist,
    source: sourceGuess,
    mediaUrl,
    appleMusicId,
  });
  const canonicalTitle = String(canonicalMatch?.title || songTitle).trim() || songTitle;
  const canonicalArtist = String(canonicalMatch?.artist || artist).trim() || artist;
  const songResult = canonicalTitle
    ? await ensureSongAdmin({
      title: canonicalTitle,
      artist: canonicalArtist,
      artworkUrl: data.albumArtUrl || "",
      verifyMeta: false,
      verifiedBy: data.verifiedBy || uid || "host_feedback",
    })
    : null;
  const songId = String(
    canonicalMatch?.songId
    || data.songId
    || songResult?.songId
    || buildSongKey(canonicalTitle || "Unknown", canonicalArtist || "Unknown")
  ).trim();
  if (!songId) {
    throw new HttpsError("invalid-argument", "songTitle/title or songId is required.");
  }

  let trackId = String(canonicalMatch?.trackId || data.trackId || "").trim();
  if (!trackId && (mediaUrl || appleMusicId)) {
    const trackResult = await ensureTrackAdmin({
      songId,
      source: sourceGuess,
      mediaUrl,
      appleMusicId,
      label: data.label || null,
      duration: data.duration ?? null,
      audioOnly: !!data.audioOnly,
      backingOnly: !!data.backingOnly,
      addedBy: uid || data.hostName || "Host",
      approvalState: data.approvalState || "",
      qualityScore: data.qualityScore ?? null,
      backingCandidateId: data.backingCandidateId || "",
      canonicalSongId: data.canonicalSongId || songId || "",
      rankingScore: data.rankingScore ?? null,
      backingTelemetry: data.backingTelemetry || null,
    });
    trackId = String(trackResult?.trackId || "").trim();
  }
  if (!trackId) {
    throw new HttpsError("invalid-argument", "trackId or backing media is required.");
  }

  const trackRef = admin.firestore().collection("tracks").doc(trackId);
  const roomCode = normalizeRoomCode(data.roomCode || "");
  const now = admin.firestore.FieldValue.serverTimestamp();
  const backingMetadata = {};
  const backingCandidateId = String(data.backingCandidateId || "").trim().slice(0, 260);
  const canonicalBackingSongId = String(data.canonicalSongId || songId || "").trim().slice(0, 220);
  const rankingScore = Number(data.rankingScore);
  if (backingCandidateId) backingMetadata.backingCandidateId = backingCandidateId;
  if (canonicalBackingSongId) backingMetadata.canonicalSongId = canonicalBackingSongId;
  if (Number.isFinite(rankingScore)) backingMetadata.rankingScore = Math.max(0, rankingScore);
  if (data.backingTelemetry && typeof data.backingTelemetry === "object" && !Array.isArray(data.backingTelemetry)) {
    backingMetadata.backingTelemetry = data.backingTelemetry;
  }
  const backingFeedbackBase = {
    rating,
    actorUid: uid,
    actorRole: data.actorRole || "host",
    roomCode,
    songId,
    title: canonicalTitle,
    artist: canonicalArtist,
    trackId,
    source: sourceGuess,
    mediaUrl,
    appleMusicId,
    backingCandidateId: backingCandidateId || data.backingCandidateId || "",
    rankingScore: Number.isFinite(rankingScore) ? Math.max(0, rankingScore) : null,
    backingTelemetry: data.backingTelemetry || null,
    qualityScore: data.qualityScore ?? null,
    label: data.label || "",
    now,
  };

  if (rating === "up") {
    await trackRef.set({
      updatedAt: now,
      lastPositiveFeedbackAt: now,
      lastPositiveFeedbackRoomCode: roomCode || null,
      ...backingMetadata,
    }, { merge: true });
    const backingFeedbackRecord = await recordCanonicalBackingFeedbackAdmin({
      ...backingFeedbackBase,
      extractYouTubeId,
    });
    return { trackId, songId, recorded: true, rating, backingCandidateId: backingFeedbackRecord?.candidateId || backingCandidateId || "" };
  }

  await admin.firestore().runTransaction(async (tx) => {
    const snap = await tx.get(trackRef);
    const existing = snap.data() || {};
    const existingAvoidRoomCodes = Array.isArray(existing?.avoidRoomCodes)
      ? existing.avoidRoomCodes.map((entry) => normalizeRoomCode(entry)).filter(Boolean)
      : [];
    const hasRoomEvidence = !!roomCode && existingAvoidRoomCodes.includes(roomCode);
    const nextAvoidRoomCodes = roomCode && !hasRoomEvidence
      ? [...existingAvoidRoomCodes, roomCode].slice(-20)
      : existingAvoidRoomCodes;
    const distinctAvoidRoomCount = roomCode ? nextAvoidRoomCodes.length : existingAvoidRoomCodes.length;
    const nextFeedbackState = distinctAvoidRoomCount >= 2
      ? "suppressed"
      : distinctAvoidRoomCount >= 1
        ? "observing"
        : normalizeTrackFeedbackState(existing?.globalFeedbackState) || "healthy";
    const currentApprovalState = normalizeTrackApprovalState(existing?.approvalState || data.approvalState || "candidate") || "candidate";
    const qualityScore = Math.max(0, Number(existing?.qualityScore || 0));
    const updates = {
      songId,
      source: sourceGuess || existing?.source || null,
      mediaUrl: mediaUrl || existing?.mediaUrl || null,
      appleMusicId: appleMusicId || existing?.appleMusicId || null,
      updatedAt: now,
      lastAvoidedAt: now,
      lastAvoidedRoomCode: roomCode || null,
      globalAvoidRoomCount: distinctAvoidRoomCount,
      globalFeedbackState: nextFeedbackState,
      ...backingMetadata,
    };
    if (!snap.exists) {
      updates.createdAt = now;
    }
    if (roomCode && !hasRoomEvidence) {
      updates.avoidRoomCodes = admin.firestore.FieldValue.arrayUnion(roomCode);
      updates.failureCount = admin.firestore.FieldValue.increment(1);
    }
    if (distinctAvoidRoomCount >= 2) {
      updates.approvalState = currentApprovalState === "approved" ? "candidate" : currentApprovalState;
      updates.qualityScore = Math.max(0, qualityScore - 10);
      updates.globalSuppressedAt = now;
    }
    tx.set(trackRef, updates, { merge: true });
  });

  const backingFeedbackRecord = await recordCanonicalBackingFeedbackAdmin({
    ...backingFeedbackBase,
    extractYouTubeId,
  });
  return { trackId, songId, recorded: true, rating, backingCandidateId: backingFeedbackRecord?.candidateId || backingCandidateId || "" };
});

exports.getTrackDiagnostics = onCall({ cors: true }, async (request) => {
  checkRateLimit(request.rawRequest, "get_track_diagnostics", { perMinute: 60, perHour: 360 });
  enforceAppCheckIfEnabled(request, "get_track_diagnostics");
  await requireCatalogContributor(request, {
    deniedMessage: "Host or moderator access required to inspect track diagnostics.",
  });
  const data = request.data || {};
  const mediaUrl = String(data.mediaUrl || "").trim();
  const appleMusicId = String(data.appleMusicId || "").trim();
  const source = String(data.source || "").trim().toLowerCase()
    || (appleMusicId ? "apple" : extractYouTubeId(mediaUrl) ? "youtube" : "");
  const canonicalMatch = await resolveCanonicalTrackIdentityInternal({
    trackId: data.trackId || "",
    songId: data.songId || "",
    title: data.title || "",
    artist: data.artist || "Unknown",
    source,
    mediaUrl,
    appleMusicId,
  });
  const trackId = String(canonicalMatch?.trackId || data.trackId || "").trim();
  if (!trackId) {
    return {
      found: false,
      trackId: "",
      songId: String(canonicalMatch?.songId || data.songId || "").trim(),
      diagnostics: null,
    };
  }

  const trackSnap = await admin.firestore().collection("tracks").doc(trackId).get();
  if (!trackSnap.exists) {
    return {
      found: false,
      trackId,
      songId: String(canonicalMatch?.songId || data.songId || "").trim(),
      diagnostics: null,
    };
  }
  const track = trackSnap.data() || {};
  return {
    found: true,
    trackId,
    songId: String(track.songId || canonicalMatch?.songId || data.songId || "").trim(),
    diagnostics: {
      source: String(track.source || source || "").trim().toLowerCase() || null,
      mediaUrl: String(track.mediaUrl || mediaUrl || "").trim(),
      appleMusicId: String(track.appleMusicId || appleMusicId || "").trim(),
      approvalState: normalizeTrackApprovalState(track.approvalState),
      qualityScore: Math.max(0, Number(track.qualityScore || 0)),
      successCount: Math.max(0, Number(track.successCount || 0)),
      usageCount: Math.max(0, Number(track.usageCount || 0)),
      failureCount: Math.max(0, Number(track.failureCount || 0)),
      globalAvoidRoomCount: Math.max(0, Number(track.globalAvoidRoomCount || 0)),
      globalFeedbackState: normalizeTrackFeedbackState(track.globalFeedbackState) || "healthy",
      lastSuccessfulRoomCode: String(track.lastSuccessfulRoomCode || "").trim() || null,
      lastAvoidedRoomCode: String(track.lastAvoidedRoomCode || "").trim() || null,
      updatedAt: track.updatedAt || null,
      lastSuccessfulAt: track.lastSuccessfulAt || null,
      lastAvoidedAt: track.lastAvoidedAt || null,
    },
  };
});

exports.resolveCanonicalTrackIdentity = onCall({ cors: true }, async (request) => {
  checkRateLimit(request.rawRequest, "resolve_canonical_track_identity", { perMinute: 90, perHour: 900 });
  requireAuth(request);
  enforceAppCheckIfEnabled(request, "resolve_canonical_track_identity");
  const data = request.data || {};
  const safeTitle = String(data.title || "").trim();
  const safeMediaUrl = String(data.mediaUrl || "").trim();
  const safeAppleMusicId = String(data.appleMusicId || "").trim();
  const safeSongId = String(data.songId || "").trim();
  if (!safeTitle && !safeMediaUrl && !safeAppleMusicId && !safeSongId) {
    throw new HttpsError("invalid-argument", "title, mediaUrl, appleMusicId, or songId is required.");
  }

  const resolved = await resolveCanonicalTrackIdentityInternal({
    songId: safeSongId,
    title: safeTitle,
    artist: String(data.artist || "").trim() || "Unknown",
    source: String(data.source || "").trim(),
    mediaUrl: safeMediaUrl,
    appleMusicId: safeAppleMusicId,
  });

  return {
    found: !!resolved?.found,
    songId: String(resolved?.songId || "").trim(),
    trackId: String(resolved?.trackId || "").trim() || null,
    title: String(resolved?.title || safeTitle || "").trim(),
    artist: String(resolved?.artist || data.artist || "Unknown").trim() || "Unknown",
    artworkUrl: String(resolved?.artworkUrl || "").trim(),
    matchedBy: String(resolved?.matchedBy || "").trim() || "fallback",
  };
});

exports.resolveCanonicalTrackIdentityBatch = onCall({ cors: true }, async (request) => {
  checkRateLimit(request.rawRequest, "resolve_canonical_track_identity_batch", { perMinute: 60, perHour: 600 });
  requireAuth(request);
  enforceAppCheckIfEnabled(request, "resolve_canonical_track_identity_batch");
  const items = Array.isArray(request.data?.items) ? request.data.items : [];
  if (!items.length) {
    throw new HttpsError("invalid-argument", "items is required.");
  }
  if (items.length > 100) {
    throw new HttpsError("invalid-argument", "items max is 100.");
  }

  const results = [];
  for (let index = 0; index < items.length; index += 1) {
    const item = items[index] || {};
    const resolved = await resolveCanonicalTrackIdentityInternal({
      songId: String(item.songId || "").trim(),
      title: String(item.title || "").trim(),
      artist: String(item.artist || "").trim() || "Unknown",
      source: String(item.source || "").trim(),
      mediaUrl: String(item.mediaUrl || "").trim(),
      appleMusicId: String(item.appleMusicId || "").trim(),
    });
    results.push({
      index,
      found: !!resolved?.found,
      songId: String(resolved?.songId || "").trim(),
      trackId: String(resolved?.trackId || "").trim() || null,
      title: String(resolved?.title || item.title || "").trim(),
      artist: String(resolved?.artist || item.artist || "Unknown").trim() || "Unknown",
      artworkUrl: String(resolved?.artworkUrl || "").trim(),
      matchedBy: String(resolved?.matchedBy || "").trim() || "fallback",
    });
  }

  return { items: results };
});

const awardAccountFameForPerformance = async ({ performanceRef, roomCode = '' } = {}) => {
  const db = admin.firestore();
  return db.runTransaction(async (tx) => {
    const performanceSnap = await tx.get(performanceRef);
    if (!performanceSnap.exists) return { awarded: 0, status: "performance_missing" };
    const performance = performanceSnap.data() || {};
    if (Number(performance.fameAwardVersion || 0) >= 1) {
      return {
        awarded: Math.max(0, Number(performance.fameAwarded || 0) || 0),
        totalFamePoints: Math.max(0, Number(performance.fameTotalAfter || 0) || 0),
        fameLevel: Math.max(0, Number(performance.fameLevelAfter || 0) || 0),
        status: String(performance.fameAwardStatus || "awarded"),
        duplicate: true,
      };
    }
    const singerUid = normalizeUidToken(performance.singerUid || "");
    if (!singerUid) {
      tx.set(performanceRef, { fameAwardVersion: 1, fameAwarded: 0, fameAwardStatus: "account_required" }, { merge: true });
      return { awarded: 0, status: "account_required" };
    }
    const userRef = db.collection("users").doc(singerUid);
    const roomUserRef = getRootRef().collection("room_users").doc(`${roomCode}_${singerUid}`);
    const [userSnap, roomUserSnap] = await Promise.all([tx.get(userRef), tx.get(roomUserRef)]);
    const userData = userSnap.exists ? (userSnap.data() || {}) : {};
    const roomUserData = roomUserSnap.exists ? (roomUserSnap.data() || {}) : {};
    const accountEligible = userSnap.exists
      && roomUserSnap.exists
      && userData.leaderboardAccountEligible === true
      && roomUserData.leaderboardAccountEligible === true;
    if (!accountEligible) {
      tx.set(performanceRef, { fameAwardVersion: 1, fameAwarded: 0, fameAwardStatus: "account_required" }, { merge: true });
      return { awarded: 0, status: "account_required" };
    }
    const breakdown = calculatePerformanceFame({
      hypeScore: performance.hypeScore,
      peakDecibel: performance.peakDecibel,
      hostMultiplier: 1,
    });
    const previousTotal = Math.max(0, Number(userData.totalFamePoints || 0) || 0);
    const nextTotal = previousTotal + breakdown.totalFameAwarded;
    const fameLevel = getFameLevel(nextTotal);
    const serverNow = admin.firestore.FieldValue.serverTimestamp();
    tx.set(userRef, { totalFamePoints: nextTotal, currentLevel: fameLevel, fameLevel, fameUpdatedAt: serverNow }, { merge: true });
    tx.set(roomUserRef, { totalFamePoints: nextTotal, currentLevel: fameLevel, fameLevel, fameUpdatedAt: serverNow }, { merge: true });
    tx.set(performanceRef, {
      fameAwardVersion: 1,
      fameAwarded: breakdown.totalFameAwarded,
      fameAwardBreakdown: breakdown,
      fameAwardStatus: "awarded",
      fameTotalAfter: nextTotal,
      fameLevelAfter: fameLevel,
      fameAwardedAt: serverNow,
    }, { merge: true });
    return { awarded: breakdown.totalFameAwarded, totalFamePoints: nextTotal, fameLevel, status: "awarded", duplicate: false };
  });
};

exports.logPerformance = onCall({ cors: true }, async (request) => {
  checkRateLimit(request.rawRequest, "log_performance", { perMinute: 24, perHour: 240 });
  enforceAppCheckIfEnabled(request, "log_performance");
  const callerUid = requireAuth(request);
  await requireHostWorkspaceAccess(request, {
    deniedMessage: "Only approved BeauRocks hosts can record qualifying performances.",
  });
  const submittedData = request.data || {};
  const roomCode = normalizeRoomCode(submittedData.roomCode || "");
  if (!roomCode) {
    throw new HttpsError("invalid-argument", "roomCode is required.");
  }
  const rootRef = getRootRef();
  const { roomData } = await ensureRoomHostAccess({
    rootRef,
    roomCode,
    callerUid,
    deniedMessage: "Only the approved host for this room can record performances.",
  });
  const lastPerformance = roomData?.lastPerformance && typeof roomData.lastPerformance === "object"
    ? roomData.lastPerformance
    : null;
  if (!lastPerformance) {
    throw new HttpsError("failed-precondition", "Finish the performance recap before recording its score.");
  }
  const requestedPerformanceId = String(submittedData.performanceId || submittedData.id || "").trim();
  const authoritativePerformanceId = String(lastPerformance.id || lastPerformance.performanceId || "").trim();
  if (requestedPerformanceId && authoritativePerformanceId && requestedPerformanceId !== authoritativePerformanceId) {
    throw new HttpsError("failed-precondition", "The requested performance is not the room's latest completed performance.");
  }
  const performanceId = authoritativePerformanceId || requestedPerformanceId;
  if (!performanceId) {
    throw new HttpsError("failed-precondition", "A completed performance ID is required.");
  }
  const performanceDocId = crypto
    .createHash("sha256")
    .update(`${roomCode}:${performanceId}`)
    .digest("hex")
    .slice(0, 48);
  const performanceRef = admin.firestore().collection("performances").doc(performanceDocId);
  const existingPerformanceSnap = await performanceRef.get();
  if (
    existingPerformanceSnap.exists
    && Number(existingPerformanceSnap.get("projectionVersion") || 0) >= 1
  ) {
    const existingPerformance = existingPerformanceSnap.data() || {};
    const fameAward = await awardAccountFameForPerformance({ performanceRef, roomCode });
    return {
      songId: existingPerformance.songId || existingPerformance.canonicalSongId || null,
      canonicalSongId: existingPerformance.canonicalSongId || existingPerformance.songId || null,
      backingCandidateId: existingPerformance.backingCandidateId || null,
      trackId: existingPerformance.trackId || null,
      totalScore: Math.max(0, Number(existingPerformance.totalScore ?? existingPerformance.score ?? 0) || 0),
      applauseScore: Math.max(0, Number(existingPerformance.applauseScore || 0) || 0),
      hypeScore: Math.max(0, Number(existingPerformance.hypeScore || 0) || 0),
      hostBonus: Math.max(0, Number(existingPerformance.hostBonus || 0) || 0),
      isNewAllTime: false,
      isNewWeekly: false,
      globalLeaderboardEligible: existingPerformance.globalLeaderboardEligible === true,
      leaderboardEligibility: existingPerformance.leaderboardEligibility || "room_only_guest",
      weekKey: existingPerformance.weekKey || getWeekKeyUtc(new Date()),
      duplicate: true,
      fameAward,
    };
  }
  const data = {
    ...submittedData,
    ...lastPerformance,
    roomCode,
    performanceId,
  };
  const songTitle = (data.songTitle || data.title || "").trim();
  if (!songTitle) {
    throw new HttpsError("invalid-argument", "songTitle is required.");
  }
  const artist = (data.artist || "Unknown").trim() || "Unknown";
  const albumArtUrl = data.albumArtUrl || "";
  const sourceGuess = data.trackSource
    || (data.appleMusicId ? "apple" : extractYouTubeId(data.mediaUrl || "") ? "youtube" : "custom");
  const canonicalMatch = await resolveCanonicalTrackIdentityInternal({
    songId: data.canonicalSongId || data.songId || "",
    title: songTitle,
    artist,
    source: sourceGuess,
    mediaUrl: data.mediaUrl || "",
    appleMusicId: data.appleMusicId || "",
  });
  const canonicalTitle = String(canonicalMatch?.title || songTitle).trim() || songTitle;
  const canonicalArtist = String(canonicalMatch?.artist || artist).trim() || artist;
  const songResult = await ensureSongAdmin({
    title: canonicalTitle,
    artist: canonicalArtist,
    artworkUrl: albumArtUrl,
    verifyMeta: false,
    verifiedBy: data.verifiedBy || "host",
  });
  const songId = canonicalMatch?.found
    ? (canonicalMatch.songId || songResult?.songId || buildSongKey(canonicalTitle, canonicalArtist))
    : (data.canonicalSongId || data.songId || songResult?.songId || buildSongKey(canonicalTitle, canonicalArtist));

  let trackId = canonicalMatch?.trackId || data.trackId || null;
  if (!trackId && (data.mediaUrl || data.appleMusicId)) {
    const trackResult = await ensureTrackAdmin({
      songId,
      source: sourceGuess,
      mediaUrl: data.mediaUrl || "",
      appleMusicId: data.appleMusicId || "",
      duration: data.duration ?? null,
      audioOnly: !!data.audioOnly,
      backingOnly: !!data.backingAudioOnly,
      addedBy: data.addedBy || data.hostName || "Host",
    });
    trackId = trackResult?.trackId || null;
  }

  if (trackId) {
    await admin.firestore().collection("tracks").doc(trackId).set({
      songId,
      canonicalSongId: songId,
      backingCandidateId: String(data.backingCandidateId || "").trim() || null,
      backingProvider: String(data.backingProvider || sourceGuess || "").trim().toLowerCase() || null,
      providerTrackId: String(data.providerTrackId || extractYouTubeId(data.mediaUrl || "") || data.appleMusicId || "").trim() || null,
      source: sourceGuess || null,
      mediaUrl: data.mediaUrl || null,
      appleMusicId: data.appleMusicId || null,
      label: data.label || null,
      approvalState: normalizeTrackApprovalState(data.approvalState || "candidate"),
      usageCount: admin.firestore.FieldValue.increment(1),
      successCount: admin.firestore.FieldValue.increment(1),
      lastSuccessfulRoomCode: roomCode || null,
      lastSuccessfulAt: admin.firestore.FieldValue.serverTimestamp(),
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    }, { merge: true });
  }

  if (roomCode && trackId) {
    const hostLibraryRef = getRootRef().collection("host_libraries").doc(roomCode);
    const hostLibrarySnap = await hostLibraryRef.get();
    const trustedCatalog = normalizeTrustedCatalogMap(hostLibrarySnap.data()?.trustedCatalog || {});
    const existingEntry = getTrustedSongEntry(trustedCatalog, songId) || {};
    const nextEntry = {
      ...existingEntry,
      songId,
      title: canonicalTitle,
      artist: canonicalArtist,
      roomRecentTrackId: trackId,
      roomRecentMediaUrl: data.mediaUrl || "",
      roomRecentAppleMusicId: data.appleMusicId || "",
      roomRecentSource: sourceGuess || "",
      roomRecentLabel: data.label || "Recent successful backing",
      roomRecentApprovalState: normalizeTrackApprovalState(data.approvalState || "candidate") || "candidate",
      roomRecentUsageCount: Math.max(1, Number(existingEntry.roomRecentUsageCount || 0) + 1),
      roomRecentSuccessCount: Math.max(1, Number(existingEntry.roomRecentSuccessCount || 0) + 1),
      roomRecentQualityScore: Math.max(0, Number(existingEntry.roomRecentQualityScore || 0)),
      roomRecentUpdatedAtMs: Date.now(),
      updatedAtMs: Date.now(),
    };
    await hostLibraryRef.set({
      trustedCatalog: {
        [songId]: nextEntry,
      },
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    }, { merge: true });
  }

  const applauseScore = Math.max(0, Math.round(Number(data.applauseScore || 0)));
  const hypeScore = Math.max(0, Math.round(Number(data.hypeScore || 0)));
  const hostBonus = Math.max(0, Math.round(Number(data.hostBonus || 0)));
  const totalScore = hypeScore + applauseScore + hostBonus;
  const weekKey = getWeekKeyUtc(new Date());
  const isOfficial = isSongVerified(songResult?.songData);
  const singerUid = normalizeUidToken(data.singerUid || "");
  const [roomUserSnap, accountUserSnap, directoryProfileSnap] = singerUid
    ? await Promise.all([
      rootRef.collection("room_users").doc(`${roomCode}_${singerUid}`).get(),
      admin.firestore().collection("users").doc(singerUid).get(),
      admin.firestore().collection("directory_profiles").doc(singerUid).get(),
    ])
    : [null, null, null];
  const roomUserData = roomUserSnap?.exists ? (roomUserSnap.data() || {}) : {};
  const accountUserData = accountUserSnap?.exists ? (accountUserSnap.data() || {}) : {};
  const directoryProfileData = directoryProfileSnap?.exists ? (directoryProfileSnap.data() || {}) : {};
  const singerBelongsToRoom = !!singerUid
    && roomUserSnap?.exists
    && normalizeRoomCode(roomUserData.roomCode || "") === roomCode;
  const globalLeaderboardEligible = singerBelongsToRoom
    && roomUserData.leaderboardAccountEligible === true
    && accountUserData.leaderboardAccountEligible === true;
  const singerName = String(
    accountUserData?.leaderboardProfile?.displayName
    || accountUserData.name
    || roomUserData.name
    || data.singerName
    || "Singer"
  ).trim().slice(0, 80) || "Singer";
  const chartIdentity = buildPublicChartIdentity({
    uid: singerUid,
    accountUser: accountUserData,
    directoryProfile: directoryProfileData,
    roomUser: roomUserData,
    fallbackName: singerName,
  });
  const leaderboardEligibility = globalLeaderboardEligible
    ? "qualified_member"
    : "room_only_guest";
  await performanceRef.set({
    performanceId,
    songId,
    canonicalSongId: songId,
    trackId: trackId || null,
    backingCandidateId: String(data.backingCandidateId || "").trim() || null,
    backingProvider: String(data.backingProvider || sourceGuess || "").trim().toLowerCase() || null,
    providerTrackId: String(data.providerTrackId || extractYouTubeId(data.mediaUrl || "") || data.appleMusicId || "").trim() || null,
    trackSource: sourceGuess || null,
    roomCode,
    singerName,
    singerUid: singerUid || null,
    songTitle: canonicalTitle,
    artist: canonicalArtist,
    albumArtUrl: albumArtUrl || null,
    score: totalScore,
    totalScore,
    applauseScore,
    hypeScore,
    hostBonus,
    peakDecibel: Math.max(40, Math.min(100, Number(data.peakDecibel || 65) || 65)),
    fameHostMultiplier: 1,
    isOfficial,
    globalLeaderboardEligible,
    leaderboardEligibility,
    qualificationVersion: 1,
    qualifiedHostUid: callerUid,
    weekKey,
    timestamp: admin.firestore.FieldValue.serverTimestamp(),
  }, { merge: true });

  const fameAward = await awardAccountFameForPerformance({ performanceRef, roomCode });

  const bestRef = admin.firestore().collection("song_hall_of_fame").doc(songId);
  const weeklyId = `${weekKey}__${songId}`;
  const weeklyRef = admin.firestore().collection("song_hall_of_fame_weeks").doc(weeklyId);
  let isNewAllTime = false;
  let isNewWeekly = false;
  if (globalLeaderboardEligible) {
    await admin.firestore().runTransaction(async (tx) => {
      const [bestSnap, weeklySnap] = await Promise.all([
        tx.get(bestRef),
        tx.get(weeklyRef),
      ]);
      const bestData = bestSnap.exists && bestSnap.get("globalLeaderboardEligible") === true
        ? bestSnap.data()
        : null;
      const weeklyData = weeklySnap.exists && weeklySnap.get("globalLeaderboardEligible") === true
        ? weeklySnap.data()
        : null;
      isNewAllTime = isBetterScore(totalScore, applauseScore, bestData);
      isNewWeekly = isBetterScore(totalScore, applauseScore, weeklyData);
      const commonEntry = {
        songId,
        canonicalSongId: songId,
        songTitle: canonicalTitle,
        artist: canonicalArtist,
        albumArtUrl,
        bestScore: totalScore,
        applauseScore,
        singerName: chartIdentity.displayName,
        singerUid: admin.firestore.FieldValue.delete(),
        memberKey: chartIdentity.memberKey,
        identityVisibility: chartIdentity.identityVisibility,
        profileUid: admin.firestore.FieldValue.delete(),
        avatarUrl: chartIdentity.avatarUrl,
        sourcePerformanceId: performanceId,
        resultId: performanceDocId,
        globalLeaderboardEligible: true,
        qualificationVersion: 1,
        qualifiedHostUid: callerUid,
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      };
      if (isNewAllTime) {
        tx.set(bestRef, commonEntry, { merge: true });
      }
      if (isNewWeekly) {
        tx.set(weeklyRef, { ...commonEntry, weekKey }, { merge: true });
      }
    });

    const discoverListingId = safeDirectoryString(roomData?.discover?.listingId || "", 220);
    const roomIsMarkedPublic = roomData?.publicRoom === true
      || roomData?.discover?.publicRoom === true
      || roomData?.discover?.visibility === "public";
    const roomSessionSnap = roomIsMarkedPublic && discoverListingId
      ? await admin.firestore().collection("room_sessions").doc(discoverListingId).get()
      : null;
    const roomSessionData = roomSessionSnap?.exists ? (roomSessionSnap.data() || {}) : {};
    const isApprovedPublicNight = roomSessionSnap?.exists
      && roomSessionData.status === "approved"
      && roomSessionData.visibility === "public";
    const memberRef = admin.firestore()
      .collection(PUBLIC_CHART_MEMBERS_COLLECTION)
      .doc(chartIdentity.memberKey);
    const publicSongRef = admin.firestore()
      .collection(PUBLIC_CHART_SONGS_COLLECTION)
      .doc(songId);
    const publicNightRef = isApprovedPublicNight
      ? admin.firestore().collection(PUBLIC_CHART_NIGHTS_COLLECTION).doc(discoverListingId)
      : null;
    const qualifiedNightLabel = isApprovedPublicNight
      ? safeDirectoryString(roomSessionData.title || roomSessionData.venueName || "Public BeauRocks night", 120)
      : "Approved BeauRocks night";

    await admin.firestore().runTransaction(async (tx) => {
      const reads = [
        tx.get(performanceRef),
        tx.get(memberRef),
        tx.get(publicSongRef),
      ];
      if (publicNightRef) reads.push(tx.get(publicNightRef));
      const [projectionPerformanceSnap, memberSnap, publicSongSnap, publicNightSnap = null] = await Promise.all(reads);
      if (Number(projectionPerformanceSnap.get("projectionVersion") || 0) >= 1) return;
      const memberData = memberSnap.exists ? (memberSnap.data() || {}) : {};
      const priorMemberTotal = Math.max(0, Number(memberData.totalScore || 0) || 0);
      const priorPerformanceCount = Math.max(0, Number(memberData.performanceCount || 0) || 0);
      const nextTotalScore = priorMemberTotal + totalScore;
      const nextPerformanceCount = priorPerformanceCount + 1;
      const memberBestScore = Math.max(0, Number(memberData.bestScore || 0) || 0);
      const memberBestApplause = Math.max(0, Number(memberData.bestApplauseScore || 0) || 0);
      const memberHasNewBest = totalScore > memberBestScore
        || (totalScore === memberBestScore && applauseScore > memberBestApplause);
      tx.set(memberRef, {
        schemaVersion: 1,
        memberKey: chartIdentity.memberKey,
        displayName: chartIdentity.displayName,
        identityVisibility: chartIdentity.identityVisibility,
        profileUid: admin.firestore.FieldValue.delete(),
        avatarUrl: chartIdentity.avatarUrl,
        totalScore: nextTotalScore,
        rankScore: nextTotalScore,
        performanceCount: nextPerformanceCount,
        averageScore: Math.round(nextTotalScore / nextPerformanceCount),
        bestScore: memberHasNewBest ? totalScore : memberBestScore,
        bestApplauseScore: memberHasNewBest ? applauseScore : memberBestApplause,
        latestSongId: songId,
        latestSongTitle: canonicalTitle,
        latestArtist: canonicalArtist,
        latestResultId: performanceDocId,
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      }, { merge: true });

      const publicSongData = publicSongSnap.exists ? (publicSongSnap.data() || {}) : null;
      const legacyChampion = publicSongData?.resultId
        ? buildPublicSongLeaderEntry({
          resultId: publicSongData.resultId,
          memberKey: publicSongData.memberKey,
          displayName: publicSongData.displayName,
          identityVisibility: publicSongData.identityVisibility,
          avatarUrl: publicSongData.avatarUrl,
          score: publicSongData.bestScore,
          applauseScore: publicSongData.applauseScore,
          qualifiedNightLabel: publicSongData.qualifiedNightLabel,
          performedAtMs: publicSongData.performedAtMs,
        })
        : null;
      const candidateLeader = buildPublicSongLeaderEntry({
        resultId: performanceDocId,
        memberKey: chartIdentity.memberKey,
        displayName: chartIdentity.displayName,
        identityVisibility: chartIdentity.identityVisibility,
        avatarUrl: chartIdentity.avatarUrl,
        score: totalScore,
        applauseScore,
        qualifiedNightLabel,
        performedAtMs: Date.now(),
      });
      const leaders = mergePublicSongLeaders(
        [...(Array.isArray(publicSongData?.leaders) ? publicSongData.leaders : []), legacyChampion],
        candidateLeader
      );
      const songHasNewBest = isBetterScore(totalScore, applauseScore, publicSongData);
      tx.set(publicSongRef, {
        schemaVersion: 2,
        songId,
        canonicalSongId: songId,
        songTitle: songHasNewBest ? canonicalTitle : (publicSongData?.songTitle || canonicalTitle),
        artist: songHasNewBest ? canonicalArtist : (publicSongData?.artist || canonicalArtist),
        albumArtUrl: songHasNewBest ? (albumArtUrl || null) : (publicSongData?.albumArtUrl || null),
        bestScore: songHasNewBest ? totalScore : Math.max(0, Number(publicSongData?.bestScore || 0) || 0),
        applauseScore: songHasNewBest ? applauseScore : Math.max(0, Number(publicSongData?.applauseScore || 0) || 0),
        memberKey: songHasNewBest ? chartIdentity.memberKey : (publicSongData?.memberKey || null),
        displayName: songHasNewBest ? chartIdentity.displayName : (publicSongData?.displayName || "BeauRocks Singer"),
        identityVisibility: songHasNewBest ? chartIdentity.identityVisibility : (publicSongData?.identityVisibility || "anonymous"),
        profileUid: admin.firestore.FieldValue.delete(),
        avatarUrl: songHasNewBest ? chartIdentity.avatarUrl : (publicSongData?.avatarUrl || null),
        resultId: songHasNewBest ? performanceDocId : (publicSongData?.resultId || performanceDocId),
        qualifiedNightLabel: songHasNewBest ? qualifiedNightLabel : (publicSongData?.qualifiedNightLabel || "Approved BeauRocks night"),
        performedAtMs: songHasNewBest ? candidateLeader.performedAtMs : Math.max(0, Number(publicSongData?.performedAtMs || 0) || 0),
        leaders,
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      }, { merge: true });

      if (publicNightRef) {
        const publicNightData = publicNightSnap?.exists ? (publicNightSnap.data() || {}) : {};
        const priorNightTotal = Math.max(0, Number(publicNightData.totalScore || 0) || 0);
        const priorNightCount = Math.max(0, Number(publicNightData.performanceCount || 0) || 0);
        const nextNightTotal = priorNightTotal + totalScore;
        const nextNightCount = priorNightCount + 1;
        const nightBestScore = Math.max(0, Number(publicNightData.bestScore || 0) || 0);
        const nightBestApplause = Math.max(0, Number(publicNightData.bestApplauseScore || 0) || 0);
        const nightHasNewBest = totalScore > nightBestScore
          || (totalScore === nightBestScore && applauseScore > nightBestApplause);
        tx.set(publicNightRef, {
          schemaVersion: 1,
          listingId: discoverListingId,
          title: safeDirectoryString(roomSessionData.title || roomData.roomName || roomData.name || "BeauRocks Night", 180),
          venueId: safeDirectoryString(roomSessionData.venueId || "", 180) || null,
          venueName: safeDirectoryString(roomSessionData.venueName || "", 180) || null,
          hostName: safeDirectoryString(roomSessionData.hostName || roomData.hostName || "", 120) || null,
          city: safeDirectoryString(roomSessionData.city || "", 80) || null,
          state: safeDirectoryString(roomSessionData.state || "", 40) || null,
          startsAtMs: Math.max(0, Number(roomSessionData.startsAtMs || 0) || 0),
          totalScore: nextNightTotal,
          rankScore: nextNightTotal,
          performanceCount: nextNightCount,
          averageScore: Math.round(nextNightTotal / nextNightCount),
          bestScore: nightHasNewBest ? totalScore : nightBestScore,
          bestApplauseScore: nightHasNewBest ? applauseScore : nightBestApplause,
          topMemberKey: nightHasNewBest ? chartIdentity.memberKey : (publicNightData.topMemberKey || null),
          topSingerName: nightHasNewBest ? chartIdentity.displayName : (publicNightData.topSingerName || null),
          topIdentityVisibility: nightHasNewBest ? chartIdentity.identityVisibility : (publicNightData.topIdentityVisibility || null),
          topProfileUid: admin.firestore.FieldValue.delete(),
          topAvatarUrl: nightHasNewBest ? chartIdentity.avatarUrl : (publicNightData.topAvatarUrl || null),
          topResultId: nightHasNewBest ? performanceDocId : (publicNightData.topResultId || null),
          updatedAt: admin.firestore.FieldValue.serverTimestamp(),
        }, { merge: true });
      }
      tx.set(performanceRef, {
        projectionVersion: 1,
        chartEra: "launch_v1",
        publicChartStatus: "active",
        publicNightListingId: publicNightRef ? discoverListingId : null,
        projectedAt: admin.firestore.FieldValue.serverTimestamp(),
      }, { merge: true });
    });
  }

  if (!globalLeaderboardEligible) {
    await performanceRef.set({
      projectionVersion: 1,
      chartEra: "launch_v1",
      publicChartStatus: "room_only",
      publicNightListingId: null,
      projectedAt: admin.firestore.FieldValue.serverTimestamp(),
    }, { merge: true });
  }

  return {
    songId,
    canonicalSongId: songId,
    backingCandidateId: String(data.backingCandidateId || "").trim() || null,
    trackId,
    totalScore,
    applauseScore,
    hypeScore,
    hostBonus,
    isNewAllTime,
    isNewWeekly,
    globalLeaderboardEligible,
    leaderboardEligibility,
    weekKey,
    duplicate: false,
    fameAward,
  };
});

const loadPublicChartIdentityForPerformance = async ({ tx, db, rootRef, performance = {} }) => {
  const singerUid = normalizeUidToken(performance.singerUid || "");
  if (!singerUid) {
    return {
      memberKey: "",
      displayName: "BeauRocks Singer",
      identityVisibility: "anonymous",
      avatarUrl: null,
    };
  }
  const roomCode = normalizeRoomCode(performance.roomCode || "");
  const [accountSnap, directoryProfileSnap, roomUserSnap] = await Promise.all([
    tx.get(db.collection("users").doc(singerUid)),
    tx.get(db.collection("directory_profiles").doc(singerUid)),
    roomCode
      ? tx.get(rootRef.collection("room_users").doc(`${roomCode}_${singerUid}`))
      : Promise.resolve(null),
  ]);
  if (!accountSnap.exists) {
    return {
      memberKey: buildChartMemberKey(singerUid),
      displayName: "BeauRocks Singer",
      identityVisibility: "anonymous",
      avatarUrl: null,
    };
  }
  return buildPublicChartIdentity({
    uid: singerUid,
    accountUser: accountSnap.data() || {},
    directoryProfile: directoryProfileSnap.exists ? (directoryProfileSnap.data() || {}) : {},
    roomUser: roomUserSnap?.exists ? (roomUserSnap.data() || {}) : {},
    fallbackName: "BeauRocks Singer",
  });
};

exports.moderatePublicChartResult = onCall({ cors: true, timeoutSeconds: 120 }, async (request) => {
  checkRateLimit(request.rawRequest, "moderate_public_chart_result", { perMinute: 12, perHour: 80 });
  enforceAppCheckIfEnabled(request, "moderate_public_chart_result");
  const callerUid = requireAuth(request, "Sign in required.");
  const requesterAccess = await getDirectoryModeratorAccess(callerUid);
  if (!requesterAccess.isAdmin) {
    throw new HttpsError("permission-denied", "Directory admin role required.");
  }
  const resultId = String(request.data?.resultId || "").trim();
  const reason = normalizeDirectoryTextBlock(request.data?.reason || "support_review", 500)
    || "support_review";
  const apply = request.data?.apply === true;
  if (!/^[a-f0-9]{48}$/.test(resultId)) {
    throw new HttpsError("invalid-argument", "A valid public result ID is required.");
  }

  const db = admin.firestore();
  const rootRef = getRootRef();
  const performanceRef = db.collection("performances").doc(resultId);
  const initialSnap = await performanceRef.get();
  if (!initialSnap.exists) {
    throw new HttpsError("not-found", "Public chart result not found.");
  }
  const initialData = initialSnap.data() || {};
  if (!isEligiblePublicChartPerformance(initialData)
    && String(initialData.publicChartStatus || "").trim().toLowerCase() !== "removed") {
    throw new HttpsError("failed-precondition", "This result is not an eligible public chart result.");
  }
  const singerUid = normalizeUidToken(initialData.singerUid || "");
  const canonicalSongId = String(initialData.canonicalSongId || initialData.songId || "").trim();
  const listingId = safeDirectoryString(initialData.publicNightListingId || "", 220);
  const weekKey = String(initialData.weekKey || "").trim();
  const preview = {
    ok: true,
    dryRun: !apply,
    resultId,
    affectedMemberKey: buildChartMemberKey(singerUid),
    affectedSongId: canonicalSongId,
    affectedRoomListingId: listingId || null,
    affectedWeekKey: weekKey || null,
    alreadyRemoved: String(initialData.publicChartStatus || "").trim().toLowerCase() === "removed",
  };
  if (!apply) return preview;

  const moderationEventRef = db.collection(PUBLIC_CHART_MODERATION_COLLECTION).doc();
  const repairResult = await db.runTransaction(async (tx) => {
    const currentSnap = await tx.get(performanceRef);
    if (!currentSnap.exists) {
      throw new HttpsError("not-found", "Public chart result not found.");
    }
    const memberQuery = db.collection("performances")
      .where("singerUid", "==", singerUid)
      .limit(PUBLIC_CHART_REPAIR_QUERY_LIMIT);
    const songQuery = db.collection("performances")
      .where("canonicalSongId", "==", canonicalSongId)
      .limit(PUBLIC_CHART_REPAIR_QUERY_LIMIT);
    const nightQuery = listingId
      ? db.collection("performances")
        .where("publicNightListingId", "==", listingId)
        .limit(PUBLIC_CHART_REPAIR_QUERY_LIMIT)
      : null;
    const reads = [tx.get(memberQuery), tx.get(songQuery)];
    if (nightQuery) reads.push(tx.get(nightQuery));
    if (listingId) reads.push(tx.get(db.collection("room_sessions").doc(listingId)));
    const [memberSnap, songSnap, nightSnap = null, roomSessionSnap = null] = await Promise.all(reads);
    if (memberSnap.size >= PUBLIC_CHART_REPAIR_QUERY_LIMIT
      || songSnap.size >= PUBLIC_CHART_REPAIR_QUERY_LIMIT
      || (nightSnap && nightSnap.size >= PUBLIC_CHART_REPAIR_QUERY_LIMIT)) {
      throw new HttpsError(
        "resource-exhausted",
        "Chart repair scope exceeds the safe transaction limit. Use the offline repair runbook."
      );
    }
    const remainsEligible = (docSnap) => docSnap.id !== resultId
      && isEligiblePublicChartPerformance(docSnap.data() || {});
    const memberDocs = memberSnap.docs.filter(remainsEligible);
    const songDocs = songSnap.docs.filter(remainsEligible);
    const nightDocs = nightSnap ? nightSnap.docs.filter(remainsEligible) : [];
    const latestMemberDoc = selectLatestPublicChartPerformance(memberDocs);
    const topSongDocs = selectTopPublicChartPerformances(songDocs);
    const bestSongDoc = topSongDocs[0] || null;
    const bestNightDoc = selectBestPublicChartPerformance(nightDocs);
    const weekDocs = weekKey
      ? songDocs.filter((docSnap) => String(docSnap.get("weekKey") || "").trim() === weekKey)
      : [];
    const topWeekDocs = selectTopPublicChartPerformances(weekDocs);
    const bestWeekDoc = topWeekDocs[0] || null;
    const identityDocs = [latestMemberDoc, ...topSongDocs, bestNightDoc, ...topWeekDocs].filter(Boolean);
    const identityByUid = new Map();
    for (const docSnap of identityDocs) {
      const uid = normalizeUidToken(docSnap.get("singerUid") || "");
      if (!uid || identityByUid.has(uid)) continue;
      identityByUid.set(uid, await loadPublicChartIdentityForPerformance({
        tx,
        db,
        rootRef,
        performance: docSnap.data() || {},
      }));
    }
    const identityFor = (docSnap) => identityByUid.get(normalizeUidToken(docSnap?.get("singerUid") || "")) || {
      memberKey: "",
      displayName: "BeauRocks Singer",
      identityVisibility: "anonymous",
      avatarUrl: null,
    };

    const memberRef = db.collection(PUBLIC_CHART_MEMBERS_COLLECTION).doc(buildChartMemberKey(singerUid));
    const publicSongRef = db.collection(PUBLIC_CHART_SONGS_COLLECTION).doc(canonicalSongId);
    const hallRef = db.collection("song_hall_of_fame").doc(canonicalSongId);
    const weeklyRef = weekKey
      ? db.collection("song_hall_of_fame_weeks").doc(`${weekKey}__${canonicalSongId}`)
      : null;
    const publicNightRef = listingId
      ? db.collection(PUBLIC_CHART_NIGHTS_COLLECTION).doc(listingId)
      : null;

    tx.set(performanceRef, {
      publicChartStatus: "removed",
      projectionVersion: 2,
      moderationReason: reason,
      moderatedAt: admin.firestore.FieldValue.serverTimestamp(),
    }, { merge: true });
    tx.set(moderationEventRef, {
      resultId,
      action: "remove",
      reason,
      performedByUid: callerUid,
      createdAt: admin.firestore.FieldValue.serverTimestamp(),
    });

    if (!latestMemberDoc) {
      tx.delete(memberRef);
    } else {
      const latestData = latestMemberDoc.data() || {};
      const bestMemberDoc = selectBestPublicChartPerformance(memberDocs);
      const bestMemberData = bestMemberDoc?.data() || {};
      const memberIdentity = identityFor(latestMemberDoc);
      const totalScore = memberDocs.reduce(
        (sum, docSnap) => sum + getPublicChartPerformanceScore(docSnap.data() || {}),
        0
      );
      tx.set(memberRef, {
        schemaVersion: 1,
        memberKey: buildChartMemberKey(singerUid),
        displayName: memberIdentity.displayName,
        identityVisibility: memberIdentity.identityVisibility,
        profileUid: admin.firestore.FieldValue.delete(),
        avatarUrl: memberIdentity.avatarUrl,
        totalScore,
        rankScore: totalScore,
        performanceCount: memberDocs.length,
        averageScore: Math.round(totalScore / memberDocs.length),
        bestScore: getPublicChartPerformanceScore(bestMemberData),
        bestApplauseScore: getPublicChartPerformanceApplause(bestMemberData),
        latestSongId: String(latestData.canonicalSongId || latestData.songId || "").trim(),
        latestSongTitle: String(latestData.songTitle || "").trim(),
        latestArtist: String(latestData.artist || "Unknown").trim() || "Unknown",
        latestResultId: latestMemberDoc.id,
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      }, { merge: false });
    }

    const writeBestSong = (ref, docSnap, extra = {}, leaderDocs = []) => {
      if (!docSnap) {
        tx.delete(ref);
        return;
      }
      const data = docSnap.data() || {};
      const identity = identityFor(docSnap);
      const leaders = mergePublicSongLeaders(leaderDocs.map((leaderDoc) => {
        const leaderData = leaderDoc.data() || {};
        const leaderIdentity = identityFor(leaderDoc);
        return {
          resultId: leaderDoc.id,
          memberKey: leaderIdentity.memberKey,
          displayName: leaderIdentity.displayName,
          identityVisibility: leaderIdentity.identityVisibility,
          avatarUrl: leaderIdentity.avatarUrl,
          score: getPublicChartPerformanceScore(leaderData),
          applauseScore: getPublicChartPerformanceApplause(leaderData),
          qualifiedNightLabel: "Approved BeauRocks night",
          performedAtMs: getPublicChartPerformanceTimestampMs(leaderData),
        };
      }), null);
      tx.set(ref, {
        schemaVersion: 2,
        songId: canonicalSongId,
        canonicalSongId,
        songTitle: String(data.songTitle || "Untitled song").trim() || "Untitled song",
        artist: String(data.artist || "Unknown").trim() || "Unknown",
        albumArtUrl: String(data.albumArtUrl || "").trim() || null,
        bestScore: getPublicChartPerformanceScore(data),
        applauseScore: getPublicChartPerformanceApplause(data),
        memberKey: identity.memberKey,
        displayName: identity.displayName,
        singerName: identity.displayName,
        singerUid: admin.firestore.FieldValue.delete(),
        identityVisibility: identity.identityVisibility,
        profileUid: admin.firestore.FieldValue.delete(),
        avatarUrl: identity.avatarUrl,
        resultId: docSnap.id,
        sourcePerformanceId: String(data.performanceId || "").trim() || null,
        globalLeaderboardEligible: true,
        qualificationVersion: 1,
        qualifiedHostUid: data.qualifiedHostUid || null,
        qualifiedNightLabel: leaders[0]?.qualifiedNightLabel || "Approved BeauRocks night",
        performedAtMs: leaders[0]?.performedAtMs || getPublicChartPerformanceTimestampMs(data),
        leaders,
        ...extra,
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      }, { merge: false });
    };
    writeBestSong(publicSongRef, bestSongDoc, {}, topSongDocs);
    writeBestSong(hallRef, bestSongDoc, {}, topSongDocs);
    if (weeklyRef) writeBestSong(weeklyRef, bestWeekDoc, { weekKey }, topWeekDocs);

    const roomSessionData = roomSessionSnap?.exists ? (roomSessionSnap.data() || {}) : {};
    const roomRemainsPublic = roomSessionSnap?.exists
      && roomSessionData.status === "approved"
      && roomSessionData.visibility === "public";
    if (publicNightRef) {
      if (!roomRemainsPublic || !nightDocs.length || !bestNightDoc) {
        tx.delete(publicNightRef);
      } else {
        const bestNightData = bestNightDoc.data() || {};
        const nightIdentity = identityFor(bestNightDoc);
        const totalScore = nightDocs.reduce(
          (sum, docSnap) => sum + getPublicChartPerformanceScore(docSnap.data() || {}),
          0
        );
        tx.set(publicNightRef, {
          schemaVersion: 1,
          listingId,
          title: safeDirectoryString(roomSessionData.title || "BeauRocks Room", 180),
          venueId: safeDirectoryString(roomSessionData.venueId || "", 180) || null,
          venueName: safeDirectoryString(roomSessionData.venueName || "", 180) || null,
          hostName: safeDirectoryString(roomSessionData.hostName || "", 120) || null,
          city: safeDirectoryString(roomSessionData.city || "", 80) || null,
          state: safeDirectoryString(roomSessionData.state || "", 40) || null,
          startsAtMs: Math.max(0, Number(roomSessionData.startsAtMs || 0) || 0),
          totalScore,
          rankScore: totalScore,
          performanceCount: nightDocs.length,
          averageScore: Math.round(totalScore / nightDocs.length),
          bestScore: getPublicChartPerformanceScore(bestNightData),
          bestApplauseScore: getPublicChartPerformanceApplause(bestNightData),
          topMemberKey: nightIdentity.memberKey,
          topSingerName: nightIdentity.displayName,
          topIdentityVisibility: nightIdentity.identityVisibility,
          topProfileUid: admin.firestore.FieldValue.delete(),
          topAvatarUrl: nightIdentity.avatarUrl,
          topResultId: bestNightDoc.id,
          updatedAt: admin.firestore.FieldValue.serverTimestamp(),
        }, { merge: false });
      }
    }
    return {
      remainingMemberPerformances: memberDocs.length,
      remainingSongPerformances: songDocs.length,
      remainingRoomPerformances: nightDocs.length,
    };
  });

  return {
    ...preview,
    dryRun: false,
    applied: true,
    ...repairResult,
  };
});

exports.previewPublicChartLaunch = onCall({ cors: true, timeoutSeconds: 60 }, async (request) => {
  checkRateLimit(request.rawRequest, "preview_public_chart_launch", { perMinute: 12, perHour: 80 });
  enforceAppCheckIfEnabled(request, "preview_public_chart_launch");
  const callerUid = requireAuth(request, "Sign in required.");
  const requesterAccess = await getDirectoryModeratorAccess(callerUid);
  if (!requesterAccess.isAdmin) {
    throw new HttpsError("permission-denied", "Directory admin role required.");
  }
  const rootRef = getRootRef();
  const roomDocs = [];
  let cursor = null;
  let truncated = false;
  while (roomDocs.length < PUBLIC_CHART_PREFLIGHT_MAX_ROOMS) {
    let roomQuery = rootRef.collection("rooms")
      .orderBy(admin.firestore.FieldPath.documentId())
      .limit(PUBLIC_CHART_PREFLIGHT_PAGE_SIZE);
    if (cursor) roomQuery = roomQuery.startAfter(cursor);
    const pageSnap = await roomQuery.get();
    roomDocs.push(...pageSnap.docs);
    cursor = pageSnap.docs[pageSnap.docs.length - 1] || null;
    if (pageSnap.size < PUBLIC_CHART_PREFLIGHT_PAGE_SIZE) break;
    if (roomDocs.length >= PUBLIC_CHART_PREFLIGHT_MAX_ROOMS) truncated = true;
  }
  const openLifecycleRooms = roomDocs.filter((docSnap) => {
    const room = docSnap.data() || {};
    const archived = room.archived === true
      || String(room.archivedStatus || "").trim().toLowerCase() === "archived";
    const closedAtMs = valueToMillis(room.closedAt)
      || Math.max(0, Number(room.closedAtMs || room.closedAt || 0) || 0);
    return !archived && closedAtMs <= 0;
  });
  const activityCutoffMs = Date.now() - PUBLIC_CHART_PREFLIGHT_ACTIVITY_WINDOW_MS;
  const activeRooms = openLifecycleRooms.filter((docSnap) => {
    const room = docSnap.data() || {};
    const activityAtMs = Math.max(
      valueToMillis(room.updatedAt),
      Math.max(0, Number(room.updatedAtMs || 0) || 0),
      valueToMillis(room.lastPerformance?.timestamp),
      Math.max(0, Number(room.currentPerformanceSession?.lastHeartbeatAtMs || 0) || 0),
      valueToMillis(room.createdAt),
      Math.max(0, Number(room.createdAtMs || 0) || 0)
    );
    return activityAtMs >= activityCutoffMs;
  });
  const activeHostUids = new Set();
  activeRooms.forEach((docSnap) => {
    const room = docSnap.data() || {};
    [room.hostUid, ...(Array.isArray(room.hostUids) ? room.hostUids : [])]
      .map((uid) => normalizeUidToken(uid || ""))
      .filter(Boolean)
      .forEach((uid) => activeHostUids.add(uid));
  });
  const accessChecks = await Promise.all(Array.from(activeHostUids).map(async (uid) => {
    try {
      const userRecord = await admin.auth().getUser(uid);
      const email = normalizeEmailToken(userRecord.email || "");
      const superAdmin = SUPER_ADMIN_UIDS.has(uid)
        || (userRecord.emailVerified === true && SUPER_ADMIN_EMAILS.has(email));
      const access = await resolveReadOnlyHostWorkspaceAccess({ uid, email, superAdmin });
      return { uid, authUserExists: true, ...access };
    } catch (error) {
      if (String(error?.code || "").includes("user-not-found")) {
        return { uid, authUserExists: false, eligible: false };
      }
      throw error;
    }
  }));
  const unapprovedHostUids = accessChecks
    .filter((entry) => entry.authUserExists && !entry.eligible)
    .map((entry) => entry.uid)
    .sort();
  const orphanedHostUids = accessChecks
    .filter((entry) => !entry.authUserExists)
    .map((entry) => entry.uid)
    .sort();
  const publicRoomCount = openLifecycleRooms.filter((docSnap) => {
    const room = docSnap.data() || {};
    return room.publicRoom === true
      || room.discover?.publicRoom === true
      || String(room.discover?.visibility || "").trim().toLowerCase() === "public";
  }).length;
  return {
    ok: true,
    chartEra: "launch_v1",
    canLaunch: !truncated && unapprovedHostUids.length === 0,
    truncated,
    gateScope: "rooms_with_activity_in_last_30_days",
    scannedRoomCount: roomDocs.length,
    openLifecycleRoomCount: openLifecycleRooms.length,
    activeRoomCount: activeRooms.length,
    publicRoomCount,
    activeHostCount: activeHostUids.size,
    approvedActiveHostCount: accessChecks.filter((entry) => entry.eligible).length,
    unapprovedHostCount: unapprovedHostUids.length,
    unapprovedHostUids,
    orphanedHostCount: orphanedHostUids.length,
    orphanedHostUids,
  };
});

exports.reconcilePerformanceRecap = onCall({ cors: true }, async (request) => {
  const callerUid = requireAuth(request);
  const data = request.data || {};
  const roomCode = normalizeRoomCode(data.roomCode || "");
  const performanceId = String(data.performanceId || "").trim();
  if (!roomCode) {
    throw new HttpsError("invalid-argument", "roomCode is required.");
  }
  if (!performanceId) {
    throw new HttpsError("invalid-argument", "performanceId is required.");
  }

  const rootRef = getRootRef();
  await ensureRoomHostAccess({
    rootRef,
    roomCode,
    callerUid,
    deniedMessage: "Only room hosts can reconcile recap data.",
  });

  const now = Date.now();
  const fallbackEndedAtMs = clampNumber(data.endedAtMs || now, 0, 4102444800000, now);
  const fallbackStartedAtMs = clampNumber(data.startedAtMs || 0, 0, 4102444800000, 0);
  const fallbackHypeScore = Math.max(0, Math.round(Number(data.fallbackHypeScore || 0)));
  const fallbackApplauseScore = Math.max(0, Math.round(Number(data.fallbackApplauseScore || 0)));
  const fallbackHostBonus = Math.max(0, Math.round(Number(data.fallbackHostBonus || 0)));

  const songRef = rootRef.collection("karaoke_songs").doc(performanceId);
  const songSnap = await songRef.get();
  const songData = songSnap.exists ? (songSnap.data() || {}) : {};
  const songStartedAtMs = toEpochMs(songData?.performingStartedAt) || toEpochMs(songData?.startedAt) || toEpochMs(songData?.timestamp);
  const windowStartMs = fallbackStartedAtMs || songStartedAtMs || Math.max(0, fallbackEndedAtMs - (12 * 60 * 1000));
  const windowEndMs = Math.max(windowStartMs, fallbackEndedAtMs);

  let reactionDocs = [];
  let reactionSource = "performance_id";
  try {
    const snap = await rootRef.collection("reactions").where("performanceId", "==", performanceId).get();
    reactionDocs = snap.docs;
  } catch (error) {
    console.warn("reconcilePerformanceRecap: performanceId query failed", error);
  }
  if (!reactionDocs.length) {
    reactionSource = "room_window_indexed";
    try {
      reactionDocs = await fetchRoomReactionsInWindow({
        rootRef,
        roomCode,
        windowStartMs,
        windowEndMs,
      });
    } catch (error) {
      reactionSource = "room_window_fallback";
      console.warn("reconcilePerformanceRecap: indexed room window query failed", error);
      try {
        const fallbackSnap = await rootRef
          .collection("reactions")
          .where("roomCode", "==", roomCode)
          .orderBy("timestamp", "desc")
          .limit(RECAP_WINDOW_QUERY_MAX_DOCS)
          .get();
        reactionDocs = fallbackSnap.docs;
      } catch (legacyError) {
        console.warn("reconcilePerformanceRecap: ordered fallback query failed", legacyError);
        const legacySnap = await rootRef
          .collection("reactions")
          .where("roomCode", "==", roomCode)
          .limit(RECAP_WINDOW_QUERY_MAX_DOCS)
          .get();
        reactionDocs = legacySnap.docs;
      }
    }
  }

  const reactionTotals = {};
  const contributionByParticipant = new Map();
  let eventCount = 0;
  let pointWeightedHype = 0;
  let nonPointCrowdActions = 0;
  let strumTotal = 0;
  let strobeTapTotal = 0;
  let stormLayerTotal = 0;
  let lobbyPlayTotal = 0;

  reactionDocs.forEach((docSnap) => {
    const entry = docSnap.data() || {};
    const entryRoomCode = normalizeRoomCode(entry.roomCode || "");
    if (entryRoomCode && entryRoomCode !== roomCode) return;

    const entryPerformanceId = String(entry.performanceId || entry.songId || "").trim();
    const timestampMs = toEpochMs(entry.timestamp);
    const inWindow = timestampMs > 0 && timestampMs >= (windowStartMs - RECAP_WINDOW_LEAD_MS) && timestampMs <= (windowEndMs + RECAP_WINDOW_TAIL_MS);
    const hasExplicitPerformance = !!entryPerformanceId;
    const matchesPerformance = entryPerformanceId === performanceId;
    if (!matchesPerformance && hasExplicitPerformance) return;
    if (!matchesPerformance && !inWindow) return;

    const type = normalizeReactionType(entry.type);
    if (!type) return;
    const count = Math.max(1, Math.min(600, Math.round(Number(entry.count || 1))));
    const multiplier = Math.max(1, Math.min(8, Number(entry.multiplier || 1)));
    const uid = String(entry.uid || "").trim();
    const participantKey = uid
      || String(entry.userName || entry.user || "guest").trim().toLowerCase()
      || `anon_${docSnap.id}`;
    if (!contributionByParticipant.has(participantKey)) {
      contributionByParticipant.set(participantKey, {
        uid: uid || null,
        userName: String(entry.userName || entry.user || "Guest").trim() || "Guest",
        avatar: String(entry.avatar || "").trim() || null,
        pointsGifted: 0,
        actions: 0,
        strums: 0,
        strobeTaps: 0,
        stormHits: 0,
      });
    }
    const participant = contributionByParticipant.get(participantKey);
    participant.actions += count;

    eventCount += 1;
    reactionTotals[type] = (reactionTotals[type] || 0) + count;
    const basePoints = Number(RECAP_REACTION_POINT_COSTS[type] || 0);
    if (basePoints > 0) {
      const weighted = Math.round(basePoints * count * multiplier);
      pointWeightedHype += weighted;
      participant.pointsGifted += weighted;
    } else {
      nonPointCrowdActions += count;
    }
    if (type === "strum") {
      strumTotal += count;
      participant.strums += count;
    } else if (type === "strobe_tap") {
      strobeTapTotal += count;
      participant.strobeTaps += count;
    } else if (type === "storm_layer") {
      stormLayerTotal += count;
      participant.stormHits += count;
    } else if (type.startsWith("lobby_play_")) {
      lobbyPlayTotal += count;
    }
  });

  const roomUsersSnap = await rootRef.collection("room_users").where("roomCode", "==", roomCode).get();
  let roomUserHype = 0;
  roomUsersSnap.docs.forEach((docSnap) => {
    const user = docSnap.data() || {};
    if (String(user.lastPerformanceId || "") !== performanceId) return;
    const uid = String(user.uid || "").trim();
    const userName = String(user.name || "Guest").trim() || "Guest";
    const key = uid || userName.toLowerCase();
    const points = Math.max(0, Math.round(Number(user.performancePointsGifted || 0)));
    roomUserHype += points;
    if (!contributionByParticipant.has(key)) {
      contributionByParticipant.set(key, {
        uid: uid || null,
        userName,
        avatar: String(user.avatar || "").trim() || null,
        pointsGifted: points,
        actions: 0,
        strums: 0,
        strobeTaps: 0,
        stormHits: 0,
      });
      return;
    }
    const current = contributionByParticipant.get(key);
    current.uid = current.uid || uid || null;
    current.userName = current.userName || userName;
    current.avatar = current.avatar || String(user.avatar || "").trim() || null;
    current.pointsGifted = Math.max(current.pointsGifted, points);
  });

  const crowdSignalScore = Math.round(
    (nonPointCrowdActions * 1.4)
    + (strumTotal * 1.8)
    + (strobeTapTotal * 1.1)
    + (stormLayerTotal * 1.5)
    + (lobbyPlayTotal * 0.75)
  );
  const resolvedHypeScore = Math.max(
    fallbackHypeScore,
    Math.round(pointWeightedHype),
    Math.round(roomUserHype),
    crowdSignalScore
  );
  const participantTotals = [...contributionByParticipant.values()]
    .sort((a, b) => (
      Number(b.pointsGifted || 0) - Number(a.pointsGifted || 0)
      || Number(b.actions || 0) - Number(a.actions || 0)
    ));
  const topFan = participantTotals[0] && (participantTotals[0].pointsGifted > 0 || participantTotals[0].actions > 0)
    ? {
      name: participantTotals[0].userName,
      avatar: participantTotals[0].avatar || null,
      pointsGifted: Number(participantTotals[0].pointsGifted || 0),
    }
    : null;

  const topStrummer = [...participantTotals].sort((a, b) => Number(b.strums || 0) - Number(a.strums || 0))[0] || null;
  const topStrobe = [...participantTotals].sort((a, b) => Number(b.strobeTaps || 0) - Number(a.strobeTaps || 0))[0] || null;
  const vibeStats = {
    guitar: strumTotal > 0
      ? {
        totalHits: strumTotal,
        top: topStrummer && topStrummer.strums > 0
          ? {
            name: topStrummer.userName,
            avatar: topStrummer.avatar || null,
            hits: Number(topStrummer.strums || 0),
          }
          : null,
      }
      : null,
    strobe: strobeTapTotal > 0
      ? {
        totalTaps: strobeTapTotal,
        top: topStrobe && topStrobe.strobeTaps > 0
          ? {
            name: topStrobe.userName,
            avatar: topStrobe.avatar || null,
            taps: Number(topStrobe.strobeTaps || 0),
          }
          : null,
      }
      : null,
    storm: stormLayerTotal > 0
      ? {
        totalHits: stormLayerTotal,
      }
      : null,
  };

  const ledgerId = buildLedgerDocId(roomCode, performanceId);
  await rootRef.collection("performance_event_ledgers").doc(ledgerId).set({
    roomCode,
    performanceId,
    songDocId: performanceId,
    songId: String(songData.songId || "").trim() || null,
    singerUid: String(songData.singerUid || data.singerUid || "").trim() || null,
    singerName: String(songData.singerName || data.singerName || "").trim() || null,
    computedByUid: callerUid,
    computedAt: admin.firestore.FieldValue.serverTimestamp(),
    version: 1,
    source: reactionSource,
    windowStartMs,
    windowEndMs,
    eventCount,
    reactionTotals,
    aggregate: {
      pointWeightedHype,
      roomUserHype,
      crowdSignalScore,
      resolvedHypeScore,
      applauseScore: fallbackApplauseScore,
      hostBonus: fallbackHostBonus,
      participantCount: participantTotals.length,
      nonPointCrowdActions,
      strumTotal,
      strobeTapTotal,
      stormLayerTotal,
      lobbyPlayTotal,
    },
    participants: participantTotals.slice(0, 18).map((entry) => ({
      uid: entry.uid || null,
      userName: entry.userName,
      avatar: entry.avatar || null,
      pointsGifted: Number(entry.pointsGifted || 0),
      actions: Number(entry.actions || 0),
      strums: Number(entry.strums || 0),
      strobeTaps: Number(entry.strobeTaps || 0),
      stormHits: Number(entry.stormHits || 0),
    })),
    topFan: topFan || null,
    vibeStats,
  }, { merge: true });

  return {
    ok: true,
    roomCode,
    performanceId,
    source: reactionSource,
    windowStartMs,
    windowEndMs,
    eventCount,
    reactionTotals,
    resolved: {
      hypeScore: resolvedHypeScore,
      applauseScore: fallbackApplauseScore,
      hostBonus: fallbackHostBonus,
    },
    topFan,
    vibeStats,
    participantCount: participantTotals.length,
  };
});

exports.youtubeQuotaStatus = onCall({ cors: true }, async (request) => {
  checkRateLimit(request.rawRequest, "youtube_quota_status", { perMinute: 120, perHour: 1200 });
  requireAuth(request);
  enforceAppCheckIfEnabled(request, "youtube_quota_status");
  const checkedAtMs = nowMs();
  const [status, dailyUsage] = await Promise.all([
    readSharedYouTubeQuotaStatus(),
    readYouTubeApiDailyUsage(checkedAtMs),
  ]);
  const policy = buildYouTubeDailyCatalogPolicy();
  return {
    ...status,
    checkedAtMs,
    dailyUsage,
    dailySearchListCallLimit: policy.dailySearchLimit,
    nightlyLiveSearchReserve: policy.liveSearchReserve,
    nightlySearchCap: policy.nightlySearchCap,
  };
});

exports.youtubeSearch = onCall({ cors: true, secrets: [YOUTUBE_API_KEY] }, async (request) => {
  checkRateLimit(request.rawRequest, "youtube_search");
  await checkDurableRateLimit(request.rawRequest, "youtube_search", DEFAULT_LIMITS);
  const { entitlements } = await requireCapability(request, "api.youtube_data", {
    allowRoomScope: true,
    roomCode: request.data?.roomCode || "",
  });
  enforceAppCheckIfEnabled(request, "youtube_search");
  const query = request.data?.query || "";
  ensureString(query, "query");
  const maxResults = clampNumber(request.data?.maxResults || 10, 1, 10, 10);
  const playableOnly = request.data?.playableOnly !== false;
  const usageSource = resolveUsageSource(request.data?.usageContext?.source, "youtube_search");
  const normalizedQuery = normalizeYouTubeSearchQuery(query);
  const cacheKey = `${normalizedQuery}|${maxResults}|${playableOnly ? "playable" : "all"}`;
  const intentKey = buildYouTubeSearchIntentKey(query);
  const intentCacheKey = intentKey && intentKey !== normalizedQuery
    ? `${intentKey}|${maxResults}|${playableOnly ? "playable" : "all"}`
    : "";
  const cachedItems = readYoutubeSearchCache(cacheKey);
  if (cachedItems !== null) {
    return { items: cachedItems, cached: true };
  }
  const persistedCachedItems = await readPersistedYoutubeSearchCache(cacheKey);
  if (persistedCachedItems !== null) {
    return { items: persistedCachedItems, cached: true };
  }
  if (intentCacheKey) {
    const intentCachedItems = readYoutubeSearchCache(intentCacheKey);
    if (intentCachedItems !== null) {
      writeYoutubeSearchCache(cacheKey, intentCachedItems);
      return { items: intentCachedItems, cached: true };
    }
    const persistedIntentCachedItems = await readPersistedYoutubeSearchCache(intentCacheKey);
    if (persistedIntentCachedItems !== null) {
      writeYoutubeSearchCache(cacheKey, persistedIntentCachedItems);
      return { items: persistedIntentCachedItems, cached: true };
    }
  }
  ensureYouTubeApiQuotaAvailable();
  const apiKey = YOUTUBE_API_KEY.value();
  if (!apiKey) {
    throw new HttpsError("failed-precondition", "YouTube API key not configured.");
  }
  const searchUsageOperationId = resolveRequestUsageOperationId(request, "search_list");
  const searchUsageReservation = await reserveOrganizationUsageOperation({
    orgId: entitlements.orgId,
    entitlements,
    operationId: searchUsageOperationId,
    meterId: "youtube_data_request",
    capabilityId: "youtube_live_search",
    units: 1,
    source: `${usageSource}_search_list`,
    ...buildUsageAttributionContext({
      request,
      roomCode: request.data?.roomCode || "",
      source: usageSource,
    }),
  });
  if (!searchUsageReservation.created) {
    throw new HttpsError("aborted", `YouTube search usage operation is already ${searchUsageReservation.state || "reserved"}.`);
  }
  try {
    await reserveYouTubeApiDailyCall({
      method: "search.list",
      source: usageSource,
    });
  } catch (error) {
    await releaseOrganizationUsageOperation({
      orgId: entitlements.orgId,
      operationId: searchUsageOperationId,
      periodKey: searchUsageReservation.periodKey,
    }).catch((releaseError) => console.warn("youtubeSearch: usage reservation release failed", releaseError));
    throw error;
  }
  const url = `https://www.googleapis.com/youtube/v3/search?key=${apiKey}&q=${encodeURIComponent(query)}&part=snippet&type=video&maxResults=${maxResults}&order=relevance`;
  let res;
  try {
    res = await fetch(url);
  } finally {
    await settleOrganizationUsageOperation({
      orgId: entitlements.orgId,
      operationId: searchUsageOperationId,
      periodKey: searchUsageReservation.periodKey,
    });
  }
  await assertYouTubeApiResponseOk(res, "YouTube search");
  const data = await res.json();
  const baseItems = (data.items || []).map((item) => ({
    id: item.id?.videoId || item.id,
    title: item.snippet?.title || "",
    channelTitle: item.snippet?.channelTitle || "",
    thumbnails: item.snippet?.thumbnails || {},
  })).filter((item) => !!item.id);
  if (!baseItems.length) {
    await primeYoutubeSearchCaches({
      exactCacheKey: cacheKey,
      intentCacheKey,
      items: [],
      persistEmpty: true,
    });
    return { items: [] };
  }

  const detailsUsageOperationId = resolveRequestUsageOperationId(request, "videos_list");
  const detailsUsageReservation = await reserveOrganizationUsageOperation({
    orgId: entitlements.orgId,
    entitlements,
    operationId: detailsUsageOperationId,
    meterId: "youtube_data_request",
    capabilityId: "youtube_live_search",
    units: 1,
    source: `${usageSource}_videos_list`,
    ...buildUsageAttributionContext({
      request,
      roomCode: request.data?.roomCode || "",
      source: usageSource,
    }),
  });
  if (!detailsUsageReservation.created) {
    throw new HttpsError("aborted", `YouTube details usage operation is already ${detailsUsageReservation.state || "reserved"}.`);
  }
  try {
    await reserveYouTubeApiDailyCall({
      method: "videos.list",
      source: `${usageSource}_playability`,
    });
  } catch (error) {
    await releaseOrganizationUsageOperation({
      orgId: entitlements.orgId,
      operationId: detailsUsageOperationId,
      periodKey: detailsUsageReservation.periodKey,
    }).catch((releaseError) => console.warn("youtubeSearch: details usage reservation release failed", releaseError));
    throw error;
  }
  const ids = baseItems.map((item) => item.id).slice(0, 50);
  const detailsUrl = `https://www.googleapis.com/youtube/v3/videos?key=${apiKey}&part=status,contentDetails,statistics&id=${ids.join(",")}`;
  let detailsRes;
  try {
    detailsRes = await fetch(detailsUrl);
  } finally {
    await settleOrganizationUsageOperation({
      orgId: entitlements.orgId,
      operationId: detailsUsageOperationId,
      periodKey: detailsUsageReservation.periodKey,
    });
  }
  await assertYouTubeApiResponseOk(detailsRes, "YouTube playability check");
  const details = await detailsRes.json();
  const statusById = new Map();
  (details.items || []).forEach((item) => {
    const id = String(item.id || "").trim();
    if (!id) return;
    const embeddable = !!item.status?.embeddable;
    const uploadStatus = String(item.status?.uploadStatus || "").toLowerCase();
    const privacyStatus = String(item.status?.privacyStatus || "").toLowerCase();
    const isUploadReady = uploadStatus === "processed" || uploadStatus === "uploaded";
    const isAllowedPrivacy = privacyStatus === "public" || privacyStatus === "unlisted";
    const playable = embeddable && isUploadReady && isAllowedPrivacy;
    const durationSec = parseIsoDuration(item.contentDetails?.duration || "");
    const viewCount = clampNumber(Number(item.statistics?.viewCount || 0), 0, Number.MAX_SAFE_INTEGER, 0);
    statusById.set(id, {
      embeddable,
      uploadStatus,
      privacyStatus,
      durationSec,
      viewCount,
      playable,
    });
  });
  const items = baseItems
    .map((item) => {
      const status = statusById.get(item.id) || {};
      return {
        ...item,
        embeddable: !!status.embeddable,
        uploadStatus: status.uploadStatus || "",
        privacyStatus: status.privacyStatus || "",
        durationSec: Number(status.durationSec || 0),
        viewCount: Number(status.viewCount || 0),
        playable: !!status.playable,
      };
    })
    .filter((item) => (playableOnly ? item.playable : true));
  await primeYoutubeSearchCaches({
    exactCacheKey: cacheKey,
    intentCacheKey,
    items,
  });
  return { items, cached: false };
});

exports.youtubePlaylist = onCall({ cors: true, secrets: [YOUTUBE_API_KEY] }, async (request) => {
  checkRateLimit(request.rawRequest, "youtube_playlist");
  await checkDurableRateLimit(request.rawRequest, "youtube_playlist", DEFAULT_LIMITS);
  const { entitlements } = await requireCapability(request, "api.youtube_data", {
    allowRoomScope: true,
    roomCode: request.data?.roomCode || "",
  });
  enforceAppCheckIfEnabled(request, "youtube_playlist");
  const playlistId = request.data?.playlistId || "";
  ensureString(playlistId, "playlistId");
  const usageSource = resolveUsageSource(request.data?.usageContext?.source, "youtube_playlist");
  ensureYouTubeApiQuotaAvailable();
  const apiKey = YOUTUBE_API_KEY.value();
  if (!apiKey) {
    throw new HttpsError("failed-precondition", "YouTube API key not configured.");
  }
  const maxTotal = clampNumber(request.data?.maxTotal || 1000, 1, 1000, 1000);
  const items = [];
  let pageToken = "";
  let pageIndex = 0;
  while (items.length < maxTotal) {
    const batchSize = Math.min(50, maxTotal - items.length);
    const usageOperationId = resolveRequestUsageOperationId(request, `playlist_items_${pageIndex}`);
    const usageReservation = await reserveOrganizationUsageOperation({
      orgId: entitlements.orgId,
      entitlements,
      operationId: usageOperationId,
      meterId: "youtube_data_request",
      capabilityId: "youtube_metadata_lookup",
      units: 1,
      source: `${usageSource}_playlist_items`,
      ...buildUsageAttributionContext({
        request,
        roomCode: request.data?.roomCode || "",
        source: usageSource,
      }),
    });
    if (!usageReservation.created) throw new HttpsError("aborted", `YouTube playlist usage operation is already ${usageReservation.state || "reserved"}.`);
    try {
      await reserveYouTubeApiDailyCall({ method: "playlistItems.list", source: usageSource });
    } catch (error) {
      await releaseOrganizationUsageOperation({ orgId: entitlements.orgId, operationId: usageOperationId, periodKey: usageReservation.periodKey });
      throw error;
    }
    const url = `https://www.googleapis.com/youtube/v3/playlistItems?key=${apiKey}&part=snippet&maxResults=${batchSize}&playlistId=${playlistId}${pageToken ? `&pageToken=${pageToken}` : ""}`;
    let res;
    try {
      res = await fetch(url);
    } finally {
      await settleOrganizationUsageOperation({ orgId: entitlements.orgId, operationId: usageOperationId, periodKey: usageReservation.periodKey });
    }
    await assertYouTubeApiResponseOk(res, "Playlist fetch");
    const data = await res.json();
    (data.items || []).forEach((item) => {
      items.push({
        id: item.snippet?.resourceId?.videoId || item.id,
        title: item.snippet?.title || "",
        channelTitle: item.snippet?.channelTitle || "",
        thumbnails: item.snippet?.thumbnails || {},
      });
    });
    pageToken = data.nextPageToken;
    pageIndex += 1;
    if (!pageToken) break;
  }
  return { items };
});

