exports.setMyVipAccountStatus = onCall({ cors: true }, async (request) => {
  checkRateLimit(request.rawRequest, "set_my_vip_account_status", { perMinute: 24, perHour: 160 });
  enforceAppCheckIfEnabled(request, "set_my_vip_account_status");
  const uid = requireAuth(request, "Sign in required.");
  const source = normalizeDirectoryToken(request.data?.source || "audience_app", 60) || "audience_app";
  const roomCode = normalizeRoomCode(request.data?.roomCode || "");
  const sourceUid = normalizeUidToken(request.data?.sourceUid || "");
  const qaBypass = !!request.data?.qaBypass;
  const vipLevel = clampNumber(request.data?.vipLevel, 1, 5, 1);
  const rewardPoints = 5000;

  if (!roomCode) {
    throw new HttpsError("invalid-argument", "roomCode is required for VIP unlock.");
  }

  let phone = "";
  let email = "";
  if (qaBypass) {
    const isSuper = await isSuperAdminUid(uid);
    if (!isSuper) {
      throw new HttpsError("permission-denied", "QA VIP bypass requires super admin.");
    }
  } else {
    const userRecord = await admin.auth().getUser(uid);
    phone = normalizeDirectoryPhone(userRecord?.phoneNumber || "");
    email = normalizeDirectoryEmail(userRecord?.email || "");
    const emailVerified = !!userRecord?.emailVerified;
    if (!phone && !(email && emailVerified)) {
      throw new HttpsError("failed-precondition", "Phone or email verification required before VIP unlock.");
    }
  }

  const db = admin.firestore();
  const rootRef = getRootRef();
  const userRef = db.collection("users").doc(uid);
  const roomRef = rootRef.collection("rooms").doc(roomCode);
  const roomUserRef = rootRef.collection("room_users").doc(`${roomCode}_${uid}`);
  const migratedUid = sourceUid && sourceUid !== uid ? sourceUid : "";
  const sourceUserRef = migratedUid ? db.collection("users").doc(migratedUid) : null;
  const sourceRoomUserRef = migratedUid
    ? rootRef.collection("room_users").doc(`${roomCode}_${migratedUid}`)
    : null;
  const grantType = "vip_account_upgrade";
  const eventId = "vip_account_upgrade";
  const grantId = buildRoomEventCreditGrantDocId({ roomCode, eventId, uid, grantType });
  const grantRef = db.collection(ROOM_EVENT_CREDIT_GRANTS_COLLECTION).doc(grantId);
  const result = await db.runTransaction(async (tx) => {
    const [roomSnap, roomUserSnap, grantSnap, sourceUserSnap, sourceRoomUserSnap] = await Promise.all([
      tx.get(roomRef),
      tx.get(roomUserRef),
      tx.get(grantRef),
      sourceUserRef ? tx.get(sourceUserRef) : Promise.resolve(null),
      sourceRoomUserRef ? tx.get(sourceRoomUserRef) : Promise.resolve(null),
    ]);
    if (!roomSnap.exists) {
      throw new HttpsError("not-found", "Room not found.");
    }

    const sourceUserData = sourceUserSnap?.exists ? (sourceUserSnap.data() || {}) : {};
    const sourceMigrationAllowed = !!migratedUid
      && normalizeUidToken(sourceUserData.mergedIntoUid || "") === uid;
    const roomUserData = roomUserSnap.exists ? (roomUserSnap.data() || {}) : {};
    const sourceRoomUserData = sourceMigrationAllowed && sourceRoomUserSnap?.exists
      ? (sourceRoomUserSnap.data() || {})
      : {};
    const existingRoomPoints = Math.max(0, Number(roomUserData.points || 0) || 0);
    const migratedRoomPoints = Math.max(0, Number(sourceRoomUserData.points || 0) || 0);
    const baseRoomPoints = Math.max(existingRoomPoints, migratedRoomPoints);
    const duplicate = grantSnap.exists;
    const pointsGranted = duplicate ? 0 : rewardPoints;
    const roomPoints = baseRoomPoints + pointsGranted;
    const serverNow = admin.firestore.FieldValue.serverTimestamp();

    tx.set(userRef, {
      uid,
      vipLevel,
      isVip: vipLevel > 0,
      ...(phone ? { phone } : {}),
      ...(!phone && email ? { email } : {}),
      ...(!duplicate ? { pointsBalance: admin.firestore.FieldValue.increment(rewardPoints) } : {}),
      vipStatusSource: source,
      vipStatusUpdatedAt: serverNow,
      updatedAt: serverNow,
    }, { merge: true });
    tx.set(roomUserRef, {
      roomCode,
      uid,
      vipLevel,
      isVip: vipLevel > 0,
      points: roomPoints,
      totalEmojis: Math.max(
        0,
        Number(roomUserData.totalEmojis || 0) || 0,
        Number(sourceRoomUserData.totalEmojis || 0) || 0,
      ),
      lastSeen: serverNow,
      updatedAt: serverNow,
    }, { merge: true });

    if (!duplicate) {
      tx.set(grantRef, {
        roomCode,
        uid,
        eventId,
        eventLabel: "Verified audience account",
        grantType,
        pointsGranted: rewardPoints,
        source,
        createdAt: serverNow,
        updatedAt: serverNow,
      });
      setShadowLedgerEntry({
        writer: tx,
        db,
        idempotencyKey: `room_event_credit_grant:${grantId}`,
        roomCode,
        uid,
        eventCredits: { enabled: false },
        type: grantType,
        amount: rewardPoints,
        source: {
          provider: "beaurocks",
          sourceId: grantId,
          sourceCollection: ROOM_EVENT_CREDIT_GRANTS_COLLECTION,
        },
        serverTimestamp: serverNow,
      });
    }
    if (sourceMigrationAllowed && sourceRoomUserRef && sourceRoomUserSnap?.exists) {
      tx.delete(sourceRoomUserRef);
    }

    return {
      duplicate,
      pointsGranted,
      roomPoints,
      sourceRoomUserMigrated: sourceMigrationAllowed && !!sourceRoomUserSnap?.exists,
    };
  });

  return {
    ok: true,
    uid,
    vipLevel,
    isVip: vipLevel > 0,
    phoneVerified: !!phone,
    emailVerified: !phone && !!email,
    mode: qaBypass ? "qa_bypass" : (phone ? "phone_verified" : "email_verified"),
    source,
    roomCode,
    rewardPoints,
    grantId,
    ...result,
  };
});

exports.claimAudienceCommunityBoost = onCall({ cors: true }, async (request) => {
  checkRateLimit(request.rawRequest, "claim_audience_community_boost", { perMinute: 12, perHour: 60 });
  await checkDurableRateLimit(request.rawRequest, "claim_audience_community_boost", { perMinute: 12, perHour: 60 });
  enforceAppCheckIfEnabled(request, "claim_audience_community_boost");
  const uid = requireAuth(request, "Create or sign in to a BeauRocks account first.");
  const roomCode = normalizeRoomCode(request.data?.roomCode || "");
  const selfAttested = request.data?.selfAttested === true;
  if (!roomCode) {
    throw new HttpsError("invalid-argument", "roomCode is required.");
  }
  if (!selfAttested) {
    throw new HttpsError("failed-precondition", "Confirm the Community Boost before claiming it.");
  }

  const userRecord = await admin.auth().getUser(uid);
  const email = normalizeDirectoryEmail(userRecord?.email || "");
  const phone = normalizeDirectoryPhone(userRecord?.phoneNumber || "");
  if (!(email && userRecord?.emailVerified) && !phone) {
    throw new HttpsError("failed-precondition", "A verified BeauRocks account is required.");
  }

  const claimId = buildAudienceCommunityBoostClaimId(uid);
  if (!claimId) {
    throw new HttpsError("invalid-argument", "A valid account is required.");
  }

  const db = admin.firestore();
  const rootRef = getRootRef();
  const roomRef = rootRef.collection("rooms").doc(roomCode);
  const roomUserRef = rootRef.collection("room_users").doc(`${roomCode}_${uid}`);
  const accountUserRef = db.collection("users").doc(uid);
  const claimRef = db.collection(AUDIENCE_GROWTH_ACTION_CLAIMS_COLLECTION).doc(claimId);
  const result = await db.runTransaction(async (tx) => {
    const [roomSnap, roomUserSnap, claimSnap] = await Promise.all([
      tx.get(roomRef),
      tx.get(roomUserRef),
      tx.get(claimRef),
    ]);
    if (!roomSnap.exists) {
      throw new HttpsError("not-found", "Room not found.");
    }
    if (!roomUserSnap.exists) {
      throw new HttpsError("failed-precondition", "Join the room before claiming the Community Boost.");
    }

    const roomUserData = roomUserSnap.data() || {};
    const currentRoomPoints = Math.max(0, Number(roomUserData.points || 0) || 0);
    if (claimSnap.exists) {
      return {
        duplicate: true,
        pointsGranted: 0,
        roomPoints: currentRoomPoints,
      };
    }

    const serverNow = admin.firestore.FieldValue.serverTimestamp();
    const nextRoomPoints = currentRoomPoints + AUDIENCE_COMMUNITY_BOOST_POINTS;
    tx.set(claimRef, {
      schemaVersion: 1,
      claimId,
      actionId: AUDIENCE_COMMUNITY_BOOST_ACTION_ID,
      uid,
      roomCode,
      networks: [...AUDIENCE_COMMUNITY_BOOST_NETWORKS],
      selfAttested: true,
      pointsGranted: AUDIENCE_COMMUNITY_BOOST_POINTS,
      status: "claimed",
      createdAt: serverNow,
      updatedAt: serverNow,
    });
    tx.set(roomUserRef, {
      roomCode,
      uid,
      points: nextRoomPoints,
      lastSeen: serverNow,
      updatedAt: serverNow,
    }, { merge: true });
    tx.set(accountUserRef, {
      uid,
      pointsBalance: admin.firestore.FieldValue.increment(AUDIENCE_COMMUNITY_BOOST_POINTS),
      communityBoostClaimed: true,
      communityBoostClaimedAt: serverNow,
      updatedAt: serverNow,
    }, { merge: true });
    setShadowLedgerEntry({
      writer: tx,
      db,
      idempotencyKey: `audience_growth_action:${claimId}`,
      roomCode,
      uid,
      eventCredits: { enabled: false },
      type: AUDIENCE_COMMUNITY_BOOST_ACTION_ID,
      amount: AUDIENCE_COMMUNITY_BOOST_POINTS,
      source: {
        provider: "beaurocks",
        sourceId: claimId,
        sourceCollection: AUDIENCE_GROWTH_ACTION_CLAIMS_COLLECTION,
      },
      serverTimestamp: serverNow,
    });

    return {
      duplicate: false,
      pointsGranted: AUDIENCE_COMMUNITY_BOOST_POINTS,
      roomPoints: nextRoomPoints,
    };
  });

  return {
    ok: true,
    actionId: AUDIENCE_COMMUNITY_BOOST_ACTION_ID,
    rewardLabel: "Community Boost",
    roomCode,
    networks: [...AUDIENCE_COMMUNITY_BOOST_NETWORKS],
    ...result,
  };
});

