    orgId: ensured.orgId,
    role: ensured.role,
    planId: entitlements.planId,
    status: entitlements.status,
    provider: entitlements.provider,
    renewalAtMs: entitlements.renewalAtMs,
    cancelAtPeriodEnd: entitlements.cancelAtPeriodEnd,
