exports.submitSelfieChallenge = onCall({ cors: true }, async (request) => {
  checkRateLimit(request.rawRequest, "submit_selfie_challenge", { perMinute: 16, perHour: 120 });
  enforceAppCheckIfEnabled(request, "submit_selfie_challenge");
  const callerUid = requireAuth(request);
  const roomCode = normalizeRoomCode(request.data?.roomCode || "");
  const promptId = normalizeSelfieChallengePromptId(request.data?.promptId || "");
  const userName = sanitizeSelfieDisplayName(request.data?.userName || "Guest");
  const avatar = sanitizeSelfieAvatar(request.data?.avatar || "");
  const url = sanitizeSelfieUrl(request.data?.url || "", "url");
  const storagePath = sanitizeOptionalStoragePath(request.data?.storagePath || "");

  if (!roomCode) {
    throw new HttpsError("invalid-argument", "roomCode is required.");
  }
  if (!promptId) {
    throw new HttpsError("invalid-argument", "promptId is required.");
  }

  const rootRef = getRootRef();
  const db = admin.firestore();
  const roomRef = rootRef.collection("rooms").doc(roomCode);
  const roomUserRef = rootRef.collection("room_users").doc(`${roomCode}_${callerUid}`);
  const submissionId = buildSelfieChallengeSubmissionId({
    roomCode,
    promptId,
    uid: callerUid,
  });
  if (!submissionId) {
    throw new HttpsError("invalid-argument", "Submission id could not be created.");
  }
  const submissionRef = rootRef.collection("selfie_submissions").doc(submissionId);
  const serverNow = admin.firestore.FieldValue.serverTimestamp();

  const result = await db.runTransaction(async (tx) => {
    const [roomSnap, roomUserSnap, submissionSnap] = await Promise.all([
      tx.get(roomRef),
      tx.get(roomUserRef),
      tx.get(submissionRef),
    ]);

    if (!roomSnap.exists) {
      throw new HttpsError("not-found", "Room code not found.");
    }
    if (!roomUserSnap.exists) {
      throw new HttpsError("permission-denied", "Join the room before submitting a selfie.");
    }

    const roomData = roomSnap.data() || {};
    const challenge = roomData.selfieChallenge || {};
    const challengePromptId = normalizeSelfieChallengePromptId(challenge.promptId || "");
    if (roomData.activeMode !== "selfie_challenge" || challengePromptId !== promptId) {
      throw new HttpsError("failed-precondition", "That selfie challenge is no longer active.");
    }
    if (String(challenge.status || "").trim().toLowerCase() !== "collecting") {
      throw new HttpsError("failed-precondition", "Selfie collection is closed.");
    }
    if (!Array.isArray(challenge.participants) || !challenge.participants.includes(callerUid)) {
      throw new HttpsError("permission-denied", "You are not part of this selfie challenge.");
    }

    if (submissionSnap.exists) {
      const existing = submissionSnap.data() || {};
      return {
        ok: true,
        duplicate: true,
        submissionId,
        approved: !!existing.approved,
        uid: callerUid,
      };
    }

    const approved = !challenge.requireApproval;
    tx.set(submissionRef, {
      roomCode,
      promptId,
      uid: callerUid,
      userName,
      avatar,
      url,
      storagePath,
      approved,
      timestamp: serverNow,
    }, { merge: true });

    return {
      ok: true,
      duplicate: false,
      submissionId,
      approved,
      uid: callerUid,
    };
  });

  await syncSelfieChallengePublicProjection({ rootRef, roomCode, promptId });
  return result;
});

exports.castSelfieChallengeVote = onCall({ cors: true }, async (request) => {
  checkRateLimit(request.rawRequest, "cast_selfie_challenge_vote", { perMinute: 20, perHour: 160 });
  enforceAppCheckIfEnabled(request, "cast_selfie_challenge_vote");
  const callerUid = requireAuth(request);
  const roomCode = normalizeRoomCode(request.data?.roomCode || "");
  const promptId = normalizeSelfieChallengePromptId(request.data?.promptId || "");
  const targetUid = normalizeUidToken(request.data?.targetUid || "");

  if (!roomCode) {
    throw new HttpsError("invalid-argument", "roomCode is required.");
  }
  if (!promptId) {
    throw new HttpsError("invalid-argument", "promptId is required.");
  }
  if (!targetUid) {
    throw new HttpsError("invalid-argument", "targetUid is required.");
  }

  const rootRef = getRootRef();
  const db = admin.firestore();
  const roomRef = rootRef.collection("rooms").doc(roomCode);
  const roomUserRef = rootRef.collection("room_users").doc(`${roomCode}_${callerUid}`);
  const voteId = buildSelfieChallengeVoteId({
    roomCode,
    promptId,
    voterUid: callerUid,
  });
  if (!voteId) {
    throw new HttpsError("invalid-argument", "Vote id could not be created.");
  }
  const voteRef = rootRef.collection("selfie_votes").doc(voteId);
  const targetSubmissionRef = rootRef.collection("selfie_submissions").doc(
    buildSelfieChallengeSubmissionId({ roomCode, promptId, uid: targetUid })
  );
  const serverNow = admin.firestore.FieldValue.serverTimestamp();

  const result = await db.runTransaction(async (tx) => {
    const [roomSnap, roomUserSnap, voteSnap, targetSubmissionSnap] = await Promise.all([
      tx.get(roomRef),
      tx.get(roomUserRef),
      tx.get(voteRef),
      tx.get(targetSubmissionRef),
    ]);

    if (!roomSnap.exists) {
      throw new HttpsError("not-found", "Room code not found.");
    }
    if (!roomUserSnap.exists) {
      throw new HttpsError("permission-denied", "Join the room before voting.");
    }

    const roomData = roomSnap.data() || {};
    const challenge = roomData.selfieChallenge || {};
    const challengePromptId = normalizeSelfieChallengePromptId(challenge.promptId || "");
    if (roomData.activeMode !== "selfie_challenge" || challengePromptId !== promptId) {
      throw new HttpsError("failed-precondition", "That selfie challenge is no longer active.");
    }
    if (String(challenge.status || "").trim().toLowerCase() !== "voting") {
      throw new HttpsError("failed-precondition", "Voting is not open.");
    }
    if (!targetSubmissionSnap.exists) {
      throw new HttpsError("not-found", "Selfie submission not found.");
    }

    const targetSubmission = targetSubmissionSnap.data() || {};
    if (normalizeRoomCode(targetSubmission.roomCode || "") !== roomCode || normalizeSelfieChallengePromptId(targetSubmission.promptId || "") !== promptId) {
      throw new HttpsError("permission-denied", "That selfie does not belong to this challenge.");
    }
    if (challenge.requireApproval && !targetSubmission.approved) {
      throw new HttpsError("failed-precondition", "That selfie is not eligible for voting yet.");
    }

    if (voteSnap.exists) {
      const existingVote = voteSnap.data() || {};
      if (normalizeUidToken(existingVote.targetUid || "") === targetUid) {
        return {
          ok: true,
          duplicate: true,
          targetUid,
          voterUid: callerUid,
        };
      }
      throw new HttpsError("already-exists", "Vote already submitted.");
    }

    tx.set(voteRef, {
      roomCode,
      promptId,
      voterUid: callerUid,
      targetUid,
      timestamp: serverNow,
    }, { merge: true });

    return {
      ok: true,
      duplicate: false,
      targetUid,
      voterUid: callerUid,
    };
  });

  await syncSelfieChallengePublicProjection({ rootRef, roomCode, promptId });
  return result;
});

exports.moderateCrowdSelfieSubmission = onCall({ cors: true }, async (request) => {
  checkRateLimit(request.rawRequest, "crowd_selfie_approval", { perMinute: 40, perHour: 400 });
  const callerUid = request.auth?.uid || "";
  if (!callerUid) {
    throw new HttpsError("unauthenticated", "Sign in required.");
  }

  const roomCode = String(request.data?.roomCode || "").trim().toUpperCase();
  ensureString(roomCode, "roomCode");
  const submissionId = String(request.data?.submissionId || "").trim();
  ensureString(submissionId, "submissionId");
  const action = String(request.data?.action || "").trim().toLowerCase();
  if (!["approve", "reject"].includes(action)) {
    throw new HttpsError("invalid-argument", "Action must be approve or reject.");
  }

  const db = admin.firestore();
  const rootRef = getRootRef();
  const submissionRef = rootRef.collection("crowd_selfie_submissions").doc(submissionId);

  await db.runTransaction(async (tx) => {
    const { roomCode: safeRoomCode } = await ensureRoomHostAccess({
      tx,
      rootRef,
      roomCode,
      callerUid,
      deniedMessage: "Only room hosts can moderate crowd selfies.",
    });
    const submissionSnap = await tx.get(submissionRef);
    if (!submissionSnap.exists) {
      throw new HttpsError("not-found", "Crowd selfie submission not found.");
    }
    const submission = submissionSnap.data() || {};
    const submissionRoomCode = normalizeRoomCode(submission.roomCode || "");
    if (submissionRoomCode !== safeRoomCode) {
      throw new HttpsError("permission-denied", "Submission does not belong to this room.");
    }
    const targetUid = typeof submission.uid === "string" ? submission.uid.trim() : "";
    if (!targetUid) {
      throw new HttpsError("failed-precondition", "Submission is missing a user.");
    }

    tx.update(submissionRef, {
      approved: action === "approve",
      status: action === "approve" ? "approved" : "rejected",
      moderatedAt: admin.firestore.FieldValue.serverTimestamp(),
      moderatedBy: callerUid,
    });

    if (action === "approve") {
      const approvedAt = admin.firestore.FieldValue.serverTimestamp();
      tx.set(db.collection("users").doc(targetUid), {
        crowdSelfieUrl: submission.url || null,
        crowdSelfieStoragePath: submission.storagePath || null,
        crowdSelfieStatus: "approved",
        crowdSelfieApprovedAt: approvedAt,
        crowdSelfieSourceRoomCode: safeRoomCode,
        crowdSelfieSubmissionId: submissionId,
        crowdSelfieConsentAcceptedAt: submission.consentAcceptedAt || approvedAt,
      }, { merge: true });

      tx.set(rootRef.collection("room_users").doc(`${safeRoomCode}_${targetUid}`), {
        crowdSelfieUrl: submission.url || null,
        crowdSelfieStatus: "approved",
        crowdSelfieApprovedAt: approvedAt,
      }, { merge: true });
    }
  });

  return { ok: true, action };
});

exports.deleteRoomReaction = onCall({ cors: true }, async (request) => {
  checkRateLimit(request.rawRequest, "delete_room_reaction", { perMinute: 40, perHour: 400 });
  const callerUid = request.auth?.uid || "";
  if (!callerUid) {
    throw new HttpsError("unauthenticated", "Sign in required.");
  }

  const roomCode = String(request.data?.roomCode || "").trim().toUpperCase();
  ensureString(roomCode, "roomCode");
  const reactionId = String(request.data?.reactionId || "").trim();
  ensureString(reactionId, "reactionId");

  const db = admin.firestore();
  const rootRef = getRootRef();
  const reactionRef = rootRef.collection("reactions").doc(reactionId);

  await db.runTransaction(async (tx) => {
    const { roomCode: safeRoomCode } = await ensureRoomHostAccess({
      tx,
      rootRef,
      roomCode,
      callerUid,
      deniedMessage: "Only room hosts can remove reactions.",
    });
    const reactionSnap = await tx.get(reactionRef);
    if (!reactionSnap.exists) {
      throw new HttpsError("not-found", "Reaction not found.");
    }
    const reaction = reactionSnap.data() || {};
    const reactionRoomCode = normalizeRoomCode(reaction.roomCode || "");
    if (reactionRoomCode !== safeRoomCode) {
      throw new HttpsError("permission-denied", "Reaction does not belong to this room.");
    }
    tx.delete(reactionRef);
  });

  return { ok: true };
});

exports.createSubscriptionCheckout = onCall(
  { cors: true, secrets: [STRIPE_SECRET_KEY] },
  async (request) => {
    checkRateLimit(request.rawRequest, "stripe_checkout");
    const callerUid = requireAuth(request);
    enforceAppCheckIfEnabled(request, "create_subscription_checkout");
    const planId = String(request.data?.planId || "").trim();
    const plan = getPlanDefinition(planId);
    if (!plan || !isPublicPaidHostPlan(planId)) {
      throw new HttpsError("invalid-argument", "Invalid subscription plan.");
    }

    const orgName = typeof request.data?.orgName === "string" ? request.data.orgName : "";
    const { orgId } = await ensureOrganizationForUser({ uid: callerUid, orgName });
    const checkoutRequestId = normalizeCheckoutToken(request.data?.requestId || "", 120);
    const checkoutIdempotencyKey = buildSubscriptionCheckoutIdempotencyKey({
      uid: callerUid,
      orgId,
      planId,
      requestId: checkoutRequestId,
    });
    const origin = resolveOrigin(request.rawRequest, request.data?.origin);
    const stripe = getStripeClient();
    const ownerEmail = typeof request.auth?.token?.email === "string"
      ? request.auth.token.email.trim()
      : "";

    const session = await stripe.checkout.sessions.create({
      mode: "subscription",
      payment_method_types: ["card"],
      allow_promotion_codes: true,
      customer_email: ownerEmail || undefined,
      line_items: [
        {
          price_data: {
            currency: "usd",
            unit_amount: plan.amountCents,
            recurring: { interval: plan.interval },
            product_data: {
              name: `BeauRocks ${plan.name}`,
              description: `Host plan for Room creation and Host Dashboard access (${plan.id})`,
            },
          },
          quantity: 1,
        },
      ],
      metadata: {
        checkoutType: "org_subscription",
        requestId: checkoutRequestId,
        orgId,
        ownerUid: callerUid,
        planId: plan.id,
      },
      subscription_data: {
        metadata: {
          orgId,
          ownerUid: callerUid,
          planId: plan.id,
        },
      },
      success_url: `${origin}/?mode=host&subscription=success&org=${encodeURIComponent(orgId)}`,
      cancel_url: `${origin}/?mode=host&subscription=cancel&org=${encodeURIComponent(orgId)}`,
    }, {
      idempotencyKey: checkoutIdempotencyKey,
    });

    return {
      url: session.url,
      id: session.id,
      orgId,
      planId: plan.id,
    };
  }
);

exports.createSubscriptionPortalSession = onCall(
  { cors: true, secrets: [STRIPE_SECRET_KEY] },
  async (request) => {
    checkRateLimit(request.rawRequest, "stripe_checkout");
    const callerUid = requireAuth(request);
    enforceAppCheckIfEnabled(request, "create_subscription_portal");
    const { orgId, role } = await ensureOrganizationForUser({ uid: callerUid });
    const superAdmin = await isSuperAdminUid(callerUid);
    if (!orgId) {
      throw new HttpsError("failed-precondition", "Organization is not initialized.");
    }
    if (!superAdmin && !["owner", "admin"].includes(role)) {
      throw new HttpsError("permission-denied", "Only organization owners/admins can manage billing.");
    }
    const subSnap = await orgsCollection()
      .doc(orgId)
      .collection("subscription")
      .doc("current")
      .get();
    const sub = subSnap.data() || {};
    const stripeCustomerId = String(sub.stripeCustomerId || "").trim();
    if (!stripeCustomerId) {
      throw new HttpsError(
        "failed-precondition",
        "No Stripe billing profile found. Start a subscription first."
      );
    }
    const origin = resolveOrigin(request.rawRequest, request.data?.origin);
    const stripe = getStripeClient();
    const session = await stripe.billingPortal.sessions.create({
      customer: stripeCustomerId,
      return_url: `${origin}/?mode=host&billing=return`,
    });

    return { url: session.url };
  }
);

exports.createTipCrateCheckout = onCall(
  { cors: true, secrets: [STRIPE_SECRET_KEY] },
  async (request) => {
    checkRateLimit(request.rawRequest, "stripe_checkout");
    const callerUid = requireAuth(request);
    enforceAppCheckIfEnabled(request, "create_tip_crate_checkout");
    const roomCode = normalizeRoomCode(request.data?.roomCode || "");
    const crateId = request.data?.crateId || "";
    ensureString(roomCode, "roomCode");
    ensureString(crateId, "crateId");

    const roomSnap = await getRootRef().collection("rooms").doc(roomCode).get();
    if (!roomSnap.exists) {
      throw new HttpsError("not-found", "Room not found.");
    }
    const crates = Array.isArray(roomSnap.data()?.tipCrates) && roomSnap.data().tipCrates.length
      ? roomSnap.data().tipCrates
      : DEFAULT_TIP_CRATES;
    const crate = crates.find((c) => c.id === crateId);
    if (!crate) {
      throw new HttpsError("invalid-argument", "Tip crate not found.");
    }
    const amount = clampNumber(crate.amount || 0, 1, 500, 0);
    if (!amount) {
      throw new HttpsError("invalid-argument", "Invalid tip amount.");
    }
    const points = clampNumber(crate.points || 0, 0, 100000, 0);
    const origin = resolveOrigin(request.rawRequest, request.data?.origin);
    const buyerUid = callerUid;
    const buyerName = normalizeOptionalName(request.data?.userName || "", "Guest");
    const stripe = getStripeClient();

    const session = await stripe.checkout.sessions.create({
      mode: "payment",
      payment_method_types: ["card"],
      line_items: [
        {
          price_data: {
            currency: "usd",
            product_data: {
              name: `BROSS Room Tip: ${crate.label || "Room Boost"}`,
            },
            unit_amount: Math.round(amount * 100),
          },
          quantity: 1,
        },
      ],
      metadata: {
        roomCode,
        crateId,
        points: `${points}`,
        rewardScope: crate.rewardScope || "room",
        awardBadge: crate.awardBadge ? "1" : "0",
        buyerUid,
        buyerName,
        label: crate.label || "Room Boost",
      },
      success_url: `${origin}/?room=${encodeURIComponent(roomCode)}&tip=success`,
      cancel_url: `${origin}/?room=${encodeURIComponent(roomCode)}&tip=cancel`,
    });

    await getRootRef().collection("stripe_checkouts").doc(session.id).set({
      checkoutType: "tip_crate",
      sessionId: session.id,
      roomCode,
      crateId,
      label: crate.label || "Room Boost",
      amount,
      amountCents: Math.round(amount * 100),
      points,
      rewardScope: crate.rewardScope || "room",
      awardBadge: !!crate.awardBadge,
      buyerUid,
      buyerName,
      paymentStatus: String(session.payment_status || "").trim() || null,
      checkoutStatus: "created",
      createdAt: admin.firestore.FieldValue.serverTimestamp(),
    }, { merge: true });

    return { url: session.url, id: session.id };
  }
);

