exports.createBeauBucksCheckout = onCall(
  { cors: true, secrets: [STRIPE_SECRET_KEY] },
  async (request) => {
    checkRateLimit(request.rawRequest, "stripe_checkout");
    const callerUid = requireAuth(request);
    enforceAppCheckIfEnabled(request, "create_beaubucks_checkout");
    if (!requestHasNonAnonymousAccount(request)) {
      throw new HttpsError("failed-precondition", "Sign in to your BeauRocks account before buying BeauBucks.");
    }
    if (!isBeauBucksCheckoutEnabled()) {
      throw new HttpsError("failed-precondition", "BeauBucks purchases are not available yet.");
    }
    if (!isBeauBucksCanaryBuyerAllowed({ uid: callerUid, policy: BEAUBUCKS_CANARY_BUYER_POLICY })) {
      throw new HttpsError("permission-denied", "This BeauBucks preview is limited to invited production testers.");
    }
    const roomCode = normalizeRoomCode(request.data?.roomCode || "");
    const packId = String(request.data?.packId || "").trim();
    ensureString(roomCode, "roomCode");
    ensureString(packId, "packId");
    const pack = getBeauBucksPack(packId);
    if (!pack || pack.publicOffer !== true) {
      throw new HttpsError("invalid-argument", "That BeauBucks pack is not available.");
    }

    const rootRef = getRootRef();
    const roomRef = rootRef.collection("rooms").doc(roomCode);
    const roomUserRef = getRoomUserRef({ rootRef, roomCode, uid: callerUid });
    const [roomSnap, roomUserSnap] = await Promise.all([roomRef.get(), roomUserRef.get()]);
    if (!roomSnap.exists) throw new HttpsError("not-found", "Room not found.");
    if (!roomUserSnap.exists) {
      throw new HttpsError("failed-precondition", "Join the Room before buying BeauBucks.");
    }
    if (!isRoomBeauBucksExperienceEnabled({ roomCode, roomData: roomSnap.data() || {} })) {
      throw new HttpsError("failed-precondition", "BeauBucks purchases are not available for this Room yet.");
    }

    const db = admin.firestore();
    const accountId = buildBeauBucksAccountId({ uid: callerUid });
    const accountRef = db.collection(BEAUBUCKS_ACCOUNT_COLLECTION).doc(accountId);
    const purchaseLimitRef = db.collection(BEAUBUCKS_PURCHASE_LIMIT_COLLECTION).doc(accountId);
    const reservationId = crypto.randomUUID();
    const reservation = await db.runTransaction(async (tx) => {
      const [accountSnap, limitSnap] = await Promise.all([tx.get(accountRef), tx.get(purchaseLimitRef)]);
      const result = evaluateBeauBucksPurchaseReservation({
        account: accountSnap.exists ? (accountSnap.data() || {}) : {},
        limitState: limitSnap.exists ? (limitSnap.data() || {}) : {},
        pack,
        reservationId,
      });
      if (!result.allowed) {
        const message = result.reasonCode === "beaubucks_purchase_limit_reached"
          ? "This account's one-pack BeauBucks canary limit has already been used."
          : result.reasonCode === "beaubucks_purchase_in_progress"
            ? "A BeauBucks checkout is already in progress for this Room."
            : "BeauBucks purchase limits are unavailable.";
        throw new HttpsError("failed-precondition", message);
      }
      tx.set(purchaseLimitRef, {
        schemaVersion: BEAUBUCKS_AUTHORITY_SCHEMA_VERSION,
        accountId,
        uid: callerUid,
        scope: "account",
        purchaseRoomCode: roomCode,
        completedPurchases: result.completedPurchases,
        reservationId,
        reservationExpiresAtMs: result.reservationExpiresAtMs,
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      }, { merge: true });
      return result;
    });

    const origin = resolveOrigin(request.rawRequest, request.data?.origin);
    const stripe = getStripeClient();
    let session = null;
    try {
      session = await stripe.checkout.sessions.create({
        mode: "payment",
        payment_method_types: ["card"],
        expires_at: Math.floor(reservation.reservationExpiresAtMs / 1000),
        line_items: [{
          price_data: {
            currency: pack.currency,
            product_data: { name: `BeauRocks: ${pack.publicLabel}` },
            unit_amount: pack.amountCents,
          },
          quantity: 1,
        }],
        metadata: {
          checkoutType: "beaubucks_purchase",
          roomCode,
          buyerUid: callerUid,
          packId: pack.id,
          beauBucks: `${pack.beauBucks}`,
          rewardScope: "account",
          reservationId,
        },
        payment_intent_data: {
          metadata: {
            checkoutType: "beaubucks_purchase",
            roomCode,
            buyerUid: callerUid,
            packId: pack.id,
            beauBucks: `${pack.beauBucks}`,
            rewardScope: "account",
            reservationId,
          },
        },
        success_url: `${origin}/?room=${encodeURIComponent(roomCode)}&beaubucks=success`,
        cancel_url: `${origin}/?room=${encodeURIComponent(roomCode)}&beaubucks=cancel`,
      });

      await Promise.all([
        rootRef.collection("stripe_checkouts").doc(session.id).set({
          schemaVersion: BEAUBUCKS_AUTHORITY_SCHEMA_VERSION,
          checkoutType: "beaubucks_purchase",
          sessionId: session.id,
          roomCode,
          buyerUid: callerUid,
          packId: pack.id,
          label: pack.publicLabel,
          amountCents: pack.amountCents,
          currency: pack.currency,
          beauBucks: pack.beauBucks,
          rewardScope: "account",
          reservationId,
          reservationExpiresAtMs: reservation.reservationExpiresAtMs,
          paymentStatus: String(session.payment_status || "").trim() || null,
          checkoutStatus: "created",
          createdAt: admin.firestore.FieldValue.serverTimestamp(),
        }, { merge: true }),
        purchaseLimitRef.set({
          reservationSessionId: session.id,
          updatedAt: admin.firestore.FieldValue.serverTimestamp(),
        }, { merge: true }),
      ]);
      return { url: session.url, id: session.id };
    } catch (error) {
      if (session?.id && stripe.checkout.sessions.expire) {
        await stripe.checkout.sessions.expire(session.id).catch(() => {});
      }
      await db.runTransaction(async (tx) => {
        const limitSnap = await tx.get(purchaseLimitRef);
        if (limitSnap.exists && String(limitSnap.get("reservationId") || "") === reservationId) {
          tx.set(purchaseLimitRef, {
            reservationId: null,
            reservationSessionId: null,
            reservationExpiresAtMs: 0,
            updatedAt: admin.firestore.FieldValue.serverTimestamp(),
          }, { merge: true });
        }
      }).catch(() => {});
      throw error;
    }
  }
);

exports.createAppleMusicToken = onCall(
  { cors: true, secrets: [APPLE_MUSIC_TEAM_ID, APPLE_MUSIC_KEY_ID, APPLE_MUSIC_PRIVATE_KEY] },
  async (request) => {
    checkRateLimit(request.rawRequest, "apple_music_token", { perMinute: 10, perHour: 80 });
    await checkDurableRateLimit(request.rawRequest, "apple_music_token", { perMinute: 10, perHour: 80 });
    const { uid: callerUid } = await requireCapability(request, "api.apple_music");
    enforceAppCheckIfEnabled(request, "create_apple_music_token");
    const roomCode = normalizeRoomCode(request.data?.roomCode || "");
    ensureString(roomCode, "roomCode");
    await ensureRoomHostAccess({
      roomCode,
      callerUid,
      deniedMessage: "Only room hosts can request Apple Music tokens.",
    });

    const teamId = normalizeAppleMusicSecret(APPLE_MUSIC_TEAM_ID.value());
    const keyId = normalizeAppleMusicSecret(APPLE_MUSIC_KEY_ID.value());
    const rawKey = normalizeAppleMusicSecret(APPLE_MUSIC_PRIVATE_KEY.value(), { preserveNewlines: true });
    const privateKey = rawKey.includes("BEGIN") ? rawKey : rawKey.replace(/\\n/g, "\n");
    const now = Math.floor(Date.now() / 1000);
    const exp = now + 60 * 60 * 12;
    const token = jwt.sign(
      { iss: teamId, iat: now, exp },
      privateKey,
      { algorithm: "ES256", header: { alg: "ES256", kid: keyId } }
    );
    return { token, expiresAt: exp };
  }
);

const fulfillVerifiedAdditionalUsageCheckout = async ({ event = {}, session = {}, metadata = {} } = {}) => {
  const verification = buildVerifiedAdditionalUsageGrant({
    policy: ADDITIONAL_USAGE_POLICY,
    allowedMeterIds: Object.keys(USAGE_METER_DEFINITIONS),
    checkout: {
      checkoutType: metadata.checkoutType,
      paymentStatus: session.payment_status,
      orgId: metadata.orgId,
      periodKey: metadata.periodKey,
      packId: metadata.packId,
      amountCents: session.amount_total,
      currency: session.currency,
    },
  });
  if (!verification.ok) return verification;

  const grant = verification.grant;
  const eventId = sanitizeSecurityToken(event.id || session.id || "", 180);
  const sessionId = sanitizeSecurityToken(session.id || "", 180);
  const paymentIntentId = sanitizeSecurityToken(
    typeof session.payment_intent === "string" ? session.payment_intent : session.payment_intent?.id,
    180,
  );
  const chargeId = sanitizeSecurityToken(session.payment_intent?.latest_charge || "", 180);
  if (!eventId || !sessionId || !paymentIntentId) {
    return { ok: false, reasonCode: ADDITIONAL_USAGE_REASON_CODES.invalidPaymentReference };
  }
  const orgRef = orgsCollection().doc(grant.orgId);
  const ledgerRef = orgRef.collection(ORG_ADDITIONAL_USAGE_LEDGER_COLLECTION).doc(sessionId);
  const grantStateRef = orgRef.collection(ORG_ADDITIONAL_USAGE_GRANT_STATE_COLLECTION).doc(sessionId);
  const capacityRef = orgRef.collection(ORG_USAGE_CAPACITY_COLLECTION).doc(grant.period);
  const paymentRef = admin.firestore().collection(ADDITIONAL_USAGE_PAYMENT_REFS_COLLECTION).doc(paymentIntentId);
  const now = admin.firestore.FieldValue.serverTimestamp();

  return admin.firestore().runTransaction(async (tx) => {
    const [orgSnap, ledgerSnap, paymentRefSnap] = await Promise.all([
      tx.get(orgRef),
      tx.get(ledgerRef),
      tx.get(paymentRef),
    ]);
    if (!orgSnap.exists) {
      return { ok: false, reasonCode: ADDITIONAL_USAGE_REASON_CODES.invalidOrganization };
    }
    if (ledgerSnap.exists) {
      return { ok: true, duplicate: true, grant: ledgerSnap.data() || {} };
    }
    if (paymentRefSnap.exists) {
      return { ok: false, reasonCode: ADDITIONAL_USAGE_REASON_CODES.paymentReferenceConflict };
    }

    tx.create(ledgerRef, {
      ...grant,
      entryType: "purchase_grant",
      checkoutType: "additional_usage",
      stripeEventId: eventId,
      stripeSessionId: sessionId,
      stripePaymentIntentId: paymentIntentId,
      stripeChargeId: chargeId || null,
      checkoutRequestId: sanitizeSecurityToken(metadata.checkoutRequestId || "", 180) || null,
      createdAt: now,
    });
    tx.create(grantStateRef, {
      schemaVersion: 1,
      orgId: grant.orgId,
      period: grant.period,
      stripeSessionId: sessionId,
      capacityByMeter: grant.capacityByMeter,
      revokedByMeter: {},
      refundedAmountCents: 0,
      status: "active",
      createdAt: now,
      updatedAt: now,
    });
    tx.create(paymentRef, {
      schemaVersion: 1,
      orgId: grant.orgId,
      period: grant.period,
      stripeSessionId: sessionId,
      stripePaymentIntentId: paymentIntentId,
      stripeChargeId: chargeId || null,
      createdAt: now,
    });
    const meters = Object.fromEntries(
      Object.entries(grant.capacityByMeter).map(([meterId, units]) => [
        meterId,
        { granted: admin.firestore.FieldValue.increment(units) },
      ]),
    );
    tx.set(capacityRef, {
      schemaVersion: 1,
      orgId: grant.orgId,
      period: grant.period,
      meters,
      purchaseCount: admin.firestore.FieldValue.increment(1),
      updatedAt: now,
    }, { merge: true });
    return { ok: true, duplicate: false, grant };
  });
};

const fulfillVerifiedBeauBucksCheckout = async ({ event = {}, session = {} } = {}) => {
  const eventId = sanitizeSecurityToken(event.id || "", 180);
  const sessionId = sanitizeSecurityToken(session.id || "", 180);
  const paymentIntentId = sanitizeSecurityToken(
    typeof session.payment_intent === "string" ? session.payment_intent : session.payment_intent?.id,
    180,
  );
  if (!eventId || !sessionId || !paymentIntentId) {
    return { ok: false, reasonCode: "beaubucks_payment_reference_invalid" };
  }
  const db = admin.firestore();
  const checkoutRef = getRootRef().collection("stripe_checkouts").doc(sessionId);
  const purchaseEntryId = buildLedgerEntryId(`beaubucks_purchase:${sessionId}`);
  const purchaseRef = db.collection(LEDGER_COLLECTION).doc(purchaseEntryId);
  const paymentRefId = buildBeauBucksPaymentRefId(paymentIntentId);
  const paymentRef = db.collection(BEAUBUCKS_PAYMENT_REF_COLLECTION).doc(paymentRefId);
  const pendingAdjustmentRef = db.collection(BEAUBUCKS_PENDING_ADJUSTMENT_COLLECTION).doc(paymentRefId);
  const now = admin.firestore.FieldValue.serverTimestamp();

  return db.runTransaction(async (tx) => {
    const checkoutSnap = await tx.get(checkoutRef);
    const checkout = checkoutSnap.exists ? (checkoutSnap.data() || {}) : {};
    const verification = validateBeauBucksCheckoutFulfillment({ checkout, session });
    if (!verification.ok) return verification;
    const { pack, roomCode, buyerUid } = verification;
    const accountId = buildBeauBucksAccountId({ uid: buyerUid });
    const accountRef = db.collection(BEAUBUCKS_ACCOUNT_COLLECTION).doc(accountId);
    const purchaseLimitRef = db.collection(BEAUBUCKS_PURCHASE_LIMIT_COLLECTION).doc(accountId);
    const [purchaseSnap, paymentRefSnap, accountSnap, pendingAdjustmentSnap, purchaseLimitSnap] = await Promise.all([
      tx.get(purchaseRef),
      tx.get(paymentRef),
      tx.get(accountRef),
      tx.get(pendingAdjustmentRef),
      tx.get(purchaseLimitRef),
    ]);
    if (purchaseSnap.exists) {
      return { ok: true, duplicate: true, grant: purchaseSnap.data() || {} };
    }
    if (paymentRefSnap.exists) {
      return { ok: false, reasonCode: "beaubucks_payment_reference_conflict" };
    }
    const account = accountSnap.exists ? (accountSnap.data() || {}) : {};
    const purchaseLimitState = purchaseLimitSnap.exists ? (purchaseLimitSnap.data() || {}) : {};
    const balanceBefore = Math.max(0, Math.floor(Number(account.balance || 0) || 0));
    const grantedBalance = balanceBefore + pack.beauBucks;
    const pendingAdjustment = pendingAdjustmentSnap.exists ? (pendingAdjustmentSnap.data() || {}) : {};
    const pendingAdjustmentType = pendingAdjustment.status === "pending"
      ? pendingAdjustment.chargebackObserved === true
        ? "chargeback"
        : Number(pendingAdjustment.cumulativeRefundedAmountCents || 0) > 0
          ? "refund"
          : ""
      : "";
    const pendingPlan = pendingAdjustmentType ? buildBeauBucksAdjustmentPlan({
      purchaseBeauBucks: pack.beauBucks,
      purchaseAmountCents: pack.amountCents,
      priorAdjustedAmountCents: 0,
      requestedAdjustedAmountCents: pendingAdjustmentType === "chargeback"
        ? pack.amountCents
        : pendingAdjustment.cumulativeRefundedAmountCents,
      availableBalance: grantedBalance,
      adjustmentType: pendingAdjustmentType,
    }) : null;
    const balanceAfter = pendingPlan ? pendingPlan.balanceAfter : grantedBalance;
    const accountStatus = pendingPlan?.restrictAccount === true
      ? "restricted"
      : String(account.status || "active");
    const paymentStatus = pendingPlan
      ? pendingAdjustmentType === "chargeback"
        ? "chargeback"
        : pendingPlan.targetAdjustedAmountCents >= pack.amountCents ? "refunded" : "partially_refunded"
      : "paid";
    const policy = getBeauBucksPolicy();

    createAuthoritativeLedgerEntry({
      writer: tx,
      db,
      idempotencyKey: `beaubucks_purchase:${sessionId}`,
      roomCode,
      uid: buyerUid,
      eventCredits: { enabled: true, presetId: "beaubucks" },
      walletScope: "account",
      type: "purchase_grant",
      amount: pack.beauBucks,
      direction: "credit",
      source: {
        provider: "stripe",
        sourceId: sessionId,
        sourceCollection: "stripe_checkouts",
      },
      attribution: { fundCode: pack.id },
      financial: {
        amountCents: pack.amountCents,
        currency: pack.currency,
        externalTransactionId: paymentIntentId,
      },
      serverTimestamp: now,
    });
    tx.set(accountRef, {
      schemaVersion: BEAUBUCKS_AUTHORITY_SCHEMA_VERSION,
      accountId,
      uid: buyerUid,
      currency: "beaubucks",
      scope: "account",
      balance: balanceAfter,
      status: accountStatus,
      lifetimePurchased: admin.firestore.FieldValue.increment(pack.beauBucks),
      lifetimeRevoked: admin.firestore.FieldValue.increment(pendingPlan?.appliedRevocation || 0),
      unrecoveredBeauBucks: admin.firestore.FieldValue.increment(pendingPlan?.unrecoveredAmount || 0),
      lastPurchaseRoomCode: roomCode,
      lastActivityRoomCode: roomCode,
      lastEntryAt: now,
      createdAt: account.createdAt || now,
      updatedAt: now,
    }, { merge: true });
    const completedPurchases = Math.max(
      Math.floor(Number(purchaseLimitState.completedPurchases || 0) || 0),
      Math.floor((Number(account.lifetimePurchased || 0) || 0) / pack.beauBucks),
    ) + 1;
    tx.set(purchaseLimitRef, {
      schemaVersion: BEAUBUCKS_AUTHORITY_SCHEMA_VERSION,
      accountId,
      uid: buyerUid,
      scope: "account",
      purchaseRoomCode: roomCode,
      completedPurchases,
      lifetimePurchaseCents: admin.firestore.FieldValue.increment(pack.amountCents),
      lastCompletedSessionId: sessionId,
      ...(String(purchaseLimitState.reservationId || "") === String(session.metadata?.reservationId || "")
        ? { reservationId: null, reservationSessionId: null, reservationExpiresAtMs: 0 }
        : {}),
      updatedAt: now,
    }, { merge: true });
    tx.create(paymentRef, {
      schemaVersion: BEAUBUCKS_AUTHORITY_SCHEMA_VERSION,
      checkoutType: "beaubucks_purchase",
      stripeSessionId: sessionId,
      stripePaymentIntentId: paymentIntentId,
      roomCode,
      uid: buyerUid,
      accountId,
      walletScope: "account",
      packId: pack.id,
      purchaseLedgerEntryId: purchaseEntryId,
      purchaseBeauBucks: pack.beauBucks,
      purchaseAmountCents: pack.amountCents,
      adjustedAmountCents: pendingPlan?.targetAdjustedAmountCents || 0,
      revokedBeauBucks: pendingPlan?.appliedRevocation || 0,
      unrecoveredBeauBucks: pendingPlan?.unrecoveredAmount || 0,
      currency: pack.currency,
      status: paymentStatus,
      createdAt: now,
      updatedAt: now,
    });
    tx.set(checkoutRef, {
      checkoutStatus: paymentStatus === "paid" ? "completed" : paymentStatus,
      paymentStatus,
      webhookEventId: eventId,
      purchaseLedgerEntryId: purchaseEntryId,
      fulfilledAt: now,
      updatedAt: now,
      policyStatusAtFulfillment: String(policy.status || "unknown"),
    }, { merge: true });
    if (pendingPlan) {
      const recoveryAdjustmentId = buildBeauBucksAdjustmentId(`pending_recovery:${paymentRefId}`);
      const recoveryAdjustmentRef = db.collection(BEAUBUCKS_ADJUSTMENT_COLLECTION).doc(recoveryAdjustmentId);
      tx.create(recoveryAdjustmentRef, {
        schemaVersion: BEAUBUCKS_AUTHORITY_SCHEMA_VERSION,
        adjustmentId: recoveryAdjustmentId,
        adjustmentType: pendingAdjustmentType,
        recoverySource: "pending_payment_adjustment",
        paymentRefId,
        stripeSessionId: sessionId,
        stripePaymentIntentId: paymentIntentId,
        pendingEventIdHashes: Array.isArray(pendingAdjustment.eventIdHashes)
          ? pendingAdjustment.eventIdHashes.slice(-20)
          : [],
        roomCode,
        uid: buyerUid,
        accountId,
        purchaseLedgerEntryId: purchaseEntryId,
        purchaseAmountCents: pack.amountCents,
        adjustmentAmountCents: pendingPlan.targetAdjustedAmountCents,
        targetAdjustedAmountCents: pendingPlan.targetAdjustedAmountCents,
        requestedRevocation: pendingPlan.requestedRevocation,
        appliedRevocation: pendingPlan.appliedRevocation,
        unrecoveredAmount: pendingPlan.unrecoveredAmount,
        balanceAfter,
        currency: pack.currency,
        status: paymentStatus,
        createdAt: now,
      });
      if (pendingPlan.appliedRevocation > 0) {
        createAuthoritativeLedgerEntry({
          writer: tx,
          db,
          idempotencyKey: `beaubucks_pending_adjustment:${paymentRefId}`,
          roomCode,
          uid: buyerUid,
          eventCredits: { enabled: true, presetId: "beaubucks" },
          walletScope: "account",
          type: pendingAdjustmentType === "chargeback" ? "chargeback_reversal" : "refund_reversal",
          amount: pendingPlan.appliedRevocation,
          direction: "debit",
          source: {
            provider: "stripe",
            sourceId: paymentRefId,
            sourceCollection: BEAUBUCKS_PENDING_ADJUSTMENT_COLLECTION,
          },
          attribution: { fundCode: pack.id },
          financial: {
            amountCents: pendingPlan.targetAdjustedAmountCents,
            currency: pack.currency,
            externalTransactionId: paymentIntentId,
          },
          serverTimestamp: now,
        });
      }
      tx.set(pendingAdjustmentRef, {
        status: "recovered",
        checkoutSessionId: sessionId,
        purchaseLedgerEntryId: purchaseEntryId,
        adjustmentId: recoveryAdjustmentId,
        appliedRevocation: pendingPlan.appliedRevocation,
        unrecoveredAmount: pendingPlan.unrecoveredAmount,
        recoveredAt: now,
        updatedAt: now,
      }, { merge: true });
    }
    return {
      ok: true,
      duplicate: false,
      pendingAdjustmentApplied: !!pendingPlan,
      pendingAdjustmentType: pendingAdjustmentType || null,
      grant: { roomCode, uid: buyerUid, amount: pack.beauBucks, balanceAfter },
    };
  });
};

const readStripeObjectId = (value = null) => sanitizeSecurityToken(
  typeof value === "string" ? value : value?.id,
  180,
);

const resolveAdjustmentPaymentIntentId = async ({ stripe = null, source = {} } = {}) => {
  const direct = readStripeObjectId(source?.payment_intent);
  if (direct) return direct;
  const chargeId = readStripeObjectId(source?.charge || source?.id);
  if (!chargeId || !stripe?.charges?.retrieve) return "";
  try {
    const charge = await stripe.charges.retrieve(chargeId);
    return readStripeObjectId(charge?.payment_intent);
  } catch (error) {
    console.warn("Could not resolve Additional usage payment intent from Stripe charge.", {
      chargeId,
      message: String(error?.message || error),
    });
    return "";
  }
};

const capturePendingBeauBucksPaymentAdjustment = async ({
  event = {},
  paymentIntentId = "",
  adjustmentType = "refund",
  source = {},
} = {}) => {
  const safePaymentIntentId = sanitizeSecurityToken(paymentIntentId, 180);
  const eventId = sanitizeSecurityToken(event.id || "", 180);
  const sourceAmount = Math.max(0, Math.floor(Number(source?.amount || 0) || 0));
  const cumulativeRefundedAmountCents = Math.max(0, Math.floor(Number(source?.amount_refunded || 0) || 0));
  if (!safePaymentIntentId || !eventId || (adjustmentType === "refund" ? cumulativeRefundedAmountCents <= 0 : sourceAmount <= 0)) {
    return { ok: false, ignored: true, reasonCode: "beaubucks_pending_adjustment_invalid" };
  }
  const db = admin.firestore();
  const paymentRefId = buildBeauBucksPaymentRefId(safePaymentIntentId);
  const eventIdHash = buildBeauBucksAdjustmentId(eventId);
  const paymentRef = db.collection(BEAUBUCKS_PAYMENT_REF_COLLECTION).doc(paymentRefId);
  const pendingRef = db.collection(BEAUBUCKS_PENDING_ADJUSTMENT_COLLECTION).doc(paymentRefId);
  const pendingEventRef = db.collection(BEAUBUCKS_PENDING_ADJUSTMENT_EVENT_COLLECTION).doc(eventIdHash);
  const now = admin.firestore.FieldValue.serverTimestamp();
  const expiresAt = admin.firestore.Timestamp.fromMillis(Date.now() + (90 * 24 * 60 * 60 * 1000));

  return db.runTransaction(async (tx) => {
    const [paymentRefSnap, pendingSnap, pendingEventSnap] = await Promise.all([
      tx.get(paymentRef),
      tx.get(pendingRef),
      tx.get(pendingEventRef),
    ]);
    if (paymentRefSnap.exists) {
      return { ok: true, ignored: true, paymentReferenceAvailable: true };
    }
    if (pendingEventSnap.exists) {
      return { ok: true, ignored: true, pending: true, duplicate: true };
    }
    const existing = pendingSnap.exists ? (pendingSnap.data() || {}) : {};
    const pendingState = buildPendingBeauBucksAdjustmentState({
      existing,
      eventIdHash,
      adjustmentType,
      cumulativeRefundedAmountCents,
      chargebackAmountCents: sourceAmount,
    });
    tx.create(pendingEventRef, {
      schemaVersion: BEAUBUCKS_AUTHORITY_SCHEMA_VERSION,
      paymentRefId,
      eventIdHash,
      stripeEventId: eventId,
      stripeChargeId: readStripeObjectId(source?.charge || source?.id) || null,
      adjustmentType,
      amountCents: sourceAmount,
      cumulativeRefundedAmountCents,
      currency: String(source?.currency || "usd").trim().toLowerCase(),
      status: "pending_purchase_classification",
      createdAt: now,
      expiresAt,
    });
    tx.set(pendingRef, {
      schemaVersion: BEAUBUCKS_AUTHORITY_SCHEMA_VERSION,
      paymentRefId,
      status: "pending",
      ...pendingState,
      firstDetectedAt: existing.firstDetectedAt || now,
      lastDetectedAt: now,
      updatedAt: now,
      expiresAt,
    }, { merge: true });
    return { ok: true, ignored: true, pending: true, duplicate: false };
  });
};

const applyBeauBucksPaymentAdjustment = async ({
  event = {},
  paymentIntentId = "",
  adjustmentType = "refund",
  source = {},
} = {}) => {
  const safePaymentIntentId = sanitizeSecurityToken(paymentIntentId, 180);
  const eventId = sanitizeSecurityToken(event.id || "", 180);
  if (!safePaymentIntentId || !eventId) {
    return { ok: false, ignored: true, reasonCode: "beaubucks_payment_reference_invalid" };
  }
  const db = admin.firestore();
  const paymentRef = db.collection(BEAUBUCKS_PAYMENT_REF_COLLECTION)
    .doc(buildBeauBucksPaymentRefId(safePaymentIntentId));
  const adjustmentRef = db.collection(BEAUBUCKS_ADJUSTMENT_COLLECTION)
    .doc(buildBeauBucksAdjustmentId(eventId));
  const now = admin.firestore.FieldValue.serverTimestamp();

  return db.runTransaction(async (tx) => {
    const paymentRefSnap = await tx.get(paymentRef);
    if (!paymentRefSnap.exists) {
      return { ok: true, ignored: true, reasonCode: "not_beaubucks_purchase" };
    }
    const payment = paymentRefSnap.data() || {};
    const roomCode = normalizeRoomCode(payment.roomCode || "");
    const uid = String(payment.uid || "").trim();
    const storedAccountId = String(payment.accountId || "").trim();
    const accountId = buildBeauBucksAccountId({ uid });
    const purchaseLedgerEntryId = String(payment.purchaseLedgerEntryId || "").trim();
    if (!roomCode || !uid || !storedAccountId || !accountId || !purchaseLedgerEntryId) {
      return { ok: false, ignored: true, reasonCode: "beaubucks_payment_reference_invalid" };
    }
    const accountRef = db.collection(BEAUBUCKS_ACCOUNT_COLLECTION).doc(accountId);
    const purchaseRef = db.collection(LEDGER_COLLECTION).doc(purchaseLedgerEntryId);
    const [adjustmentSnap, accountSnap, purchaseSnap] = await Promise.all([
      tx.get(adjustmentRef),
      tx.get(accountRef),
      tx.get(purchaseRef),
    ]);
    if (adjustmentSnap.exists) {
      return { ok: true, ignored: false, duplicate: true, ...(adjustmentSnap.data() || {}) };
    }
    if (!purchaseSnap.exists) {
      return { ok: false, ignored: true, reasonCode: "beaubucks_purchase_missing" };
    }
    const account = accountSnap.exists ? (accountSnap.data() || {}) : {};
    const purchaseAmountCents = Math.max(0, Math.floor(Number(payment.purchaseAmountCents || 0) || 0));
    const priorAdjustedAmountCents = Math.max(0, Math.floor(Number(payment.adjustedAmountCents || 0) || 0));
    const requestedAdjustedAmountCents = adjustmentType === "chargeback"
      ? purchaseAmountCents
      : Math.max(0, Math.floor(Number(source?.amount_refunded || 0) || 0));
    const plan = buildBeauBucksAdjustmentPlan({
      purchaseBeauBucks: payment.purchaseBeauBucks,
      purchaseAmountCents,
      priorAdjustedAmountCents,
      requestedAdjustedAmountCents,
      availableBalance: account.balance,
      adjustmentType,
    });
    const adjustmentAmountCents = Math.max(0, plan.targetAdjustedAmountCents - priorAdjustedAmountCents);
    const nextRevoked = Math.max(0, Math.floor(Number(payment.revokedBeauBucks || 0) || 0))
      + plan.appliedRevocation;
    const nextUnrecovered = Math.max(0, Math.floor(Number(payment.unrecoveredBeauBucks || 0) || 0))
      + plan.unrecoveredAmount;
    const chargeId = readStripeObjectId(source?.charge || source?.id);
    const paymentStatus = adjustmentType === "chargeback"
      ? "chargeback"
      : plan.targetAdjustedAmountCents >= purchaseAmountCents ? "refunded" : "partially_refunded";

    tx.create(adjustmentRef, {
      schemaVersion: BEAUBUCKS_AUTHORITY_SCHEMA_VERSION,
      adjustmentId: adjustmentRef.id,
      adjustmentType,
      stripeEventId: eventId,
      stripeSessionId: payment.stripeSessionId,
      stripePaymentIntentId: safePaymentIntentId,
      stripeChargeId: chargeId || null,
      roomCode,
      uid,
      accountId,
      originalAccountId: storedAccountId,
      walletScope: "account",
      purchaseLedgerEntryId,
      purchaseAmountCents,
      adjustmentAmountCents,
      targetAdjustedAmountCents: plan.targetAdjustedAmountCents,
      requestedRevocation: plan.requestedRevocation,
      appliedRevocation: plan.appliedRevocation,
      unrecoveredAmount: plan.unrecoveredAmount,
      balanceAfter: plan.balanceAfter,
      currency: String(source?.currency || payment.currency || "usd").trim().toLowerCase(),
      status: paymentStatus,
      createdAt: now,
    });
    if (plan.appliedRevocation > 0) {
      createAuthoritativeLedgerEntry({
        writer: tx,
        db,
        idempotencyKey: `beaubucks_adjustment:${eventId}`,
        roomCode,
        uid,
        eventCredits: { enabled: true, presetId: "beaubucks" },
        walletScope: "account",
        type: adjustmentType === "chargeback" ? "chargeback_reversal" : "refund_reversal",
        amount: plan.appliedRevocation,
        direction: "debit",
        source: {
          provider: "stripe",
          sourceId: eventId,
          sourceCollection: BEAUBUCKS_ADJUSTMENT_COLLECTION,
        },
        attribution: { fundCode: String(payment.packId || "") },
        financial: {
          amountCents: adjustmentAmountCents,
          currency: String(payment.currency || "usd"),
          externalTransactionId: safePaymentIntentId,
        },
        serverTimestamp: now,
      });
    }
    tx.set(accountRef, {
      schemaVersion: BEAUBUCKS_AUTHORITY_SCHEMA_VERSION,
      accountId,
      uid,
      currency: "beaubucks",
      scope: "account",
      balance: plan.balanceAfter,
      status: plan.restrictAccount ? "restricted" : String(account.status || "active"),
      lifetimeRevoked: admin.firestore.FieldValue.increment(plan.appliedRevocation),
      unrecoveredBeauBucks: admin.firestore.FieldValue.increment(plan.unrecoveredAmount),
      lastActivityRoomCode: roomCode,
      ...(plan.appliedRevocation > 0 ? { lastEntryAt: now } : {}),
      updatedAt: now,
    }, { merge: true });
    tx.set(paymentRef, {
      adjustedAmountCents: plan.targetAdjustedAmountCents,
      revokedBeauBucks: nextRevoked,
      unrecoveredBeauBucks: nextUnrecovered,
      status: paymentStatus,
      lastAdjustmentType: adjustmentType,
      lastAdjustmentEventId: eventId,
      updatedAt: now,
    }, { merge: true });
    if (payment.stripeSessionId) {
      tx.set(getRootRef().collection("stripe_checkouts").doc(payment.stripeSessionId), {
        checkoutStatus: paymentStatus,
        paymentStatus,
        adjustedAmountCents: plan.targetAdjustedAmountCents,
        revokedBeauBucks: nextRevoked,
        unrecoveredBeauBucks: nextUnrecovered,
        updatedAt: now,
      }, { merge: true });
    }
    return {
      ok: true,
      ignored: false,
      duplicate: false,
      applied: plan.appliedRevocation > 0,
      adjustmentType,
      appliedRevocation: plan.appliedRevocation,
      unrecoveredAmount: plan.unrecoveredAmount,
      balanceAfter: plan.balanceAfter,
    };
  });
};

const applyAdditionalUsageCapacityAdjustment = async ({
  event = {},
  paymentIntentId = "",
  adjustmentType = "refund",
  source = {},
} = {}) => {
  const safePaymentIntentId = sanitizeSecurityToken(paymentIntentId, 180);
  const eventId = sanitizeSecurityToken(event.id || "", 180);
  if (!safePaymentIntentId || !eventId) {
    return { ok: false, ignored: true, reasonCode: ADDITIONAL_USAGE_REASON_CODES.invalidPaymentReference };
  }
  const paymentRef = admin.firestore().collection(ADDITIONAL_USAGE_PAYMENT_REFS_COLLECTION).doc(safePaymentIntentId);
  const now = admin.firestore.FieldValue.serverTimestamp();

  return admin.firestore().runTransaction(async (tx) => {
    const paymentRefSnap = await tx.get(paymentRef);
    if (!paymentRefSnap.exists) {
      return { ok: true, ignored: true, reasonCode: "not_additional_usage" };
    }
    const payment = paymentRefSnap.data() || {};
    const orgId = String(payment.orgId || "").trim();
    const period = normalizeUsagePeriodKey(payment.period || "");
    const sessionId = sanitizeSecurityToken(payment.stripeSessionId || "", 180);
    if (!orgId || !period || !sessionId) {
      return { ok: false, ignored: true, reasonCode: ADDITIONAL_USAGE_REASON_CODES.invalidPaymentReference };
    }
    const orgRef = orgsCollection().doc(orgId);
    const purchaseRef = orgRef.collection(ORG_ADDITIONAL_USAGE_LEDGER_COLLECTION).doc(sessionId);
    const adjustmentRef = orgRef.collection(ORG_ADDITIONAL_USAGE_LEDGER_COLLECTION).doc(eventId);
    const grantStateRef = orgRef.collection(ORG_ADDITIONAL_USAGE_GRANT_STATE_COLLECTION).doc(sessionId);
    const capacityRef = orgRef.collection(ORG_USAGE_CAPACITY_COLLECTION).doc(period);
    const [purchaseSnap, adjustmentSnap, grantStateSnap] = await Promise.all([
      tx.get(purchaseRef),
      tx.get(adjustmentRef),
      tx.get(grantStateRef),
    ]);
    if (adjustmentSnap.exists) {
      return { ok: true, duplicate: true, ignored: false };
    }
    if (!purchaseSnap.exists || !grantStateSnap.exists) {
      return { ok: false, ignored: true, reasonCode: ADDITIONAL_USAGE_REASON_CODES.grantStateMissing };
    }
    const purchase = purchaseSnap.data() || {};
    const grantState = grantStateSnap.data() || {};
    const revocation = buildAdditionalUsageRevocation({
      grant: purchase,
      grantState,
      adjustmentType,
    });
    if (!revocation.ok) return { ...revocation, ignored: true };
    const reasonCode = revocation.applied ? "" : ADDITIONAL_USAGE_REASON_CODES.alreadyFullyRevoked;
    const purchaseAmountCents = toWholeNumber(purchase.amountCents, 0);
    const previousRefundedAmountCents = toWholeNumber(grantState.refundedAmountCents, 0);
    const stripeCumulativeRefundAmountCents = revocation.adjustmentType === "refund"
      ? Math.min(purchaseAmountCents, toWholeNumber(source?.amount_refunded, 0))
      : 0;
    const adjustmentAmountCents = revocation.adjustmentType === "refund"
      ? Math.max(0, stripeCumulativeRefundAmountCents - previousRefundedAmountCents)
      : toWholeNumber(source?.amount, 0);
    tx.create(adjustmentRef, {
      schemaVersion: 1,
      orgId,
      period,
      entryType: "capacity_adjustment",
      adjustmentType: revocation.adjustmentType,
      label: purchase.label || purchase.packId || "Additional usage",
      packId: purchase.packId || "",
      purchaseTransactionId: sessionId,
      stripeEventId: eventId,
      stripeSessionId: sessionId,
      stripePaymentIntentId: safePaymentIntentId,
      stripeChargeId: readStripeObjectId(source?.charge || source?.id) || null,
      amountCents: purchaseAmountCents,
      adjustmentAmountCents,
      stripeCumulativeRefundAmountCents: revocation.adjustmentType === "refund"
        ? stripeCumulativeRefundAmountCents
        : null,
      currency: String(source?.currency || purchase.currency || "usd").trim().toLowerCase(),
      paymentStatus: revocation.adjustmentType === "refund" ? "refunded" : "chargeback",
      capacityByMeter: revocation.capacityByMeter,
      applied: revocation.applied,
      reasonCode,
      createdAt: now,
    });
    tx.set(grantStateRef, {
      revokedByMeter: revocation.nextRevokedByMeter,
      status: "revoked",
      lastAdjustmentType: revocation.adjustmentType,
      lastAdjustmentEventId: eventId,
      ...(revocation.adjustmentType === "refund"
        ? { refundedAmountCents: Math.max(previousRefundedAmountCents, stripeCumulativeRefundAmountCents) }
        : {}),
      updatedAt: now,
    }, { merge: true });
    if (revocation.applied) {
      const meters = Object.fromEntries(
        Object.entries(revocation.capacityByMeter).map(([meterId, units]) => [
          meterId,
          { revoked: admin.firestore.FieldValue.increment(units) },
        ]),
      );
      tx.set(capacityRef, {
        meters,
        adjustmentCount: admin.firestore.FieldValue.increment(1),
        updatedAt: now,
      }, { merge: true });
    }
    tx.set(paymentRef, {
      lastAdjustmentType: revocation.adjustmentType,
      lastAdjustmentEventId: eventId,
      updatedAt: now,
    }, { merge: true });
    return {
      ok: true,
      ignored: false,
      duplicate: false,
      applied: revocation.applied,
      reasonCode,
      orgId,
      period,
    };
  });
};

exports.stripeWebhook = onRequest(
  { secrets: [STRIPE_SECRET_KEY, STRIPE_WEBHOOK_SECRET] },
  async (req, res) => {
    const stripe = getStripeClient();
    const sig = req.headers["stripe-signature"];
    const webhookSecret = STRIPE_WEBHOOK_SECRET.value();
    let event;

    try {
      event = stripe.webhooks.constructEvent(req.rawBody, sig, webhookSecret);
    } catch (err) {
      console.error("Stripe webhook signature failed.", err?.message || err);
      res.status(400).send("Webhook Error");
      return;
    }

    if (event.type === "checkout.session.completed") {
      const session = event.data.object || {};
      const metadata = session.metadata || {};
      const isBeauBucksCheckout = metadata.checkoutType === "beaubucks_purchase";
      if (isBeauBucksCheckout) {
        const result = await fulfillVerifiedBeauBucksCheckout({ event, session });
        if (!result.ok) {
          console.warn("BeauBucks checkout was not granted.", {
            eventId: String(event.id || ""),
            reasonCode: String(result.reasonCode || "beaubucks_purchase_rejected"),
          });
        }
        res.json({
          received: true,
          beauBucksCheckout: true,
          granted: result.ok === true,
          duplicate: result.duplicate === true,
          pendingAdjustmentApplied: result.pendingAdjustmentApplied === true,
          pendingAdjustmentType: result.pendingAdjustmentType || null,
          reasonCode: result.ok ? null : String(result.reasonCode || "beaubucks_purchase_rejected"),
        });
        return;
      }
      const isAdditionalUsageCheckout = metadata.checkoutType === "additional_usage";
      if (isAdditionalUsageCheckout) {
        const result = await fulfillVerifiedAdditionalUsageCheckout({ event, session, metadata });
        if (!result.ok) {
          console.warn("Additional usage checkout was not granted.", {
            eventId: String(event.id || ""),
            reasonCode: String(result.reasonCode || "additional_usage_rejected"),
          });
        }
        res.json({
          received: true,
          additionalUsageCheckout: true,
          granted: result.ok === true,
          duplicate: result.duplicate === true,
          reasonCode: result.ok ? null : String(result.reasonCode || "additional_usage_rejected"),
        });
        return;
      }
      const isSubscriptionCheckout =
        session.mode === "subscription"
        || metadata.checkoutType === "org_subscription"
        || !!metadata.orgId;

      if (isSubscriptionCheckout) {
        const stripeSubscriptionId = typeof session.subscription === "string"
          ? session.subscription
          : "";
        const stripeCustomerId = typeof session.customer === "string"
          ? session.customer
          : "";
        const orgId = String(metadata.orgId || "").trim();
        let ownerUid = String(metadata.ownerUid || "").trim();
        let planId = String(metadata.planId || "").trim();
        let subscription = null;

        if (stripeSubscriptionId) {
          try {
            subscription = await stripe.subscriptions.retrieve(stripeSubscriptionId);
          } catch (err) {
            console.warn("Failed to retrieve Stripe subscription after checkout.", err?.message || err);
          }
        }

        if (!ownerUid && subscription?.metadata?.ownerUid) {
          ownerUid = String(subscription.metadata.ownerUid || "").trim();
        }
        planId = resolvePlanIdFromStripeSubscription({
          explicitPlanId: planId,
          subscription,
        });
        const status = String(
          subscription?.status
            || (session.payment_status === "paid" ? "active" : "incomplete")
        ).toLowerCase();
        const currentPeriodEndSec = Number(subscription?.current_period_end || 0);
        const cancelAtPeriodEnd = !!subscription?.cancel_at_period_end;

        if (orgId) {
          await applyOrganizationSubscriptionState({
            orgId,
            ownerUid,
            planId,
            status,
            provider: "stripe",
            stripeCustomerId,
            stripeSubscriptionId,
            currentPeriodEndSec,
            cancelAtPeriodEnd,
            source: "stripe_checkout_completed",
          });
        }

        res.json({
          received: true,
          subscriptionCheckout: true,
          orgId: orgId || null,
        });
        return;
      }

      const roomCode = metadata.roomCode;
      const points = Number(metadata.points || 0);
      const rewardScope = metadata.rewardScope || (metadata.packId ? "buyer" : "room");
      const awardBadge = metadata.awardBadge === "1";
      const buyerUid = metadata.buyerUid || "";
      const buyerName = metadata.buyerName || "Guest";
      const label = metadata.label || "Room Boost";
      if (!roomCode || !points) {
        res.json({ received: true });
        return;
      }

      const eventId = session.id || event.id;
      const rootRef = getRootRef();
      const eventRef = rootRef.collection("stripe_events").doc(eventId);
      const existing = await eventRef.get();
      if (existing.exists) {
        res.json({ received: true, duplicate: true });
        return;
      }
      await eventRef.set({
        roomCode,
        points,
        amount: session.amount_total || 0,
        createdAt: admin.firestore.FieldValue.serverTimestamp(),
      });
      await rootRef.collection("stripe_checkouts").doc(eventId).set({
        checkoutType: metadata.packId ? "points_pack" : "tip_crate",
        sessionId: eventId,
        roomCode,
        packId: metadata.packId || null,
        crateId: metadata.crateId || null,
        label,
        amountCents: session.amount_total || 0,
        points,
        rewardScope,
        awardBadge,
        buyerUid: buyerUid || null,
        buyerName,
        paymentStatus: String(session.payment_status || "").trim() || null,
        checkoutStatus: "completed",
        webhookEventId: event.id,
        fulfilledAt: admin.firestore.FieldValue.serverTimestamp(),
      }, { merge: true });

      if (rewardScope === "buyer" && buyerUid) {
        const buyerRef = rootRef.collection("room_users").doc(`${roomCode}_${buyerUid}`);
        await buyerRef.set(
          {
            points: admin.firestore.FieldValue.increment(points),
            roomBoostBadge: awardBadge ? true : undefined,
            roomBoosts: awardBadge ? admin.firestore.FieldValue.increment(1) : undefined,
          },
          { merge: true }
        );
        await admin.firestore().collection("users").doc(buyerUid).set(
          {
            uid: buyerUid,
            pointsBalance: admin.firestore.FieldValue.increment(points),
            updatedAt: admin.firestore.FieldValue.serverTimestamp(),
          },
          { merge: true }
        );
      } else {
        const usersSnap = await rootRef
          .collection("room_users")
          .where("roomCode", "==", roomCode)
          .get();
        if (!usersSnap.empty) {
          const batch = admin.firestore().batch();
          usersSnap.docs.forEach((docSnap) => {
            batch.update(docSnap.ref, {
              points: admin.firestore.FieldValue.increment(points),
            });
          });
          await batch.commit();
        }
        if (buyerUid && awardBadge) {
          const buyerRef = rootRef.collection("room_users").doc(`${roomCode}_${buyerUid}`);
          await buyerRef.set(
            {
              roomBoostBadge: true,
              roomBoosts: admin.firestore.FieldValue.increment(1),
            },
            { merge: true }
          );
        }
        await rootRef.collection("rooms").doc(roomCode).set({
          purchaseCelebration: buildRoomPurchaseCelebrationPayload({
            id: eventId,
            buyerName,
            label,
            points,
            badgeAwarded: awardBadge,
            sourceProvider: "stripe",
            rewardScope,
            amountCents: session.amount_total || 0,
          }),
        }, { merge: true });
      }

      const amount = session.amount_total
        ? `$${(session.amount_total / 100).toFixed(2)}`
        : "";
      await rootRef.collection("activities").add({
        roomCode,
        user: rewardScope === "buyer" ? buyerName : "TIP JAR",
        text:
          rewardScope === "buyer"
            ? `${buyerName} grabbed ${label} - +${points} pts`
            : `room tip jar hit ${amount} - everyone +${points} pts`,
        icon: "$",
        timestamp: admin.firestore.FieldValue.serverTimestamp(),
      });
      await syncSelfServeAuctionStateServer({
        rootRef,
        roomCode,
      });
    }

    if (event.type === "charge.refunded" || event.type === "charge.dispute.created") {
      const source = event.data.object || {};
      const adjustmentType = event.type === "charge.refunded" ? "refund" : "chargeback";
      const paymentIntentId = await resolveAdjustmentPaymentIntentId({ stripe, source });
      const additionalUsageResult = await applyAdditionalUsageCapacityAdjustment({
        event,
        paymentIntentId,
        adjustmentType,
        source,
      });
      let beauBucksResult = await applyBeauBucksPaymentAdjustment({
        event,
        paymentIntentId,
        adjustmentType,
        source,
      });
      let pendingBeauBucksResult = null;
      if (additionalUsageResult.ignored === true && beauBucksResult.reasonCode === "not_beaubucks_purchase") {
        pendingBeauBucksResult = await capturePendingBeauBucksPaymentAdjustment({
          event,
          paymentIntentId,
          adjustmentType,
          source,
        });
        if (pendingBeauBucksResult.paymentReferenceAvailable === true) {
          beauBucksResult = await applyBeauBucksPaymentAdjustment({
            event,
            paymentIntentId,
            adjustmentType,
            source,
          });
        }
      }
      const additionalUsageAdjustment = additionalUsageResult.ignored !== true;
      const beauBucksAdjustment = beauBucksResult.ignored !== true;
      const reasonCode = additionalUsageAdjustment
        ? additionalUsageResult.reasonCode
        : beauBucksAdjustment
          ? beauBucksResult.reasonCode
          : additionalUsageResult.reasonCode || beauBucksResult.reasonCode;
      res.json({
        received: true,
        additionalUsageAdjustment,
        beauBucksAdjustment,
        beauBucksAdjustmentPending: pendingBeauBucksResult?.pending === true,
        pendingAdjustmentDuplicate: pendingBeauBucksResult?.duplicate === true,
        adjustmentType,
        applied: additionalUsageResult.applied === true || beauBucksResult.applied === true,
        duplicate: additionalUsageResult.duplicate === true || beauBucksResult.duplicate === true,
        ignored: additionalUsageResult.ignored === true && beauBucksResult.ignored === true,
        reasonCode: reasonCode || null,
      });
      return;
    }

    if (event.type === "customer.subscription.updated" || event.type === "customer.subscription.deleted") {
      const subscription = event.data.object || {};
      const stripeSubscriptionId = String(subscription.id || "").trim();
      if (!stripeSubscriptionId) {
        res.json({ received: true, ignored: true });
        return;
      }
      const subMapSnap = await admin
        .firestore()
        .collection(STRIPE_SUBSCRIPTIONS_COLLECTION)
        .doc(stripeSubscriptionId)
        .get();
      const mapped = subMapSnap.data() || {};
      const orgId = String(subscription.metadata?.orgId || mapped.orgId || "").trim();
      const ownerUid = String(subscription.metadata?.ownerUid || mapped.ownerUid || "").trim();
      const planId = resolvePlanIdFromStripeSubscription({
        explicitPlanId: subscription.metadata?.planId || "",
        subscription,
        fallbackPlanId: mapped.planId || "",
      });
      const status = event.type === "customer.subscription.deleted"
        ? "canceled"
        : String(subscription.status || "inactive").toLowerCase();
      if (orgId) {
        await applyOrganizationSubscriptionState({
          orgId,
          ownerUid,
          planId,
          status,
          provider: "stripe",
          stripeCustomerId: String(subscription.customer || "").trim(),
          stripeSubscriptionId,
          currentPeriodEndSec: Number(subscription.current_period_end || 0),
          cancelAtPeriodEnd: !!subscription.cancel_at_period_end,
          source: "stripe_subscription_event",
        });
      }
    }

    res.json({ received: true });
  }
);

const readGivebutterSignature = (req) =>
  String(
    req.get("signature")
    || req.get("Signature")
    || req.get("x-givebutter-signature")
    || req.get("givebutter-signature")
    || req.get("x-webhook-signature")
    || ""
  ).trim();

const normalizeWebhookSignatureToken = (value = "") => {
  const safeValue = String(value || "").trim();
  const delimiterIndex = safeValue.indexOf("=");
  if (delimiterIndex <= 0) return safeValue;
  const prefix = safeValue.slice(0, delimiterIndex).trim();
  if (!/^[a-z0-9_-]+$/i.test(prefix)) return safeValue;
  return safeValue.slice(delimiterIndex + 1).trim();
};

const timingSafeEqualString = (left = "", right = "") => {
  const safeLeft = String(left || "");
  const safeRight = String(right || "");
  if (!safeLeft || !safeRight) return false;
  const leftBuffer = Buffer.from(safeLeft, "utf8");
  const rightBuffer = Buffer.from(safeRight, "utf8");
  if (leftBuffer.length !== rightBuffer.length) return false;
  try {
    return crypto.timingSafeEqual(leftBuffer, rightBuffer);
  } catch {
    return false;
  }
};

const verifyGivebutterWebhookSignature = ({
  rawBody,
  signature = "",
  secret = "",
} = {}) => {
  const safeSecret = String(secret || "").trim();
  const normalizedSignature = normalizeWebhookSignatureToken(signature);
  if (!safeSecret || !normalizedSignature) return false;
  if (timingSafeEqualString(safeSecret, normalizedSignature)) return true;
  if (!rawBody) return false;
  const safeBody = Buffer.isBuffer(rawBody) ? rawBody : Buffer.from(String(rawBody || ""));
  const expectedHex = crypto
    .createHmac("sha256", safeSecret)
    .update(safeBody)
    .digest("hex");
  if (timingSafeEqualString(expectedHex, normalizedSignature)) return true;
  const expectedBase64 = crypto
    .createHmac("sha256", safeSecret)
    .update(safeBody)
    .digest("base64");
  return timingSafeEqualString(expectedBase64, normalizedSignature);
};

const normalizeGivebutterWebhookPayload = (payload = {}) => {
  const source = extractGivebutterPayloadSubject(payload);
  const purchaserEmail = normalizeEmailToken(
    source.email
    || source.purchaser_email
    || source.supporter_email
    || source.customer_email
    || source.contact?.email
    || source.supporter?.email
    || source.purchaser?.email
    || payload?.email
    || ""
  );
  const attendeeName = safeDirectoryString(
    source.name
    || source.attendee_name
    || source.supporter_name
    || source.customer_name
    || source.full_name
    || `${source.first_name || ""} ${source.last_name || ""}`.trim()
    || "",
    180
  );
  const eventId = normalizeDirectoryToken(
    source.event_id
    || source.eventId
    || source.campaign_code
    || source.campaign?.slug
    || source.campaign?.code
    || payload?.event_id
    || "",
    80
  );
  const sourceCampaignCode = normalizeRoomEventCreditCode(
    source.campaign_code
    || source.campaign?.code
    || source.campaign?.slug
    || ""
  );
  const fundCode = normalizeRoomEventCreditCode(
    source.fund_code
    || source.fundCode
    || source.fund_id
    || source.fundId
    || source.fund?.code
    || source.fund?.id
    || source.purchase?.fund_code
    || source.purchase?.fundId
    || source.purchase?.fund?.code
    || source.purchase?.fund?.id
    || payload?.fund_code
    || ""
  );
  const amountCents = extractGivebutterAmountCents(payload);
  const externalId = normalizeDirectoryToken(
    source.ticket_id
    || source.line_item_id
    || source.order_id
    || source.transaction_id
    || payload?.id
    || `${purchaserEmail}_${eventId}_${Date.now()}`
    || "",
    180
  );
  return {
    purchaserEmail,
    attendeeName,
    eventId,
    sourceCampaignCode,
    fundCode,
    amountCents,
    externalId,
    rawSubject: source,
  };
};

const chunkFirestoreUpdates = async (entries = [], applyChunk = async () => {}) => {
  const safeEntries = Array.isArray(entries) ? entries : [];
  for (let idx = 0; idx < safeEntries.length; idx += 400) {
    const chunk = safeEntries.slice(idx, idx + 400);
    if (!chunk.length) continue;
    await applyChunk(chunk);
  }
};

const normalizeHostSupportDropScope = (value = "") => {
  const token = normalizeDirectoryToken(value || "", 40);
  return token === "user" ? "user" : "room";
};

const normalizeHostSupportDropPayload = (input = {}) => {
  const amountDollars = Number(input?.amountDollars || 0);
  const fallbackAmountCents = Number.isFinite(amountDollars) && amountDollars > 0
    ? Math.round(amountDollars * 100)
    : 0;
  return {
    roomCode: normalizeRoomCode(input?.roomCode || ""),
    scope: normalizeHostSupportDropScope(input?.scope || input?.rewardScope || ""),
    targetUid: normalizeUidToken(input?.targetUid || ""),
    donorName: safeDirectoryString(input?.donorName || input?.buyerName || "", 180),
    anonymous: input?.anonymous === true,
    label: safeDirectoryString(input?.label || "", 120),
    points: clampNumber(input?.points, 0, 50000, 0),
    amountCents: clampNumber(input?.amountCents ?? fallbackAmountCents, 0, 100000000, 0),
    awardBadge: input?.awardBadge === true,
    celebrationStyle: normalizeSupportCelebrationStyle(
      input?.celebrationStyle || SUPPORT_CELEBRATION_STYLES.moneybagsBurst
    ),
  };
};

const matchGivebutterSupportConfig = ({
  config = {},
  normalized = {},
} = {}) => {
  const safeConfig = normalizeRoomEventCreditConfigRecord(config);
  if (!safeConfig.supportProvider || safeConfig.supportProvider !== "givebutter") return false;
  const offerCampaignCodes = safeConfig.supportOffers
    .map((offer) => normalizeRoomEventCreditCode(offer.supportCampaignCode || ""))
    .filter(Boolean);
  const hasCampaignMatch = normalized.sourceCampaignCode
    && (
      safeConfig.supportCampaignCode === normalized.sourceCampaignCode
      || offerCampaignCodes.includes(normalized.sourceCampaignCode)
    );
  if (hasCampaignMatch) return true;
  const hasFundMatch = normalized.fundCode
    && safeConfig.supportOffers.some((offer) => normalizeRoomEventCreditCode(offer.supportFundCode || "") === normalized.fundCode);
  if (hasFundMatch) return true;
  if (!safeConfig.supportCampaignCode && !offerCampaignCodes.length && normalized.eventId && safeConfig.eventId === normalized.eventId) {
    return true;
  }
  return false;
};

const resolveGivebutterSupportReward = ({
  config = {},
  normalized = {},
  payload = {},
} = {}) => {
  const safeConfig = normalizeRoomEventCreditConfigRecord(config);
  const amountCents = clampNumber(
    normalized.amountCents || extractGivebutterAmountCents(payload),
    0,
    100000000,
    0
  );
  const campaignCode = normalizeRoomEventCreditCode(normalized.sourceCampaignCode || "");
  const fundCode = normalizeRoomEventCreditCode(normalized.fundCode || "");
  const scoredOffers = safeConfig.supportOffers
    .map((offer) => {
      const offerCampaignCode = normalizeRoomEventCreditCode(offer.supportCampaignCode || safeConfig.supportCampaignCode || "");
      const offerFundCode = normalizeRoomEventCreditCode(offer.supportFundCode || "");
      const offerAmountCents = Math.round(clampNumber(offer.amount || 0, 0, 500, 0) * 100);
      if (campaignCode && offer.supportCampaignCode && offerCampaignCode !== campaignCode) return null;
      if (fundCode && offerFundCode && offerFundCode !== fundCode) return null;
      let score = 0;
      if (fundCode && offerFundCode === fundCode) score += 100;
      if (campaignCode && offerCampaignCode === campaignCode) score += offer.supportCampaignCode ? 40 : 10;
      if (amountCents && offerAmountCents === amountCents) score += 20;
      if (!score) return null;
      return { offer, score };
    })
    .filter(Boolean)
    .sort((a, b) => b.score - a.score);

  const bestOffer = scoredOffers[0];
  if (bestOffer) {
    const tiedOffers = scoredOffers.filter((entry) => entry.score === bestOffer.score);
    if (tiedOffers.length === 1) {
      return {
        offerId: bestOffer.offer.id || "",
        label: safeDirectoryString(bestOffer.offer.label || "Support Offer", 120) || "Support Offer",
        pointsGranted: clampNumber(bestOffer.offer.points || 0, 0, 100000, 0),
        rewardScope: normalizeSupportRewardScope(bestOffer.offer.rewardScope || "buyer"),
        awardBadge: bestOffer.offer.awardBadge === true,
        amountCents,
        celebrationStyle: safeConfig.supportCelebrationStyle,
      };
    }
  }

  return {
    offerId: "",
    label: safeDirectoryString(safeConfig.supportLabel || safeConfig.eventLabel || "Room Support", 120) || "Room Support",
    pointsGranted: clampNumber(safeConfig.supportPoints, 0, 100000, 0),
    rewardScope: "room",
    awardBadge: safeConfig.supportBadge !== false,
    amountCents,
    celebrationStyle: safeConfig.supportCelebrationStyle,
  };
};

exports.givebutterWebhook = onRequest(
  { secrets: [GIVEBUTTER_WEBHOOK_SECRET] },
  async (req, res) => {
    if (req.method !== "POST") {
      res.status(405).send("Method not allowed");
      return;
    }

    const signature = readGivebutterSignature(req);
    const webhookSecret = GIVEBUTTER_WEBHOOK_SECRET.value();
    if (!verifyGivebutterWebhookSignature({
      rawBody: req.rawBody,
      signature,
      secret: webhookSecret,
    })) {
      console.error("Givebutter webhook signature failed.");
      res.status(400).send("Webhook Error");
      return;
    }

    const payload = isPlainObject(req.body) ? req.body : {};
    const eventType = normalizeDirectoryToken(payload.type || payload.event || "", 80) || "unknown";
    const normalized = normalizeGivebutterWebhookPayload(payload);
    if (!normalized.purchaserEmail || !normalized.externalId) {
      res.json({ received: true, ignored: true, reason: "missing_subject" });
      return;
    }

    const db = admin.firestore();
    const supportEventRef = db.collection(SUPPORT_PURCHASE_EVENTS_COLLECTION).doc(
      buildEventAttendeeEntitlementDocId({
        sourceProvider: "givebutter_support",
        externalId: normalized.externalId,
      })
    );
    const [eventConfigQuery, supportConfigQuery] = await Promise.all([
      db.collection(ROOM_EVENT_CREDIT_CONFIGS_COLLECTION)
        .where("sourceProvider", "==", "givebutter")
        .limit(50)
        .get(),
      db.collection(ROOM_EVENT_CREDIT_CONFIGS_COLLECTION)
        .where("supportProvider", "==", "givebutter")
        .limit(50)
        .get(),
    ]);
    const matchingSupportConfig = supportConfigQuery.docs
      .map((docSnap) => ({ id: docSnap.id, ...(docSnap.data() || {}) }))
      .find((entry) => matchGivebutterSupportConfig({ config: entry, normalized }));
    if (matchingSupportConfig) {
      const existingSupport = await supportEventRef.get();
      if (existingSupport.exists) {
        res.json({ received: true, duplicate: true, supportPurchase: true });
        return;
      }
      const supportConfig = normalizeRoomEventCreditConfigRecord(matchingSupportConfig);
      const roomCode = normalizeRoomCode(matchingSupportConfig.roomCode || matchingSupportConfig.id || "");
      const supportReward = resolveGivebutterSupportReward({
        config: supportConfig,
        normalized,
        payload,
      });
      const pointsGranted = clampNumber(supportReward.pointsGranted, 0, 100000, 0);
      const label = safeDirectoryString(supportReward.label || supportConfig.supportLabel || supportConfig.eventLabel || "Room Support", 120) || "Room Support";
      const rewardScope = normalizeSupportRewardScope(supportReward.rewardScope || "room");
      const amountCents = clampNumber(supportReward.amountCents, 0, 100000000, 0);
      let matchedBuyerUid = "";
      let matchedBuyerAvatar = "";
      if (roomCode) {
        const usersSnap = await getRootRef()
          .collection("room_users")
          .where("roomCode", "==", roomCode)
          .get();
        if (!usersSnap.empty) {
          const batch = db.batch();
          usersSnap.docs.forEach((docSnap) => {
            const roomUserData = docSnap.data() || {};
            const roomUserEmail = normalizeEmailToken(roomUserData.email || "");
            const safeUid = normalizeUidToken(roomUserData.uid || "") || normalizeUidToken(docSnap.id.split("_").pop() || "");
            const isBuyer = !!roomUserEmail && roomUserEmail === normalized.purchaserEmail;
            if (!matchedBuyerUid && isBuyer) {
              matchedBuyerUid = safeUid;
              matchedBuyerAvatar = safeDirectoryString(roomUserData.avatar || "", 24);
            }
            const shouldGrantRoomPoints = pointsGranted > 0 && (rewardScope === "room" || rewardScope === "buyer_and_room");
            const shouldGrantBuyerPoints = pointsGranted > 0 && rewardScope === "buyer" && isBuyer;
            if (shouldGrantRoomPoints || shouldGrantBuyerPoints) {
              batch.update(docSnap.ref, {
                points: admin.firestore.FieldValue.increment(pointsGranted),
              });
            }
            if (isBuyer) {
              const buyerRoomUserPatch = {
                roomBoosted: true,
                lastSupportPurchaseAmountCents: amountCents,
                lastSupportPurchaseProvider: "givebutter",
                lastSupportPurchaseAt: admin.firestore.FieldValue.serverTimestamp(),
              };
              if (supportReward.awardBadge) {
                buyerRoomUserPatch.roomBoostBadge = true;
                buyerRoomUserPatch.roomBoosts = admin.firestore.FieldValue.increment(1);
              }
              batch.set(docSnap.ref, buyerRoomUserPatch, { merge: true });
            }
          });
          await batch.commit();
        }
      }
      if (matchedBuyerUid && pointsGranted > 0 && (rewardScope === "buyer" || rewardScope === "buyer_and_room")) {
        await db.collection("users").doc(matchedBuyerUid).set({
          uid: matchedBuyerUid,
          pointsBalance: admin.firestore.FieldValue.increment(pointsGranted),
          updatedAt: admin.firestore.FieldValue.serverTimestamp(),
        }, { merge: true });
      }
      if (roomCode) {
        await getRootRef().collection("rooms").doc(roomCode).set({
          purchaseCelebration: buildRoomPurchaseCelebrationPayload({
            id: normalized.externalId,
            buyerName: normalized.attendeeName || "Supporter",
            buyerAvatar: matchedBuyerAvatar,
            label,
            points: pointsGranted,
            badgeAwarded: supportReward.awardBadge === true,
            sourceProvider: "givebutter",
            rewardScope,
            amountCents,
            celebrationStyle: supportReward.celebrationStyle,
          }),
        }, { merge: true });
        await getRootRef().collection("activities").add({
          roomCode,
          user: normalized.attendeeName || "SUPPORTER",
          text: `${normalized.attendeeName || "A supporter"} unlocked ${label}${pointsGranted > 0
            ? rewardScope === "room"
              ? ` - everyone +${pointsGranted} pts`
              : ` - +${pointsGranted} pts`
            : ""}`,
          icon: "$",
          timestamp: admin.firestore.FieldValue.serverTimestamp(),
        });
      }
      await supportEventRef.set({
        sourceProvider: "givebutter",
        roomCode: roomCode || null,
        normalizedEmail: normalized.purchaserEmail,
        attendeeName: normalized.attendeeName,
        sourceCampaignCode: normalized.sourceCampaignCode || supportConfig.supportCampaignCode,
        fundCode: normalized.fundCode || null,
        label,
        pointsGranted,
        amountCents,
        rewardScope,
        awardBadge: supportReward.awardBadge === true,
        supportOfferId: supportReward.offerId || null,
        matchedUid: matchedBuyerUid || null,
        pointsFulfilledAt: matchedBuyerUid && pointsGranted > 0 && (rewardScope === "buyer" || rewardScope === "buyer_and_room")
          ? admin.firestore.FieldValue.serverTimestamp()
          : null,
        externalId: normalized.externalId,
        rawPayload: payload,
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
        createdAt: admin.firestore.FieldValue.serverTimestamp(),
      }, { merge: true });
      if (roomCode) {
        await syncSelfServeAuctionStateServer({
          rootRef: getRootRef(),
          roomCode,
        });
      }
      res.json({
        received: true,
        supportPurchase: true,
        roomCode: roomCode || null,
      });
      return;
    }

    const entitlementRef = db.collection(EVENT_ATTENDEE_ENTITLEMENTS_COLLECTION).doc(
      buildEventAttendeeEntitlementDocId({
        sourceProvider: "givebutter",
        externalId: normalized.externalId,
      })
    );
    const matchingConfig = eventConfigQuery.docs
      .map((docSnap) => ({ id: docSnap.id, ...(docSnap.data() || {}) }))
      .find((entry) => {
        const config = normalizeRoomEventCreditConfigRecord(entry);
        if (normalized.eventId && config.eventId === normalized.eventId) return true;
        if (normalized.sourceCampaignCode && config.sourceCampaignCode && config.sourceCampaignCode === normalized.sourceCampaignCode) return true;
        return false;
      });
    const resolvedConfig = matchingConfig
      ? normalizeRoomEventCreditConfigRecord(matchingConfig)
      : normalizeRoomEventCreditConfigRecord({
        enabled: true,
        eventId: normalized.eventId || "custom_event",
        eventLabel: normalized.eventId || "Custom Event Credits",
        sourceProvider: "givebutter",
        sourceCampaignCode: normalized.sourceCampaignCode,
      });
    const reward = inferGivebutterEntitlementRewards({
      payload,
      eventId: normalized.eventId || resolvedConfig.eventId,
      config: resolvedConfig,
    });

    await entitlementRef.set({
      sourceProvider: "givebutter",
      webhookEventType: eventType,
      normalizedEmail: normalized.purchaserEmail,
      attendeeName: normalized.attendeeName,
      eventId: reward.eventId || resolvedConfig.eventId,
      sourceCampaignCode: normalized.sourceCampaignCode || resolvedConfig.sourceCampaignCode,
      ticketTier: reward.ticketTier,
      pointsGranted: reward.pointsGranted,
      vipEntitled: reward.vipEntitled,
      skipLineEntitled: reward.skipLineEntitled,
      matchedUid: null,
      matchedRoomCode: null,
      claimed: false,
      externalId: normalized.externalId,
      rawPayload: payload,
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      createdAt: admin.firestore.FieldValue.serverTimestamp(),
    }, { merge: true });

    res.json({
      received: true,
      entitlementId: entitlementRef.id,
      eventId: reward.eventId || resolvedConfig.eventId,
    });
  }
);

exports.verifyAppleReceipt = onCall(
  { cors: true },
  async (request) => {
    const callerUid = requireAuth(request);
    const transactionId = request.data?.transactionId || "";
    const productId = request.data?.productId || "";
    const userUid = request.data?.userUid || "";
    ensureString(transactionId, "transactionId");
    ensureString(productId, "productId");
    ensureString(userUid, "userUid");
    if (userUid !== callerUid) {
      throw new HttpsError("permission-denied", "userUid must match authenticated user.");
    }

    // TODO: Wire App Store Server API with JWT auth and verify transaction.
    // After verification, grant entitlements and store a transaction record
    // to prevent duplicate grants.
    throw new HttpsError(
      "failed-precondition",
      "Apple IAP verification is currently unavailable."
    );
  }
);
